INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C1','kor',4,2,'u4',2,'이 단원에서 배울 두 가지 — 작품을 읽고 생각이나 느낌을 나누기 · 질문으로 내가 어떻게 읽었는지 되돌아보기',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C2','kor',4,2,'u4',2,'읽는 동안 한 일 — 같은 책을 같은 시간 읽어도 읽는 동안 스스로 묻고 다 읽고 정리하면 남는 것이 달라짐(건희·주서) — 빨리·끝까지·여러 번 읽기가 잘 읽기는 아님',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C3','kor',4,2,'u4',2,'읽다가 겪는 어려움 — 무엇을 알려 주는 글인지 모름 · 인물이 왜 그랬는지 모름 · 다 읽었는데 남는 것이 없음 — 책 무게·표지 색은 읽기의 어려움이 아님',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C4','kor',4,2,'u4',2,'질문으로 되돌아보기 — 글을 읽으며 스스로 질문을 던져 내가 잘 이해하고 있는지 점검하는 것이 읽기 과정을 되돌아보는 것',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C5','kor',4,2,'u4',2,'글의 종류와 질문 — 시나 이야기 — 마음에 남는 장면 · 설명하는 글 — 무엇을 어떻게 알려 주나 · 의견 글 — 이유가 알맞은가',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C6','kor',4,2,'u4',2,'질문은 골라 쓰는 것 — 질문은 개수를 채우는 것이 아니라 글과 그때의 나에게 필요한 것을 골라 씀 — 많을수록 · 빠짐없이 다 ✗',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C7','kor',4,2,'u4',2,'시에는 채워 넣을 자리 — 시는 짧아서 읽는 사람이 채워 넣을 자리가 많음 — 그래서 같은 시에서도 떠오르는 장면이 사람마다 다름',ARRAY['[4국05-03][4국05-05]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C8','kor',4,2,'u4',2,'시 「길게 불러 보면」의 내용 — 고래를 길게 부르면 오래가, 소리를 길게 부르면 오리가 들림 — 낱말 속에 숨어 있던 것들이 고개를 듦',ARRAY['[4국05-03][4국05-05]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C9','kor',4,2,'u4',2,'다른 장면은 틀린 것이 아님 — 은별(커다란 고래)과 건희(말놀이하는 우리 반)처럼 겪은 일이 다르면 떠오르는 장면이 다름',ARRAY['[4국05-03][4국05-05]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C10','kor',4,2,'u4',2,'느낌을 나누는 방법 — 떠오른 장면과 그 까닭을 함께 · 마음에 든 줄을 짚어 · 말·표정·몸짓·그림 가운데 편한 방법으로 — 다수결로 정하거나 따라 말하지 않음',ARRAY['[4국05-03][4국05-05]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C11','kor',4,2,'u4',2,'다른 느낌을 들었을 때 — 「왜 그 색이 떠올랐는지 말해 줄래?」처럼 까닭을 물음 — 「틀렸어」도 「나도 바꿀게」도 아님',ARRAY['[4국05-03][4국05-05]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C12','kor',4,2,'u4',2,'글자를 늘이면 숨는 낱말 — 앞 글자의 소리를 길게 늘이면 뒤에 다른 낱말이 나타남(수박→우박 · 하마→아마) — 남는 소리가 낱말이 아니면 숨은 낱말이 없음',ARRAY['[4국05-03][4국05-05]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C13','kor',4,2,'u4',2,'나누는 까닭은 넓게 보기 — 서로 다른 느낌을 들으면 내가 못 본 면을 볼 수 있음 — 나눈 뒤 모두 같은 느낌이 되어야 하는 것이 아님',ARRAY['[4국05-03][4국05-05]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C14','kor',4,2,'u4',4,'말과 행동에서 자라는 느낌 — 이야기 속 인물의 말과 행동을 따라가다 보면 내 마음에도 생각이나 느낌이 생김',ARRAY['[4국05-03][4국05-05]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C15','kor',4,2,'u4',4,'「말하지 못한 말」 ① 내용 — 형준이는 해설을 하고 싶었지만 그 말을 못 하고 「소품 할게」 하고 웃음',ARRAY['[4국05-03][4국05-05]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C16','kor',4,2,'u4',4,'「말하지 못한 말」 ② 내용 — 배경 그림을 맡은 친구가 입을 닫은 뒤 아무도 먼저 의견을 내지 않아 연습이 자꾸 끊김',ARRAY['[4국05-03][4국05-05]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C17','kor',4,2,'u4',4,'이야기 속 낱말 — 멋쩍다(어색하고 쑥스럽다) · 머뭇거리다(선뜻 하지 못하고 멈칫하다) · 우물쭈물하다(분명히 하지 못하고 자꾸 망설이다) — 쓰인 줄의 앞뒤로 짐작',ARRAY['[4국05-03][4국05-05]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C18','kor',4,2,'u4',4,'말과 행동으로 성격 짐작 — 손을 반쯤 들었다 내림(형준 — 하고 싶은 말을 삼킴) · 본 대로 바로 말함(수지 — 상대 마음은 살피지 않음) — 이름·겉모습·한 장면만으로 단정하지 않음',ARRAY['[4국05-03][4국05-05]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C19','kor',4,2,'u4',4,'인물에 어울리는 말투 — 형준 — 천천히, 말끝이 흐려지게 · 수지 — 망설임 없이 또렷하고 빠르게(비웃는 말투 ✗)',ARRAY['[4국05-03][4국05-05]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C20','kor',4,2,'u4',4,'역할놀이 장면 고르기 — 어느 장면을 골라도 좋고 고른 까닭을 말할 수 있으면 됨 — 정답 장면은 없음',ARRAY['[4국05-03][4국05-05]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C21','kor',4,2,'u4',4,'역할놀이 하는 차례와 태도 — 장면 정하기 → 역할 나누기(해설자도) → 연습하기 → 친구들 앞에서 해 보기 · 다른 모둠 차례에는 끝까지 지켜봄',ARRAY['[4국05-03][4국05-05]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C22','kor',4,2,'u4',4,'역할놀이를 볼 때의 기준 — 인물의 말과 행동에 어울리는 말투인가 · 인물에 대한 생각이나 느낌이 드러났는가 · 새로 든 생각 — 웃기기·목소리 크기 ✗',ARRAY['[4국05-03][4국05-05]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C23','kor',4,2,'u4',4,'자신과 관련짓는 질문 — 「형준이처럼 하고 싶은 말을 못 한 적이 있나요?」처럼 작품에 대한 친구의 생각을 알아보는 질문',ARRAY['[4국05-03][4국05-05]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C24','kor',4,2,'u4',4,'상처 주지 않는 쪽지 — 「너는 ~하잖아」 대신 「나는 ~라고 생각했어」로 받는 사람이 상처받지 않게 씀',ARRAY['[4국05-03][4국05-05]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C25','kor',4,2,'u4',4,'둘 다 한 가지씩 — 형준이는 하고 싶은 말을 하지 않았고 수지는 상대 마음을 살피지 않았음 — 한 사람만 잘못한 것이 아님(우석이의 말)',ARRAY['[4국05-03][4국05-05]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C26','kor',4,2,'u4',7,'읽기 과정 셋 — 읽기 전 · 읽기 중 · 읽기 후로 나누어 볼 수 있고 단계마다 하는 일이 다름',ARRAY['[4국02-03]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C27','kor',4,2,'u4',7,'읽기 전에 하는 일 — 제목과 차례를 보고 내용 짐작하기 · 그 주제에 대해 이미 아는 것 떠올리기',ARRAY['[4국02-03]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C28','kor',4,2,'u4',7,'읽기 중에 하는 일 — 짐작한 것과 맞는지 확인하기 · 각 부분에서 가장 중요한 문장 찾기 · 새로 알게 된 것 살피기',ARRAY['[4국02-03]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C29','kor',4,2,'u4',7,'읽기 후에 하는 일 — 읽은 내용을 짧게 간추리기 · 더 알고 싶어진 것 떠올리기',ARRAY['[4국02-03]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C30','kor',4,2,'u4',7,'단계에 알맞은 질문 — 읽기 전 질문은 읽지 않고도 답할 수 있고, 읽기 후 질문은 끝까지 읽어야 답할 수 있음 — 읽기와 상관없는 질문(도서관 위치·줄 수)은 아님',ARRAY['[4국02-03]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C31','kor',4,2,'u4',7,'「민들레 씨앗의 여행」 내용 — 하얀 공은 씨앗이 모인 것 · 씨앗의 가는 털이 낙하산처럼 공기를 받아 바람을 타고 멀리 퍼짐',ARRAY['[4국02-03]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C32','kor',4,2,'u4',7,'설명하는 글에 어울리는 질문 — 무엇에 대해 알려 주나 · 새로 알게 된 것 · 중요한 문장 — 의견 글이나 시에 어울리는 질문은 뺌',ARRAY['[4국02-03]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C33','kor',4,2,'u4',7,'그때그때 골라 쓰기 — 짧은 안내문과 두꺼운 책, 재미로 읽기와 조사하려고 읽기는 필요한 질문이 다름 — 매번 전부 다 하는 것이 아님',ARRAY['[4국02-03]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C34','kor',4,2,'u4',9,'설명하는 글 — 어떤 것을 알기 쉽게 알려 주는 글 — 조립 설명서·안내문·조리법도 설명하는 글',ARRAY['[4국02-03]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C35','kor',4,2,'u4',9,'「지렁이가 하는 일」 내용 — 흙을 먹으며 땅속을 지나다님 · 지나간 굴로 공기와 물이 스며듦 · 똥이 흙에 양분을 섞어 식물이 자라기 좋은 땅이 됨',ARRAY['[4국02-03]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C36','kor',4,2,'u4',9,'설명하는 글의 낱말 — 양분(살아가고 자라는 데 필요한 성분) · 스며들다(속으로 배어 들어가다) · 뒤섞이다(여럿이 한데 마구 섞이다)',ARRAY['[4국02-03]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C37','kor',4,2,'u4',9,'중심 문장 찾기 — 그 문장이 없으면 그 부분의 뜻이 통하지 않는 문장 — 나머지는 그것을 자세히 풀어 줌(첫 문장·긴 문장이 늘 중심은 아님)',ARRAY['[4국02-03]']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C38','kor',4,2,'u4',9,'간추리기 — 각 부분의 중심 문장을 모아 짧게 정리하는 것 — 모두 옮겨 적기 ✗ · 재미있는 부분만 ✗',ARRAY['[4국02-03]']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C39','kor',4,2,'u4',9,'솔직한 자기 점검 — 내가 어떻게 읽었는지 솔직하게 표시하고, 표시하지 못한 줄을 다음에 해 볼 일로 삼음(점수 없음)',ARRAY['[4국02-03]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C40','kor',4,2,'u4',9,'새로 안 것과 더 알고 싶은 것 — 글과 연결하기 — 글에서 새로 알게 된 것과 읽고 나서 더 알고 싶어진 것을 가려 말함',ARRAY['[4국02-03]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C41','kor',4,2,'u4',11,'의견을 제시하는 글 — 어떤 문제에 대한 글쓴이의 생각을 밝혀 쓴 글 — 읽는 사람이 동의할지 말지 스스로 정할 수 있음',ARRAY['[4국02-03]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C42','kor',4,2,'u4',11,'제목으로 알 수 있는 것 — 의견이 드러난 제목으로 무엇을 하자고 할지 짐작함 — 이유가 몇 개인지·글쓴이가 누구인지는 읽어야 앎',ARRAY['[4국02-03]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C43','kor',4,2,'u4',11,'글쓴이의 의견 찾기 — 「저는 ~라고 생각합니다」처럼 바라는 것을 밝힌 문장 — 인사·문제 상황·실천 권유와 구별',ARRAY['[4국02-03]']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C44','kor',4,2,'u4',11,'의견을 받치는 이유 찾기 — 「첫째, 둘째」처럼 의견을 받치는 까닭 — 문제 상황(물건이 쌓여 있음)이나 실천 권유(오늘 집에 가서 살펴보자)와 구별',ARRAY['[4국02-03]']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C45','kor',4,2,'u4',11,'이유가 의견과 이어지는가 — 그 이유가 의견대로 하면 좋은 점인지 따짐(글씨 연습 ✗) — 내가 찬성하든 반대하든 답이 같아야 함',ARRAY['[4국02-03]']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C46','kor',4,2,'u4',11,'실렸다고 언제나 옳지 않음 — 글에 실린 의견은 글쓴이의 생각 — 깔끔하다고 언제나 옳은 것도, 무조건 의심할 것도 아니고 이유를 따져 봄',ARRAY['[4국02-03]']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C47','kor',4,2,'u4',11,'글쓴이와 내 의견 견주기 — 같은 곳과 다른 곳을 찾고, 다르면 내 이유를 마련함 — 그대로 따르기도 무조건 반대하기도 아님',ARRAY['[4국02-03]']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C48','kor',4,2,'u4',11,'의견 글을 읽을 때의 질문 — 읽기 전 — 무엇을 하자는 글일까 · 읽기 중 — 의견은 무엇이고 이유가 이어지는가 · 읽기 후 — 내 생각과 어디가 같고 다른가',ARRAY['[4국02-03]']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C49','kor',4,2,'u4',11,'점검표는 나를 위해 — 「아니요」가 나온 곳으로 돌아가 다시 읽음 — 모두 「예」가 되게 답하기나 빨리 채우기가 목적이 아님',ARRAY['[4국02-03]']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C50','kor',4,2,'u4',13,'느낌을 나타내는 여러 방법 — 즉흥극 · 그림 · 편지 · 노래 · 내가 생각한 다른 방법 — 방법에는 등수가 없음',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C51','kor',4,2,'u4',13,'다른 방법을 고른 친구에게 — 「왜 그 방법으로 나타냈는지 궁금해.」처럼 까닭을 묻고, 잘한 부분을 칭찬하고 격려함',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C52','kor',4,2,'u4',13,'질문 카드에 알맞은 질문 — 답하면 내가 어떻게 읽었는지 드러나는 질문(짐작과 같았나 · 새로 안 것) — 줄 수·글쓴이 나이 ✗',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C53','kor',4,2,'u4',13,'질문 놀이에서 답하기 — 그렇게 읽었다고 말할 수 있으면 됨 — 많이 받기·빨리 답하기를 겨루는 놀이가 아니고, 답을 못 하면 그곳이 다시 읽을 자리',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C54','kor',4,2,'u4',13,'시 「받아쓰기」의 내용 — 시험지를 받으면 아는 글자도 낯설어지고 연필 끝에서 미끄러지지만, 집에 돌아와 다시 쓰면 또박또박 잘 써짐',ARRAY['[4국05-03][4국05-05][4국02-03]']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C55','kor',4,2,'u4',13,'사물에는 높임말을 쓰지 않음 — 물건이나 값에는 「-시-」를 붙이지 않음(색연필이 다 팔렸어요 · 국이 식었어요) — 사람을 높일 때 씀',ARRAY['기초 다지기(높임 표현·우리말·글씨 — 성취기준 번호 확인 필요)']::text[],55) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C56','kor',4,2,'u4',13,'우리나라 — 나라와 민족은 남의 나라보다 낮출 수 없어 「저희 나라」가 아니라 「우리나라」라고 함',ARRAY['기초 다지기(높임 표현·우리말·글씨 — 성취기준 번호 확인 필요)']::text[],56) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C57','kor',4,2,'u4',13,'외국어 대신 우리말 — 바꿔 쓸 우리말이 있으면 우리말로(메모→쪽지 · 스케줄→일정 · 체크하다→표시하다) — 모르는 사람도 알아들음',ARRAY['기초 다지기(높임 표현·우리말·글씨 — 성취기준 번호 확인 필요)']::text[],57) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u4-C58','kor',4,2,'u4',13,'겹받침 ㄻ — ㄹ과 ㅁ이 같은 크기로 나란히(앎 · 삶다 · 옮기다 · 젊은이) — ㄺ·ㄼ·ㄵ 같은 다른 겹받침과 구별',ARRAY['기초 다지기(높임 표현·우리말·글씨 — 성취기준 번호 확인 필요)']::text[],58) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X01','kor',4,'u4',ARRAY['K4-2-u4-C1']::text[],'이 단원에서 배울 내용을 책을 빨리 많이 읽는 법이나 단원과 상관없는 것으로 여긴다','느낌 나누기 · 되돌아보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X02','kor',4,'u4',ARRAY['K4-2-u4-C2']::text[],'끝까지·빨리·여러 번 읽기만 하면 잘 읽은 것이라고 여기고 읽는 동안 한 일은 살피지 않는다','읽는 동안 무엇을 했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X03','kor',4,'u4',ARRAY['K4-2-u4-C3']::text[],'책 무게나 표지 색처럼 읽기와 상관없는 불편을 읽기의 어려움으로 고른다','읽었는데 잘 모르겠다?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X04','kor',4,'u4',ARRAY['K4-2-u4-C4']::text[],'질문은 남에게만 하는 것이라 여기거나 읽기를 점검하는 일과 상관없다고 여긴다','스스로 묻고 점검해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X05','kor',4,'u4',ARRAY['K4-2-u4-C5','K4-2-u4-C32','K4-2-u4-C48']::text[],'글의 종류와 그 글에 어울리는 질문을 엇갈리게 짝짓는다','무엇을 하려고 쓴 글?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X06','kor',4,'u4',ARRAY['K4-2-u4-C6','K4-2-u4-C53']::text[],'질문을 많이 만들수록 잘 읽은 것이라고 여긴다','개수보다 쓸모') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X07','kor',4,'u4',ARRAY['K4-2-u4-C6','K4-2-u4-C33']::text[],'읽기 전·중·후 활동을 언제나 빠짐없이 다 해야 잘 읽은 것이라고 여긴다','그때그때 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X08','kor',4,'u4',ARRAY['K4-2-u4-C7','K4-2-u4-C9']::text[],'같은 시에서는 떠오르는 장면이 하나로 정해져 있고, 다른 장면은 잘못 읽은 것이라고 여긴다','채워 넣을 자리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X09','kor',4,'u4',ARRAY['K4-2-u4-C8']::text[],'시에서 늘인 낱말 속에 들리는 것을 엇갈리게 읽는다','소리 내어 늘여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X10','kor',4,'u4',ARRAY['K4-2-u4-C10']::text[],'가장 많이 나온 느낌으로 반의 느낌이나 시의 느낌을 정한다','수로 정하지 않아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X11','kor',4,'u4',ARRAY['K4-2-u4-C10','K4-2-u4-C13']::text[],'친구가 먼저 말한 느낌이나 고른 방법을 그대로 따라 한다','내 느낌을 말해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X12','kor',4,'u4',ARRAY['K4-2-u4-C11','K4-2-u4-C51']::text[],'나와 다른 느낌이나 방법을 들으면 틀렸다고 말한다','다를 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X13','kor',4,'u4',ARRAY['K4-2-u4-C11']::text[],'다른 느낌을 들으면 내 느낌을 그쪽으로 바꾸어야 한다고 여긴다','까닭을 물어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X14','kor',4,'u4',ARRAY['K4-2-u4-C10']::text[],'느낌은 정답이 없으니 까닭 없이 아무렇게나 말해도 된다고 여긴다','까닭을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X15','kor',4,'u4',ARRAY['K4-2-u4-C12']::text[],'늘였을 때 남는 소리가 낱말이 아닌데도 숨은 낱말이 있다고 고르거나 늘이는 자리를 엇갈린다','남는 소리가 낱말?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X16','kor',4,'u4',ARRAY['K4-2-u4-C13']::text[],'느낌을 나눈 뒤에는 모두 같은 느낌이 되어야 한다고 여긴다','넓게 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X17','kor',4,'u4',ARRAY['K4-2-u4-C14','K4-2-u4-C15']::text[],'인물이 겉으로 한 말만 보고 속마음을 놓쳐 이야기 내용을 잘못 안다(형준이는 소품이 좋아서)','손을 왜 내렸나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X18','kor',4,'u4',ARRAY['K4-2-u4-C16']::text[],'연습이 끊긴 까닭을 이야기와 상관없는 것으로 고른다','말이 사라졌어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X19','kor',4,'u4',ARRAY['K4-2-u4-C17']::text[],'멋쩍다 · 머뭇거리다 · 우물쭈물하다의 뜻을 엇갈리게 안다','쓰인 줄을 다시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X20','kor',4,'u4',ARRAY['K4-2-u4-C14','K4-2-u4-C18']::text[],'인물의 성격을 말과 행동이 아니라 이름·겉모습·한 장면만 보고 정한다','말과 행동을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X21','kor',4,'u4',ARRAY['K4-2-u4-C18','K4-2-u4-C19','K4-2-u4-C25']::text[],'수지를 친구를 일부러 놀리고 괴롭히려는 나쁜 인물로 단정한다','본 대로 바로 말했어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X22','kor',4,'u4',ARRAY['K4-2-u4-C19']::text[],'인물의 말과 행동에 어울리지 않는 말투를 고른다(형준 — 크고 빠르게·거칠게)','말끝이 흐려져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X23','kor',4,'u4',ARRAY['K4-2-u4-C20']::text[],'역할놀이로 나타낼 장면에는 정답이 하나 있다고 여기거나 까닭 없이 고른다','까닭만 있으면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X24','kor',4,'u4',ARRAY['K4-2-u4-C22']::text[],'가장 웃긴 역할놀이가 가장 잘한 역할놀이라고 여긴다','웃기기 대회 ✗') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X25','kor',4,'u4',ARRAY['K4-2-u4-C22']::text[],'목소리가 클수록 잘한 역할놀이라고 여긴다','마음이 드러났나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X26','kor',4,'u4',ARRAY['K4-2-u4-C21']::text[],'역할놀이 차례를 엇갈리게 알거나 다른 모둠 차례에 끼어든다','정하기 → 나누기 → 연습 → 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X27','kor',4,'u4',ARRAY['K4-2-u4-C24']::text[],'「너는 ~하잖아」처럼 받는 사람이 상처받는 쪽지를 쓴다','나는 ~라고 생각했어') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X28','kor',4,'u4',ARRAY['K4-2-u4-C23','K4-2-u4-C52']::text[],'작품이나 읽기와 상관없는 것(나이·옷 색·날짜)을 묻는 질문을 만든다','읽은 것을 묻나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X29','kor',4,'u4',ARRAY['K4-2-u4-C25']::text[],'이야기 속 다툼에서 한 사람만 잘못했다고 여긴다','둘 다 한 가지씩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X30','kor',4,'u4',ARRAY['K4-2-u4-C26','K4-2-u4-C27','K4-2-u4-C28','K4-2-u4-C29']::text[],'읽기 전·중·후와 그 단계에서 하는 일을 엇갈리게 짝짓는다','펴기 전 · 읽는 동안 · 다 읽고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X31','kor',4,'u4',ARRAY['K4-2-u4-C30']::text[],'읽기 전 질문으로 끝까지 읽어야 답할 수 있는 질문을 고르거나, 읽기 후 질문을 제목만으로 답할 수 있다고 여긴다','지금 답할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X32','kor',4,'u4',ARRAY['K4-2-u4-C30','K4-2-u4-C52']::text[],'도서관 위치·글의 줄 수처럼 읽기와 상관없는 질문을 읽기 과정 질문으로 고른다','내 읽기가 드러나나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X33','kor',4,'u4',ARRAY['K4-2-u4-C31']::text[],'「민들레 씨앗의 여행」 내용을 글과 다르게 안다(꽃이 시든 것·걸어 다님)','털이 낙하산처럼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X34','kor',4,'u4',ARRAY['K4-2-u4-C34']::text[],'설명하는 글을 느낌을 적은 글이나 일기, 시키는 글로 여긴다','알기 쉽게 알려 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X35','kor',4,'u4',ARRAY['K4-2-u4-C35']::text[],'설명하는 글에서 읽은 내용을 글과 다르게 안다','그 줄을 다시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X36','kor',4,'u4',ARRAY['K4-2-u4-C36']::text[],'양분 · 스며들다 · 뒤섞이다의 뜻을 엇갈리게 안다','앞뒤 문장으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X37','kor',4,'u4',ARRAY['K4-2-u4-C37']::text[],'첫 문장이나 긴 문장, 곁가지 문장을 중심 문장으로 고른다','없으면 뜻이 안 통하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X38','kor',4,'u4',ARRAY['K4-2-u4-C38']::text[],'글에 나온 문장을 모두 옮겨 적는 것을 간추리기라고 여긴다','짧게 정리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X39','kor',4,'u4',ARRAY['K4-2-u4-C38']::text[],'가장 재미있었던 부분만 적는 것을 간추리기라고 여긴다','중심 문장을 모아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X40','kor',4,'u4',ARRAY['K4-2-u4-C39','K4-2-u4-C49']::text[],'점검표나 자기 점검을 잘 보이려고 모두 「예」가 되게 표시한다','나를 위해 솔직하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X41','kor',4,'u4',ARRAY['K4-2-u4-C49']::text[],'점검표는 빨리 채우는 것이 가장 중요하다고 여긴다','다시 읽을 곳 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X42','kor',4,'u4',ARRAY['K4-2-u4-C41']::text[],'의견을 제시하는 글을 읽는 사람이 반드시 따라야 하는 글이나 겪은 일을 적은 글로 여긴다','글쓴이의 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X43','kor',4,'u4',ARRAY['K4-2-u4-C42']::text[],'제목만 보고 이유가 몇 개인지나 글쓴이가 누구인지까지 알 수 있다고 여긴다','제목엔 의견만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X44','kor',4,'u4',ARRAY['K4-2-u4-C43']::text[],'글쓴이의 의견을 인사·문제 상황·실천 권유와 헷갈린다','~라고 생각합니다') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X45','kor',4,'u4',ARRAY['K4-2-u4-C44']::text[],'문제 상황이나 실천을 권하는 말을 의견을 받치는 이유로 고른다','첫째 · 둘째') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X46','kor',4,'u4',ARRAY['K4-2-u4-C45']::text[],'의견과 이어지지 않는 이유나 길고 많기만 한 이유를 알맞은 이유로 여긴다','의견대로 하면 좋은 점?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X47','kor',4,'u4',ARRAY['K4-2-u4-C45']::text[],'이유가 알맞은지를 내가 그 의견에 찬성하는지로 정한다','찬반과 상관없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X48','kor',4,'u4',ARRAY['K4-2-u4-C46','K4-2-u4-C47']::text[],'글에 실린 의견은 무조건 옳다고 믿고 그대로 따른다','이유를 따져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X49','kor',4,'u4',ARRAY['K4-2-u4-C46','K4-2-u4-C47']::text[],'의견 글은 일단 틀렸다고 보고 무조건 의심하거나 반대한다','견주어 보아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X50','kor',4,'u4',ARRAY['K4-2-u4-C50','K4-2-u4-C51']::text[],'느낌을 나타내는 방법에 등수가 있다고 여기거나 배운 방법만 써야 한다고 여긴다','방법에 등수 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X51','kor',4,'u4',ARRAY['K4-2-u4-C53']::text[],'질문 놀이에서 질문을 많이 받은 사람이 이긴다고 여긴다','이기는 놀이 ✗') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X52','kor',4,'u4',ARRAY['K4-2-u4-C53']::text[],'질문 놀이에서 빨리 답할수록 잘한 것이라고 여긴다','그렇게 읽었다고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X53','kor',4,'u4',ARRAY['K4-2-u4-C55']::text[],'물건이나 값을 「-시-」를 붙여 높인다','사람만 높여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X54','kor',4,'u4',ARRAY['K4-2-u4-C56']::text[],'나라를 말할 때 「저희 나라」라고 낮춘다','우리나라') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X55','kor',4,'u4',ARRAY['K4-2-u4-C57']::text[],'외국어와 우리말을 엇갈리게 짝짓거나, 외국어가 더 멋지다고 여기거나, 들어온 말은 빠짐없이 다 바꿔야 한다고 여긴다','바꿀 말이 있으면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X56','kor',4,'u4',ARRAY['K4-2-u4-C58']::text[],'ㄺ·ㄼ·ㄵ 같은 다른 겹받침을 ㄻ으로 여기거나 ㄻ을 받침 하나로 쓴다','ㄹ과 ㅁ이 나란히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X57','kor',4,'u4',ARRAY['K4-2-u4-C54']::text[],'시 「받아쓰기」의 내용을 시와 다르게 안다','시험지 · 집') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X58','kor',4,'u4',ARRAY['K4-2-u4-C40']::text[],'글에서 새로 안 것과 더 알고 싶어진 것을 헷갈리거나 글과 상관없는 말을 한다','새로 안 것 · 궁금한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u4-X59','kor',4,'u4',ARRAY['K4-2-u4-C55','K4-2-u4-C56']::text[],'높임을 고칠 때 사람이 아닌 낱말에 「께서」를 붙이는 등 엉뚱한 곳을 높인다','높일 사람은 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_basic#1','kor',4,2,'u4','L02','g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C2',1,'mc','auto','건희와 주서 가운데 주서가 읽으면서 더 한 일은 무엇인가요?',ARRAY['K4-2-u4-X02']::text[],false,'{"seq":1,"concept":"K4-2-u4-C2","difficulty":1,"kind":"mc","stem":"건희와 주서 가운데 주서가 읽으면서 더 한 일은 무엇인가요?","options":[{"t":"읽는 동안 스스로 묻고, 다 읽고 중요한 곳에 줄을 그었다","correct":true},{"t":"더 빠른 속도로 읽었다","mis":"K4-2-u4-X02"},{"t":"같은 책을 두 번 읽었다","mis":"K4-2-u4-X02"},{"t":"책을 끝까지 다 읽었다","mis":"K4-2-u4-X02"}],"explanation":["두 친구는 같은 책을 읽었어요.","읽는 동안 한 일이 달라요.","주서는 묻고, 정리했어요."],"asset":{"type":"speech","turns":[{"who":"건희","text":"끝까지 다 읽기는 했는데…… 무슨 내용이었는지 잘 생각나지 않아."},{"who":"주서","text":"나는 읽다가 ''이다음엔 어떻게 될까?'' 하고 멈춰서 생각해 봤어. 다 읽고는 중요한 곳에 줄을 그어 두었고."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_basic#2','kor',4,2,'u4','L02','g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C8',1,'mc','auto','「고래」를 길게 불러 보면 그 안에서 들리는 낱말은 무엇인가요?',ARRAY['K4-2-u4-X09']::text[],false,'{"seq":2,"concept":"K4-2-u4-C8","difficulty":1,"kind":"mc","stem":"「고래」를 길게 불러 보면 그 안에서 들리는 낱말은 무엇인가요?","options":[{"t":"오래","correct":true},{"t":"바다","mis":"K4-2-u4-X09"},{"t":"고기","mis":"K4-2-u4-X09"},{"t":"노래","mis":"K4-2-u4-X09"}],"explanation":["「고오오오오래」를 소리 내어 봐요.","뒤에 남는 소리를 들어요.","「오래」가 들려요."],"asset":{"type":"passage","lines":["고래를 길게 불러 보면 / 고오오오오래","바다에서 오래 사는 고래 / 이름 속에 오래가 먼저 와 있었네","소리를 길게 불러 보면 / 소오오오오리","물 위에 동동 오리 한 마리 / 소리 속에서 헤엄쳐 나오네","길게 불러 보면 / 낱말 속에 숨어 있던 것들이 / 하나씩 고개를 드네"],"title":"시 「길게 불러 보면」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_basic#3','kor',4,2,'u4','L02','g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C9',1,'ox','auto','은별이와 건희가 같은 시를 읽고 다른 장면을 떠올렸으니 둘 중 한 명은 잘못 읽은 거예요.',ARRAY['K4-2-u4-X08']::text[],false,'{"seq":3,"concept":"K4-2-u4-C9","difficulty":1,"kind":"ox","stem":"은별이와 건희가 같은 시를 읽고 다른 장면을 떠올렸으니 둘 중 한 명은 잘못 읽은 거예요.","answer":"X","reason_options":[{"t":"겪은 일이 서로 달라 떠오르는 장면이 다를 수 있기 때문에","correct":true},{"t":"같은 시에서는 같은 장면이 떠올라야 하기 때문에","mis":"K4-2-u4-X08"}],"mis":"K4-2-u4-X08","explanation":["둘 다 같은 시를 읽었어요.","겪은 일이 달라요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"은별","text":"나는 아주 천천히 헤엄치는 커다란 고래가 떠올랐어."},{"who":"건희","text":"나는 말놀이를 하며 웃는 우리 반이 떠올랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_basic#4','kor',4,2,'u4','L02','g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C3',1,'mc','auto','글을 읽다가 겪는 어려움으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X03']::text[],false,'{"seq":4,"concept":"K4-2-u4-C3","difficulty":1,"kind":"mc","stem":"글을 읽다가 겪는 어려움으로 알맞은 것은 무엇인가요?","options":[{"t":"인물이 왜 그렇게 말했는지 알 수 없다","correct":true},{"t":"책 표지 색깔이 마음에 들지 않는다","mis":"K4-2-u4-X03"},{"t":"책이 무거워서 들고 다니기 힘들다","mis":"K4-2-u4-X03"},{"t":"책상 위에 책이 너무 많다","mis":"K4-2-u4-X03"}],"explanation":["「읽었는데 잘 모르겠다」를 찾아요.","표지나 무게는 읽기와 달라요.","인물의 마음을 모르는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_basic#5','kor',4,2,'u4','L02','g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C5',2,'match','auto','글의 종류와 그 글을 읽을 때 떠올리기 좋은 질문을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u4-C5","difficulty":2,"kind":"match","stem":"글의 종류와 그 글을 읽을 때 떠올리기 좋은 질문을 알맞게 이으세요.","pairs":[{"l":"시나 이야기","r":"오래 마음에 남는 장면은 어디인가?"},{"l":"설명하는 글","r":"무엇을 어떻게 알려 주고 있나?"},{"l":"의견을 제시하는 글","r":"의견을 받치는 이유가 알맞은가?"}],"mis":"K4-2-u4-X05","explanation":["그 글이 무엇을 하려고 쓴 글인지 봐요.","알려 주는 글 · 의견 글","질문도 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_basic#6','kor',4,2,'u4','L02','g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C10',2,'mc','auto','시에 대한 생각이나 느낌을 나누는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X10','K4-2-u4-X11','K4-2-u4-X14']::text[],false,'{"seq":6,"concept":"K4-2-u4-C10","difficulty":2,"kind":"mc","stem":"시에 대한 생각이나 느낌을 나누는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"떠오른 장면을 말하고, 왜 그 장면이 떠올랐는지 함께 말한다","correct":true},{"t":"가장 많이 나온 느낌으로 반의 느낌을 정한다","mis":"K4-2-u4-X10"},{"t":"친구가 먼저 말하면 그것과 똑같이 말한다","mis":"K4-2-u4-X11"},{"t":"「좋았어」 한마디만 하고 까닭은 말하지 않는다","mis":"K4-2-u4-X14"}],"explanation":["내 느낌을 말해요.","어디서 왔는지도 말해요.","까닭을 함께예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_basic#7','kor',4,2,'u4','L02','g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C11',2,'mc','auto','짝이 시를 읽고 나와 전혀 다른 색깔이 떠올랐다고 말했어요. 알맞은 대답은 무엇인가요?',ARRAY['K4-2-u4-X12','K4-2-u4-X13','K4-2-u4-X10']::text[],false,'{"seq":7,"concept":"K4-2-u4-C11","difficulty":2,"kind":"mc","stem":"짝이 시를 읽고 나와 전혀 다른 색깔이 떠올랐다고 말했어요. 알맞은 대답은 무엇인가요?","options":[{"t":"「왜 그 색이 떠올랐는지 말해 줄래?」","correct":true},{"t":"「그건 틀렸어. 이 시는 파란색이야.」","mis":"K4-2-u4-X12"},{"t":"「그럼 나도 네 색으로 바꿀게.」","mis":"K4-2-u4-X13"},{"t":"「반에서 가장 많이 나온 색으로 정하자.」","mis":"K4-2-u4-X10"}],"explanation":["느낌은 다를 수 있어요.","틀린 것이 아니에요.","까닭을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_basic#8','kor',4,2,'u4','L02','g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C4',2,'mc','auto','글을 읽을 때 스스로 질문을 던지면 좋은 점은 무엇인가요?',ARRAY['K4-2-u4-X02','K4-2-u4-X04','K4-2-u4-X06']::text[],false,'{"seq":8,"concept":"K4-2-u4-C4","difficulty":2,"kind":"mc","stem":"글을 읽을 때 스스로 질문을 던지면 좋은 점은 무엇인가요?","options":[{"t":"내가 잘 이해하고 있는지 스스로 점검할 수 있다","correct":true},{"t":"책을 더 빨리 다 읽을 수 있다","mis":"K4-2-u4-X02"},{"t":"질문은 선생님께만 하는 것이라 좋은 점이 없다","mis":"K4-2-u4-X04"},{"t":"질문 개수가 많아져 잘 읽은 것이 된다","mis":"K4-2-u4-X06"}],"explanation":["주서도 스스로 물었어요.","내가 잘 이해하나 살펴요.","스스로 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_basic#9','kor',4,2,'u4','L02','g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C12',2,'mc','auto','「수박」을 길게 늘여 「수우우우우박」이라고 하면 숨어 있는 낱말은 무엇인가요?',ARRAY['K4-2-u4-X15']::text[],false,'{"seq":9,"concept":"K4-2-u4-C12","difficulty":2,"kind":"mc","stem":"「수박」을 길게 늘여 「수우우우우박」이라고 하면 숨어 있는 낱말은 무엇인가요?","options":[{"t":"우박","correct":true},{"t":"수박","mis":"K4-2-u4-X15"},{"t":"우수","mis":"K4-2-u4-X15"},{"t":"수우","mis":"K4-2-u4-X15"}],"explanation":["앞 글자를 길게 늘여요.","뒤에 「우박」이 남아요.","‘우박’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_basic#10','kor',4,2,'u4','L02','g4_2_kor_u4_L02_basic','lesson_basic','K4-2-u4-C13',3,'error','auto','시를 읽고 느낌을 나누는 까닭을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X16','K4-2-u4-X11','K4-2-u4-X12']::text[],false,'{"seq":10,"concept":"K4-2-u4-C13","difficulty":3,"kind":"error","stem":"시를 읽고 느낌을 나누는 까닭을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「이야기를 나눈 뒤에는 모두 같은 느낌이 되어야 해.」","correct":true,"mis_target":"K4-2-u4-X16"},{"t":"친구 가 — 「다른 느낌을 들으면 내가 못 본 면을 볼 수 있어.」","mis":"K4-2-u4-X11"},{"t":"친구 나 — 「느낌은 달라도 까닭을 들으면 이해할 수 있어.」","mis":"K4-2-u4-X12"}],"explanation":["나누는 까닭은 넓게 보기예요.","하나로 맞추는 게 아니에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_challenge#1','kor',4,2,'u4','L02','g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C4',2,'sa','auto','글을 읽을 때 스스로 질문을 던져 내가 잘 이해하는지 살피는 것을 「읽기 과정을 (  ) 본다」고 해요. 빈칸에 알맞은 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u4-C4","difficulty":2,"kind":"sa","stem":"글을 읽을 때 스스로 질문을 던져 내가 잘 이해하는지 살피는 것을 「읽기 과정을 (  ) 본다」고 해요. 빈칸에 알맞은 말을 쓰세요.","answer":["되돌아","되돌아본다"],"explanation":["스스로 물어요.","내 읽기를 다시 살펴요.","‘되돌아’예요."],"mis":"K4-2-u4-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_challenge#2','kor',4,2,'u4','L02','g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C7',2,'blank','auto','시는 짧아서 (  )이/가 채워 넣을 자리가 많아요. 그래서 같은 시에서도 떠오르는 장면이 달라요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u4-X08']::text[],false,'{"seq":2,"concept":"K4-2-u4-C7","difficulty":2,"kind":"blank","stem":"시는 짧아서 (  )이/가 채워 넣을 자리가 많아요. 그래서 같은 시에서도 떠오르는 장면이 달라요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"읽는 사람","correct":true},{"t":"시를 쓴 사람","mis":"K4-2-u4-X08"},{"t":"선생님","mis":"K4-2-u4-X08"},{"t":"그림","mis":"K4-2-u4-X08"}],"explanation":["시는 짧아요.","나머지는 누가 채울까요?","‘읽는 사람’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_challenge#3','kor',4,2,'u4','L02','g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C6',3,'mc','auto','읽기 과정을 되돌아보는 것에 대해 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X06','K4-2-u4-X07','K4-2-u4-X04']::text[],false,'{"seq":3,"concept":"K4-2-u4-C6","difficulty":3,"kind":"mc","stem":"읽기 과정을 되돌아보는 것에 대해 알맞은 생각은 무엇인가요?","options":[{"t":"글과 그때의 나에게 필요한 질문을 골라 쓴다","correct":true},{"t":"질문을 많이 만들수록 잘 읽은 것이다","mis":"K4-2-u4-X06"},{"t":"읽기 전·중·후 활동을 빠짐없이 다 해야 한다","mis":"K4-2-u4-X07"},{"t":"질문은 다 읽은 뒤에만 한 번 하면 된다","mis":"K4-2-u4-X04"}],"explanation":["「많을수록」을 조심해요.","「빠짐없이 다」도 조심해요.","골라 쓰는 거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_challenge#4','kor',4,2,'u4','L02','g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C1',3,'mc','auto','이 단원에서 배울 두 가지를 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X01','K4-2-u4-X07']::text[],false,'{"seq":4,"concept":"K4-2-u4-C1","difficulty":3,"kind":"mc","stem":"이 단원에서 배울 두 가지를 바르게 말한 것은 무엇인가요?","options":[{"t":"작품에 대한 생각이나 느낌을 나누고, 질문으로 내가 어떻게 읽었는지 되돌아본다","correct":true},{"t":"책을 빠르게 많이 읽는 방법을 익힌다","mis":"K4-2-u4-X01"},{"t":"글을 쓴 사람의 이름과 나이를 외운다","mis":"K4-2-u4-X01"},{"t":"모든 글에 같은 질문 일곱 개를 빠짐없이 한다","mis":"K4-2-u4-X07"}],"explanation":["하나는 느낌 나누기예요.","하나는 되돌아보기예요.","질문으로 되돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_challenge#5','kor',4,2,'u4','L02','g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C12',3,'mc','auto','길게 늘였을 때 뒤에 다른 낱말이 숨어 있는 것은 무엇인가요?',ARRAY['K4-2-u4-X15']::text[],false,'{"seq":5,"concept":"K4-2-u4-C12","difficulty":3,"kind":"mc","stem":"길게 늘였을 때 뒤에 다른 낱말이 숨어 있는 것은 무엇인가요?","options":[{"t":"하마","correct":true},{"t":"가방","mis":"K4-2-u4-X15"},{"t":"사탕","mis":"K4-2-u4-X15"},{"t":"토끼","mis":"K4-2-u4-X15"}],"explanation":["「하아아아마」로 늘여요.","「아마」가 남아요.","나머지는 낱말이 안 남아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_challenge#6','kor',4,2,'u4','L02','g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C10',3,'ox','auto','시를 읽고 느낌을 나눌 때는 말로만 해야 하고, 그림이나 몸짓으로 나타내면 안 돼요.',ARRAY['K4-2-u4-X50']::text[],false,'{"seq":6,"concept":"K4-2-u4-C10","difficulty":3,"kind":"ox","stem":"시를 읽고 느낌을 나눌 때는 말로만 해야 하고, 그림이나 몸짓으로 나타내면 안 돼요.","answer":"X","reason_options":[{"t":"말·표정·몸짓·그림 가운데 편한 방법으로 나타낼 수 있기 때문에","correct":true},{"t":"느낌은 말로 해야만 제대로 전해지기 때문에","mis":"K4-2-u4-X50"}],"mis":"K4-2-u4-X50","explanation":["말만 있는 게 아니에요.","그림, 몸짓도 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_challenge#7','kor',4,2,'u4','L02','g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C9',3,'mc','auto','은별이는 커다란 고래를, 건희는 말놀이하는 우리 반을 떠올렸어요. 두 친구가 다른 장면을 떠올린 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X08','K4-2-u4-X14']::text[],false,'{"seq":7,"concept":"K4-2-u4-C9","difficulty":3,"kind":"mc","stem":"은별이는 커다란 고래를, 건희는 말놀이하는 우리 반을 떠올렸어요. 두 친구가 다른 장면을 떠올린 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"두 친구가 겪은 일이 서로 다르기 때문에","correct":true},{"t":"건희가 시를 잘못 읽었기 때문에","mis":"K4-2-u4-X08"},{"t":"은별이가 시를 끝까지 읽지 않았기 때문에","mis":"K4-2-u4-X08"},{"t":"느낌에는 정답이 없어서 아무렇게나 말했기 때문에","mis":"K4-2-u4-X14"}],"explanation":["누가 틀린 게 아니에요.","아무렇게나도 아니에요.","겪은 일이 달라요."],"asset":{"type":"speech","turns":[{"who":"은별","text":"나는 아주 천천히 헤엄치는 커다란 고래가 떠올랐어."},{"who":"건희","text":"나는 말놀이를 하며 웃는 우리 반이 떠올랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_challenge#8','kor',4,2,'u4','L02','g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C5',4,'mc','auto','㉰를 읽을 때 떠올리기 가장 알맞은 질문은 무엇인가요?',ARRAY['K4-2-u4-X05']::text[],false,'{"seq":8,"concept":"K4-2-u4-C5","difficulty":4,"kind":"mc","stem":"㉰를 읽을 때 떠올리기 가장 알맞은 질문은 무엇인가요?","options":[{"t":"글쓴이의 의견을 받치는 이유가 알맞은가?","correct":true},{"t":"가장 오래 마음에 남는 장면은 어디인가?","mis":"K4-2-u4-X05"},{"t":"무엇을 어떻게 알려 주고 있나?","mis":"K4-2-u4-X05"},{"t":"그네는 누가 탔을까?","mis":"K4-2-u4-X05"}],"explanation":["㉰는 「~라고 생각합니다」예요.","의견을 제시하는 글이에요.","이유가 알맞은지 물어요."],"asset":{"type":"passage","lines":["㉮ 「빈 그네」 — 아이들이 다 돌아간 저녁, 그네 하나가 아직 흔들린다","㉯ 「개미가 줄지어 가는 까닭」 — 먹이를 찾은 개미는 땅에 냄새를 남긴다","㉰ 「다 쓴 종이는 이면지 상자에 모아요」 — 저는 종이를 모으자고 생각합니다"],"title":"세 글의 첫 토막"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_challenge#9','kor',4,2,'u4','L02','g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C2',4,'mc','auto','건희가 다음에 책을 읽을 때 해 보면 좋을 일로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X02','K4-2-u4-X06']::text[],false,'{"seq":9,"concept":"K4-2-u4-C2","difficulty":4,"kind":"mc","stem":"건희가 다음에 책을 읽을 때 해 보면 좋을 일로 가장 알맞은 것은 무엇인가요?","options":[{"t":"읽는 동안 「이다음엔 어떻게 될까?」 하고 멈춰 생각하고, 다 읽고 중요한 곳을 정리한다","correct":true},{"t":"주서보다 더 빨리 끝까지 읽는다","mis":"K4-2-u4-X02"},{"t":"같은 책을 세 번 더 읽는다","mis":"K4-2-u4-X02"},{"t":"질문을 스무 개 만들어 모두 적는다","mis":"K4-2-u4-X06"}],"explanation":["빠르기나 횟수가 아니에요.","읽는 동안 한 일이 달랐어요.","묻고, 정리해요."],"asset":{"type":"speech","turns":[{"who":"건희","text":"끝까지 다 읽기는 했는데…… 무슨 내용이었는지 잘 생각나지 않아."},{"who":"주서","text":"나는 읽다가 ''이다음엔 어떻게 될까?'' 하고 멈춰서 생각해 봤어. 다 읽고는 중요한 곳에 줄을 그어 두었고."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L02_challenge#10','kor',4,2,'u4','L02','g4_2_kor_u4_L02_challenge','lesson_challenge','K4-2-u4-C11',4,'essay','teacher','짝이 「길게 불러 보면」을 읽고 「나는 이 시가 쓸쓸했어.」라고 말했어요. 나는 즐거운 느낌이었다면 짝에게 어떻게 말하면 좋을지 쓰고, 그렇게 말해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C11","difficulty":4,"kind":"essay","stem":"짝이 「길게 불러 보면」을 읽고 「나는 이 시가 쓸쓸했어.」라고 말했어요. 나는 즐거운 느낌이었다면 짝에게 어떻게 말하면 좋을지 쓰고, 그렇게 말해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「나는 즐거웠는데, 너는 어느 줄에서 쓸쓸했는지 말해 줄래?」라고 묻는다. 느낌은 틀린 것이 아니라 다를 수 있는 것이고, 짝의 까닭을 들으면 내가 못 본 면을 볼 수 있기 때문이다.","scoring_points":["짝의 느낌을 틀렸다고 하지 않았는가","짝에게 느낌의 까닭을 묻는 말을 썼는가","다른 느낌을 들으면 좋은 점을 까닭으로 썼는가"]},"explanation":["틀렸다고 하지 않아요.","까닭을 물어요.","못 본 면을 볼 수 있어요."],"asset":{"type":"passage","lines":["고래를 길게 불러 보면 / 고오오오오래","바다에서 오래 사는 고래 / 이름 속에 오래가 먼저 와 있었네","소리를 길게 불러 보면 / 소오오오오리","물 위에 동동 오리 한 마리 / 소리 속에서 헤엄쳐 나오네","길게 불러 보면 / 낱말 속에 숨어 있던 것들이 / 하나씩 고개를 드네"],"title":"시 「길게 불러 보면」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_basic#1','kor',4,2,'u4','L04','g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C15',1,'mc','auto','형준이가 소품을 맡겠다고 한 까닭은 무엇인가요?',ARRAY['K4-2-u4-X17']::text[],false,'{"seq":1,"concept":"K4-2-u4-C15","difficulty":1,"kind":"mc","stem":"형준이가 소품을 맡겠다고 한 까닭은 무엇인가요?","options":[{"t":"해설을 하고 싶었지만 그 말을 하지 못해서","correct":true},{"t":"소품 만들기를 가장 좋아해서","mis":"K4-2-u4-X17"},{"t":"연습할 시간이 없어서","mis":"K4-2-u4-X17"},{"t":"우석이가 소품을 하라고 시켜서","mis":"K4-2-u4-X17"}],"explanation":["손을 반쯤 들었다 내렸어요.","수지 말을 들은 뒤예요.","하고 싶은 말을 못 했어요."],"asset":{"type":"passage","lines":["학예회 연습 첫날, 모둠에서 역할을 나누기로 했다.","형준이는 해설을 맡고 싶어 며칠 전부터 혼자 대사를 읽어 보았다.","「해설 할 사람?」 우석이가 묻자 형준이는 손을 반쯤 들었다가 내렸다.","그때 수지가 말했다. 「형준이는 목소리가 작아서 해설은 안 맞을걸.」","형준이는 아무 말도 하지 않고 「나는 소품 할게.」 하고 웃었다.","돌아오는 길에 우석이가 물었다. 「너, 소품 정말 하고 싶었어?」","형준이는 멋쩍게 웃기만 했다."],"title":"이야기 「말하지 못한 말」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_basic#2','kor',4,2,'u4','L04','g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C16',1,'mc','auto','연습이 자꾸 끊긴 까닭은 무엇인가요?',ARRAY['K4-2-u4-X18']::text[],false,'{"seq":2,"concept":"K4-2-u4-C16","difficulty":1,"kind":"mc","stem":"연습이 자꾸 끊긴 까닭은 무엇인가요?","options":[{"t":"아무도 먼저 의견을 내지 않게 되어서","correct":true},{"t":"연습 날짜가 자꾸 바뀌어서","mis":"K4-2-u4-X18"},{"t":"맡은 역할이 너무 어려워서","mis":"K4-2-u4-X18"},{"t":"배경 그림 종이가 찢어져서","mis":"K4-2-u4-X18"}],"explanation":["그림을 맡은 친구가 입을 닫았어요.","아무도 먼저 말하지 않았어요.","말이 사라졌어요."],"asset":{"type":"passage","lines":["다음 연습 날, 배경 그림을 맡은 친구가 종이를 펼쳤다.","수지가 들여다보더니 말했다. 「이건 좀 이상해. 나무가 집보다 크잖아.」","그 친구는 종이를 접어 넣고 그날 내내 아무 말도 하지 않았다.","연습이 자꾸 끊겼다. 아무도 먼저 의견을 내지 않았기 때문이다.","형준이가 조용히 말했다. 「사실 나…… 해설 하고 싶었어.」","수지가 「그럼 그때 말하지.」 하려다 입을 다물었다. 자기가 한 말이 떠올랐다.","우석이가 말했다. 「우리 둘 다 한 가지씩 빠뜨린 것 같아.」","셋은 한참 동안 말없이 앉아 있었다."],"title":"이야기 「말하지 못한 말」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_basic#3','kor',4,2,'u4','L04','g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C17',1,'match','auto','이야기에 나온 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u4-C17","difficulty":1,"kind":"match","stem":"이야기에 나온 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"멋쩍다","r":"어색하고 쑥스럽다"},{"l":"머뭇거리다","r":"선뜻 하지 못하고 잠깐 멈칫하다"},{"l":"우물쭈물하다","r":"말이나 행동을 분명히 하지 못하고 자꾸 망설이다"}],"mis":"K4-2-u4-X19","explanation":["낱말이 쓰인 줄을 다시 봐요.","형준이는 멋쩍게 웃었어요.","앞뒤로 뜻을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_basic#4','kor',4,2,'u4','L04','g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C22',1,'ox','auto','역할놀이는 가장 웃기게 한 모둠이 가장 잘한 거예요.',ARRAY['K4-2-u4-X24']::text[],false,'{"seq":4,"concept":"K4-2-u4-C22","difficulty":1,"kind":"ox","stem":"역할놀이는 가장 웃기게 한 모둠이 가장 잘한 거예요.","answer":"X","reason_options":[{"t":"인물의 말과 행동에 대한 생각이나 느낌이 드러났는지가 중요하기 때문에","correct":true},{"t":"보는 친구들이 많이 웃어야 성공한 역할놀이이기 때문에","mis":"K4-2-u4-X24"}],"mis":"K4-2-u4-X24","explanation":["역할놀이는 웃기기 대회가 아니에요.","인물의 마음을 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_basic#5','kor',4,2,'u4','L04','g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C19',2,'mc','auto','형준이 역할을 할 때 어울리는 말투는 무엇인가요?',ARRAY['K4-2-u4-X22','K4-2-u4-X21']::text[],false,'{"seq":5,"concept":"K4-2-u4-C19","difficulty":2,"kind":"mc","stem":"형준이 역할을 할 때 어울리는 말투는 무엇인가요?","options":[{"t":"천천히, 말끝이 조금 흐려지게","correct":true},{"t":"빠르고 큰 목소리로 또박또박","mis":"K4-2-u4-X22"},{"t":"화가 난 듯 거칠게","mis":"K4-2-u4-X22"},{"t":"친구를 놀리려는 듯 비웃으며","mis":"K4-2-u4-X21"}],"explanation":["형준이는 손을 들었다 내렸어요.","하고 싶은 말을 삼켰어요.","말끝이 흐려져요."],"asset":{"type":"passage","lines":["학예회 연습 첫날, 모둠에서 역할을 나누기로 했다.","형준이는 해설을 맡고 싶어 며칠 전부터 혼자 대사를 읽어 보았다.","「해설 할 사람?」 우석이가 묻자 형준이는 손을 반쯤 들었다가 내렸다.","그때 수지가 말했다. 「형준이는 목소리가 작아서 해설은 안 맞을걸.」","형준이는 아무 말도 하지 않고 「나는 소품 할게.」 하고 웃었다.","돌아오는 길에 우석이가 물었다. 「너, 소품 정말 하고 싶었어?」","형준이는 멋쩍게 웃기만 했다."],"title":"이야기 「말하지 못한 말」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_basic#6','kor',4,2,'u4','L04','g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C18',2,'mc','auto','수지가 한 말 「형준이는 목소리가 작아서 해설은 안 맞을걸.」과 「이건 좀 이상해.」로 짐작할 수 있는 수지의 성격은 무엇인가요?',ARRAY['K4-2-u4-X21','K4-2-u4-X20']::text[],false,'{"seq":6,"concept":"K4-2-u4-C18","difficulty":2,"kind":"mc","stem":"수지가 한 말 「형준이는 목소리가 작아서 해설은 안 맞을걸.」과 「이건 좀 이상해.」로 짐작할 수 있는 수지의 성격은 무엇인가요?","options":[{"t":"본 대로 바로 말하지만 상대의 마음은 잘 살피지 않는다","correct":true},{"t":"친구를 일부러 괴롭히려는 나쁜 아이다","mis":"K4-2-u4-X21"},{"t":"말을 잘 하지 못하고 늘 망설인다","mis":"K4-2-u4-X20"},{"t":"목소리가 커서 무서운 아이다","mis":"K4-2-u4-X20"}],"explanation":["수지가 한 말을 봐요.","생각한 것을 곧바로 말했어요.","마음은 살피지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_basic#7','kor',4,2,'u4','L04','g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C20',2,'mc','auto','역할놀이로 나타낼 장면을 고를 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X23','K4-2-u4-X24']::text[],false,'{"seq":7,"concept":"K4-2-u4-C20","difficulty":2,"kind":"mc","stem":"역할놀이로 나타낼 장면을 고를 때 알맞은 생각은 무엇인가요?","options":[{"t":"어느 장면을 골라도 좋고, 고른 까닭을 말할 수 있으면 된다","correct":true},{"t":"가장 감동적인 장면 하나만 정답이다","mis":"K4-2-u4-X23"},{"t":"가장 웃긴 장면을 골라야 한다","mis":"K4-2-u4-X24"},{"t":"대사가 가장 많은 장면을 골라야 잘한 것이다","mis":"K4-2-u4-X23"}],"explanation":["장면에는 정답이 없어요.","웃긴 장면을 찾는 것도 아니에요.","까닭만 말하면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_basic#8','kor',4,2,'u4','L04','g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C21',2,'mc','auto','역할놀이를 하는 차례로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X26']::text[],false,'{"seq":8,"concept":"K4-2-u4-C21","difficulty":2,"kind":"mc","stem":"역할놀이를 하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"장면 정하기 → 역할 나누기 → 연습하기 → 친구들 앞에서 해 보기","correct":true},{"t":"역할 나누기 → 친구들 앞에서 해 보기 → 장면 정하기 → 연습하기","mis":"K4-2-u4-X26"},{"t":"연습하기 → 장면 정하기 → 해 보기 → 역할 나누기","mis":"K4-2-u4-X26"},{"t":"친구들 앞에서 해 보기 → 연습하기 → 역할 나누기 → 장면 정하기","mis":"K4-2-u4-X26"}],"explanation":["장면부터 정해요.","나누고 연습해요.","해 보기가 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_basic#9','kor',4,2,'u4','L04','g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C24',2,'mc','auto','수지와 닮은 사람에게 쪽지를 쓸 때 알맞은 문장은 무엇인가요?',ARRAY['K4-2-u4-X27','K4-2-u4-X29']::text[],false,'{"seq":9,"concept":"K4-2-u4-C24","difficulty":2,"kind":"mc","stem":"수지와 닮은 사람에게 쪽지를 쓸 때 알맞은 문장은 무엇인가요?","options":[{"t":"「나는 네 말을 듣고 친구 마음이 어땠을지 궁금했어.」","correct":true},{"t":"「너는 늘 남의 마음을 아프게 하잖아.」","mis":"K4-2-u4-X27"},{"t":"「너 같은 사람은 말을 하지 마.」","mis":"K4-2-u4-X27"},{"t":"「너 때문에 연습이 다 망했어.」","mis":"K4-2-u4-X29"}],"explanation":["받는 사람을 생각해요.","「너는 ~하잖아」는 아파요.","「나는 ~」으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_basic#10','kor',4,2,'u4','L04','g4_2_kor_u4_L04_basic','lesson_basic','K4-2-u4-C25',3,'mc','auto','우석이가 「우리 둘 다 한 가지씩 빠뜨린 것 같아.」라고 한 말의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X29','K4-2-u4-X18']::text[],false,'{"seq":10,"concept":"K4-2-u4-C25","difficulty":3,"kind":"mc","stem":"우석이가 「우리 둘 다 한 가지씩 빠뜨린 것 같아.」라고 한 말의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"형준이는 하고 싶은 말을 하지 않았고, 수지는 상대의 마음을 살피지 않고 말했다","correct":true},{"t":"수지 혼자 잘못했다","mis":"K4-2-u4-X29"},{"t":"형준이 혼자 잘못했다","mis":"K4-2-u4-X29"},{"t":"둘 다 연습에 늦게 왔다","mis":"K4-2-u4-X18"}],"explanation":["「둘 다」를 봐요.","형준이가 빠뜨린 것, 수지가 빠뜨린 것","한 사람만의 일이 아니에요."],"asset":{"type":"passage","lines":["다음 연습 날, 배경 그림을 맡은 친구가 종이를 펼쳤다.","수지가 들여다보더니 말했다. 「이건 좀 이상해. 나무가 집보다 크잖아.」","그 친구는 종이를 접어 넣고 그날 내내 아무 말도 하지 않았다.","연습이 자꾸 끊겼다. 아무도 먼저 의견을 내지 않았기 때문이다.","형준이가 조용히 말했다. 「사실 나…… 해설 하고 싶었어.」","수지가 「그럼 그때 말하지.」 하려다 입을 다물었다. 자기가 한 말이 떠올랐다.","우석이가 말했다. 「우리 둘 다 한 가지씩 빠뜨린 것 같아.」","셋은 한참 동안 말없이 앉아 있었다."],"title":"이야기 「말하지 못한 말」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_challenge#1','kor',4,2,'u4','L04','g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C17',2,'sa','auto','「어색하고 쑥스럽다」는 뜻으로, 형준이가 우석이의 물음에 웃기만 할 때 쓰인 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u4-C17","difficulty":2,"kind":"sa","stem":"「어색하고 쑥스럽다」는 뜻으로, 형준이가 우석이의 물음에 웃기만 할 때 쓰인 낱말을 쓰세요.","answer":["멋쩍다","멋쩍게"],"explanation":["마지막 줄을 봐요.","「~게 웃기만 했다」","‘멋쩍다’예요."],"asset":{"type":"passage","lines":["학예회 연습 첫날, 모둠에서 역할을 나누기로 했다.","형준이는 해설을 맡고 싶어 며칠 전부터 혼자 대사를 읽어 보았다.","「해설 할 사람?」 우석이가 묻자 형준이는 손을 반쯤 들었다가 내렸다.","그때 수지가 말했다. 「형준이는 목소리가 작아서 해설은 안 맞을걸.」","형준이는 아무 말도 하지 않고 「나는 소품 할게.」 하고 웃었다.","돌아오는 길에 우석이가 물었다. 「너, 소품 정말 하고 싶었어?」","형준이는 멋쩍게 웃기만 했다."],"title":"이야기 「말하지 못한 말」 ①"},"mis":"K4-2-u4-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_challenge#2','kor',4,2,'u4','L04','g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C14',2,'blank','auto','이야기 속 인물의 (  )을/를 따라가다 보면 인물에 대한 생각이나 느낌이 생겨요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u4-X20']::text[],false,'{"seq":2,"concept":"K4-2-u4-C14","difficulty":2,"kind":"blank","stem":"이야기 속 인물의 (  )을/를 따라가다 보면 인물에 대한 생각이나 느낌이 생겨요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"말과 행동","correct":true},{"t":"이름과 나이","mis":"K4-2-u4-X20"},{"t":"옷 색깔","mis":"K4-2-u4-X20"},{"t":"글자 수","mis":"K4-2-u4-X20"}],"explanation":["인물이 무엇을 했나요?","무슨 말을 했나요?","‘말과 행동’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_challenge#3','kor',4,2,'u4','L04','g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C18',3,'mc','auto','형준이가 「해설 할 사람?」이라는 말에 손을 반쯤 들었다가 내린 행동으로 짐작할 수 있는 것은 무엇인가요?',ARRAY['K4-2-u4-X17','K4-2-u4-X20']::text[],false,'{"seq":3,"concept":"K4-2-u4-C18","difficulty":3,"kind":"mc","stem":"형준이가 「해설 할 사람?」이라는 말에 손을 반쯤 들었다가 내린 행동으로 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"하고 싶은 마음이 있었지만 망설였다","correct":true},{"t":"해설에는 관심이 전혀 없었다","mis":"K4-2-u4-X17"},{"t":"팔이 아파서 손을 들 수 없었다","mis":"K4-2-u4-X17"},{"t":"우석이를 골탕 먹이려고 했다","mis":"K4-2-u4-X20"}],"explanation":["손을 반쯤 들었어요.","그러다 내렸어요.","하고 싶었지만 망설였어요."],"asset":{"type":"passage","lines":["학예회 연습 첫날, 모둠에서 역할을 나누기로 했다.","형준이는 해설을 맡고 싶어 며칠 전부터 혼자 대사를 읽어 보았다.","「해설 할 사람?」 우석이가 묻자 형준이는 손을 반쯤 들었다가 내렸다.","그때 수지가 말했다. 「형준이는 목소리가 작아서 해설은 안 맞을걸.」","형준이는 아무 말도 하지 않고 「나는 소품 할게.」 하고 웃었다.","돌아오는 길에 우석이가 물었다. 「너, 소품 정말 하고 싶었어?」","형준이는 멋쩍게 웃기만 했다."],"title":"이야기 「말하지 못한 말」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_challenge#4','kor',4,2,'u4','L04','g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C22',3,'mc','auto','역할놀이를 보고 이야기할 때 살펴볼 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X25','K4-2-u4-X24']::text[],false,'{"seq":4,"concept":"K4-2-u4-C22","difficulty":3,"kind":"mc","stem":"역할놀이를 보고 이야기할 때 살펴볼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"그 인물에 대한 자기 생각이나 느낌이 드러났는가","correct":true},{"t":"목소리가 가장 큰 사람은 누구였는가","mis":"K4-2-u4-X25"},{"t":"누가 가장 웃겼는가","mis":"K4-2-u4-X24"},{"t":"누가 대사를 가장 빨리 말했는가","mis":"K4-2-u4-X25"}],"explanation":["웃기기도, 크기도 아니에요.","인물에 대한 생각을 봐요.","느낌이 드러났나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_challenge#5','kor',4,2,'u4','L04','g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C23',3,'mc','auto','「말하지 못한 말」에 대한 친구의 생각을 알아보는 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X28']::text[],false,'{"seq":5,"concept":"K4-2-u4-C23","difficulty":3,"kind":"mc","stem":"「말하지 못한 말」에 대한 친구의 생각을 알아보는 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"형준이처럼 하고 싶은 말을 못 한 적이 있나요?","correct":true},{"t":"학예회는 몇 월에 하나요?","mis":"K4-2-u4-X28"},{"t":"형준이는 몇 살일까요?","mis":"K4-2-u4-X28"},{"t":"우석이네 집은 어디일까요?","mis":"K4-2-u4-X28"}],"explanation":["작품과 이어진 질문이에요.","나와 관련지어 봐요.","못 한 적이 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_challenge#6','kor',4,2,'u4','L04','g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C19',3,'ox','auto','수지 역할을 할 때는 친구를 비웃는 말투로 해야 인물에 어울려요.',ARRAY['K4-2-u4-X21']::text[],false,'{"seq":6,"concept":"K4-2-u4-C19","difficulty":3,"kind":"ox","stem":"수지 역할을 할 때는 친구를 비웃는 말투로 해야 인물에 어울려요.","answer":"X","reason_options":[{"t":"수지는 본 대로 바로 말하는 인물이지 친구를 놀리려던 것은 아니기 때문에","correct":true},{"t":"형준이가 속상했으니 수지가 나쁜 마음으로 말한 것이 분명하기 때문에","mis":"K4-2-u4-X21"}],"mis":"K4-2-u4-X21","explanation":["수지는 곧바로 말했어요.","놀리려던 건 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_challenge#7','kor',4,2,'u4','L04','g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C21',3,'mc','auto','다른 모둠이 역할놀이를 할 때 알맞은 태도는 무엇인가요?',ARRAY['K4-2-u4-X26','K4-2-u4-X24']::text[],false,'{"seq":7,"concept":"K4-2-u4-C21","difficulty":3,"kind":"mc","stem":"다른 모둠이 역할놀이를 할 때 알맞은 태도는 무엇인가요?","options":[{"t":"끝까지 조용히 지켜보며 인물의 마음이 드러났는지 살핀다","correct":true},{"t":"재미없으면 중간에 끼어들어 바꾸어 준다","mis":"K4-2-u4-X26"},{"t":"우리 모둠 차례를 준비하느라 보지 않는다","mis":"K4-2-u4-X26"},{"t":"누가 가장 웃긴지 점수를 매긴다","mis":"K4-2-u4-X24"}],"explanation":["끼어들지 않아요.","끝까지 지켜봐요.","인물의 마음을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_challenge#8','kor',4,2,'u4','L04','g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C25',4,'essay','teacher','형준이와 수지가 각각 빠뜨린 것은 무엇인지 쓰고, 둘 가운데 한 사람만 잘못했다고 볼 수 없는 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u4-C25","difficulty":4,"kind":"essay","stem":"형준이와 수지가 각각 빠뜨린 것은 무엇인지 쓰고, 둘 가운데 한 사람만 잘못했다고 볼 수 없는 까닭을 쓰세요.","answer_guide":{"answer":"예: 형준이는 해설을 하고 싶다는 말을 하지 않았고, 수지는 상대의 마음을 살피지 않고 본 대로 바로 말했다. 형준이가 말하지 않아서 수지도 형준이의 마음을 몰랐고, 수지의 말 때문에 형준이는 더 말하기 어려웠으니 둘 다 한 가지씩 돌아볼 점이 있다.","scoring_points":["형준이가 빠뜨린 것을 썼는가","수지가 빠뜨린 것을 썼는가","두 사람의 일이 서로 이어져 있음을 까닭으로 썼는가"]},"explanation":["형준이는 말하지 않았어요.","수지는 마음을 살피지 않았어요.","둘 다 한 가지씩이에요."],"asset":{"type":"passage","lines":["다음 연습 날, 배경 그림을 맡은 친구가 종이를 펼쳤다.","수지가 들여다보더니 말했다. 「이건 좀 이상해. 나무가 집보다 크잖아.」","그 친구는 종이를 접어 넣고 그날 내내 아무 말도 하지 않았다.","연습이 자꾸 끊겼다. 아무도 먼저 의견을 내지 않았기 때문이다.","형준이가 조용히 말했다. 「사실 나…… 해설 하고 싶었어.」","수지가 「그럼 그때 말하지.」 하려다 입을 다물었다. 자기가 한 말이 떠올랐다.","우석이가 말했다. 「우리 둘 다 한 가지씩 빠뜨린 것 같아.」","셋은 한참 동안 말없이 앉아 있었다."],"title":"이야기 「말하지 못한 말」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_challenge#9','kor',4,2,'u4','L04','g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C18',4,'mc','auto','다빈이의 말과 행동으로 짐작할 수 있는 성격으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X20']::text[],false,'{"seq":9,"concept":"K4-2-u4-C18","difficulty":4,"kind":"mc","stem":"다빈이의 말과 행동으로 짐작할 수 있는 성격으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"자기가 조금 불편해도 친구를 먼저 챙긴다","correct":true},{"t":"남의 일에는 관심이 없다","mis":"K4-2-u4-X20"},{"t":"우산을 자랑하고 싶어 한다","mis":"K4-2-u4-X20"},{"t":"처음에 머뭇거렸으니 지호를 싫어한다","mis":"K4-2-u4-X20"}],"explanation":["우산을 기울였어요.","어깨가 젖어도 괜찮대요.","한 장면만 보고 정하지 않아요."],"asset":{"type":"passage","lines":["비가 오는 하굣길, 지호는 우산이 없어 현관에 서 있었다.","같은 반 다빈이가 우산을 펴다가 지호를 보았다.","다빈이는 잠깐 머뭇거리더니 우산을 지호 쪽으로 기울였다.","「같이 가자. 나는 어깨 좀 젖어도 괜찮아.」","지호는 「고마워.」 하고 작게 말했다.","다음 날, 지호는 집에 있던 우산 하나를 더 들고 와 다빈이 책상 옆에 걸어 두었다."],"title":"이야기 「우산 하나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L04_challenge#10','kor',4,2,'u4','L04','g4_2_kor_u4_L04_challenge','lesson_challenge','K4-2-u4-C22',4,'mc','auto','어떤 모둠이 「말하지 못한 말」 역할놀이를 마쳤어요. 평가 기준에 가장 알맞게 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X24','K4-2-u4-X25','K4-2-u4-X20']::text[],false,'{"seq":10,"concept":"K4-2-u4-C22","difficulty":4,"kind":"mc","stem":"어떤 모둠이 「말하지 못한 말」 역할놀이를 마쳤어요. 평가 기준에 가장 알맞게 말한 친구는 누구인가요?","options":[{"t":"「형준이가 손을 내릴 때 망설이는 마음이 잘 보였어. 나도 그런 적이 있어서 마음이 쓰였어.」","correct":true},{"t":"「수지 역할이 제일 웃겼으니 그 모둠이 이겼어.」","mis":"K4-2-u4-X24"},{"t":"「목소리가 제일 커서 잘 들렸으니 일등이야.」","mis":"K4-2-u4-X25"},{"t":"「형준이는 원래 겁이 많은 아이니까 저렇게 하면 돼.」","mis":"K4-2-u4-X20"}],"explanation":["인물의 마음이 보였나요?","내 생각이나 느낌을 말해요.","웃기기·크기가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_basic#1','kor',4,2,'u4','L07','g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C26',1,'match','auto','읽기 과정과 그때 할 수 있는 활동을 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u4-C26","difficulty":1,"kind":"match","stem":"읽기 과정과 그때 할 수 있는 활동을 알맞게 이으세요.","pairs":[{"l":"읽기 전","r":"제목을 보고 내용을 짐작하기"},{"l":"읽기 중","r":"짐작한 것과 맞는지 확인하며 읽기"},{"l":"읽기 후","r":"글 전체를 짧게 간추려 정리하기"}],"mis":"K4-2-u4-X30","explanation":["글을 펴기 전에 할 수 있는 일","읽는 동안에만 할 수 있는 일","다 읽어야 할 수 있는 일"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_basic#2','kor',4,2,'u4','L07','g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C27',1,'mc','auto','읽기 「전」에 하는 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":2,"concept":"K4-2-u4-C27","difficulty":1,"kind":"mc","stem":"읽기 「전」에 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"그 주제에 대해 내가 이미 아는 것을 떠올린다","correct":true},{"t":"읽은 내용을 짧게 간추린다","mis":"K4-2-u4-X30"},{"t":"각 부분에서 가장 중요한 문장을 찾는다","mis":"K4-2-u4-X30"},{"t":"더 알고 싶어진 것을 적는다","mis":"K4-2-u4-X30"}],"explanation":["아직 글을 펴지 않았어요.","짐작하거나 아는 것을 떠올려요.","아는 것 떠올리기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_basic#3','kor',4,2,'u4','L07','g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C31',1,'mc','auto','「민들레 씨앗의 여행」에서 하얗고 동그란 공은 무엇인가요?',ARRAY['K4-2-u4-X33']::text[],false,'{"seq":3,"concept":"K4-2-u4-C31","difficulty":1,"kind":"mc","stem":"「민들레 씨앗의 여행」에서 하얗고 동그란 공은 무엇인가요?","options":[{"t":"씨앗이 잔뜩 모여 있는 것","correct":true},{"t":"꽃이 시든 것","mis":"K4-2-u4-X33"},{"t":"잎이 말라 뭉친 것","mis":"K4-2-u4-X33"},{"t":"벌레가 만든 집","mis":"K4-2-u4-X33"}],"explanation":["2번 문장을 봐요.","시든 것이 아니래요.","씨앗이 모인 것이에요."],"asset":{"type":"passage","lines":["1 봄에 핀 노란 민들레꽃이 지고 나면 그 자리에 하얗고 동그란 공이 생깁니다.","2 이 공은 꽃이 시든 것이 아니라 씨앗이 잔뜩 모여 있는 것입니다.","3 씨앗 하나하나에는 가는 털이 부챗살처럼 붙어 있습니다.","4 이 털이 낙하산처럼 공기를 받아 씨앗을 공중에 띄웁니다.","5 그래서 민들레는 스스로 걸어 다니지 못해도 멀리까지 퍼질 수 있습니다.","6 바람이 잘 부는 길가에 민들레가 줄지어 피어 있는 까닭이 여기에 있습니다."],"title":"설명하는 글 「민들레 씨앗의 여행」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_basic#4','kor',4,2,'u4','L07','g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C29',1,'ox','auto','「읽은 내용을 짧게 간추리면 무엇인가?」는 다 읽은 뒤에 할 수 있는 질문이에요.',ARRAY['K4-2-u4-X31']::text[],false,'{"seq":4,"concept":"K4-2-u4-C29","difficulty":1,"kind":"ox","stem":"「읽은 내용을 짧게 간추리면 무엇인가?」는 다 읽은 뒤에 할 수 있는 질문이에요.","answer":"O","reason_options":[{"t":"글을 끝까지 읽어야 간추릴 수 있기 때문에","correct":true},{"t":"제목만 보고도 간추릴 수 있기 때문에","mis":"K4-2-u4-X31"}],"mis":"K4-2-u4-X31","explanation":["간추리려면 다 읽어야 해요.","읽기 후 질문이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_basic#5','kor',4,2,'u4','L07','g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C30',2,'mc','auto','「민들레 씨앗의 여행」을 읽기 전에 할 수 있는 질문은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":5,"concept":"K4-2-u4-C30","difficulty":2,"kind":"mc","stem":"「민들레 씨앗의 여행」을 읽기 전에 할 수 있는 질문은 무엇인가요?","options":[{"t":"제목을 보니 무엇에 대한 글일까?","correct":true},{"t":"셋째 줄의 중심 내용은 무엇인가?","mis":"K4-2-u4-X31"},{"t":"짧게 간추리면 무엇인가?","mis":"K4-2-u4-X31"},{"t":"이 책은 도서관 어디에 있는가?","mis":"K4-2-u4-X32"}],"explanation":["아직 읽지 않았어요.","제목만 보고 답할 수 있어야 해요.","무엇에 대한 글일까?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_basic#6','kor',4,2,'u4','L07','g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C28',2,'mc','auto','읽는 「동안」에 할 수 있는 질문은 무엇인가요?',ARRAY['K4-2-u4-X30','K4-2-u4-X32']::text[],false,'{"seq":6,"concept":"K4-2-u4-C28","difficulty":2,"kind":"mc","stem":"읽는 「동안」에 할 수 있는 질문은 무엇인가요?","options":[{"t":"내가 짐작한 내용과 글의 내용이 같은가?","correct":true},{"t":"이 글을 읽고 더 알고 싶어진 것은 무엇인가?","mis":"K4-2-u4-X30"},{"t":"이 주제에 대해 내가 아는 것은 무엇인가?","mis":"K4-2-u4-X30"},{"t":"이 글은 몇 줄인가?","mis":"K4-2-u4-X32"}],"explanation":["읽는 도중에 멈춰요.","짐작과 견주어요.","같은지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_basic#7','kor',4,2,'u4','L07','g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C31',2,'mc','auto','민들레가 스스로 걸어 다니지 못해도 멀리까지 퍼질 수 있는 까닭은 무엇인가요?',ARRAY['K4-2-u4-X33']::text[],false,'{"seq":7,"concept":"K4-2-u4-C31","difficulty":2,"kind":"mc","stem":"민들레가 스스로 걸어 다니지 못해도 멀리까지 퍼질 수 있는 까닭은 무엇인가요?","options":[{"t":"씨앗에 붙은 털이 낙하산처럼 공기를 받아 씨앗을 띄우기 때문에","correct":true},{"t":"씨앗이 땅속으로 길을 파고 가기 때문에","mis":"K4-2-u4-X33"},{"t":"꽃이 바람에 꺾여 날아가기 때문에","mis":"K4-2-u4-X33"},{"t":"새가 꽃을 통째로 옮기기 때문에","mis":"K4-2-u4-X33"}],"explanation":["3번과 4번 문장을 봐요.","털이 공기를 받아요.","씨앗이 떠서 퍼져요."],"asset":{"type":"passage","lines":["1 봄에 핀 노란 민들레꽃이 지고 나면 그 자리에 하얗고 동그란 공이 생깁니다.","2 이 공은 꽃이 시든 것이 아니라 씨앗이 잔뜩 모여 있는 것입니다.","3 씨앗 하나하나에는 가는 털이 부챗살처럼 붙어 있습니다.","4 이 털이 낙하산처럼 공기를 받아 씨앗을 공중에 띄웁니다.","5 그래서 민들레는 스스로 걸어 다니지 못해도 멀리까지 퍼질 수 있습니다.","6 바람이 잘 부는 길가에 민들레가 줄지어 피어 있는 까닭이 여기에 있습니다."],"title":"설명하는 글 「민들레 씨앗의 여행」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_basic#8','kor',4,2,'u4','L07','g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C32',2,'mc','auto','설명하는 글을 읽을 때 떠올리기 좋은 질문은 무엇인가요?',ARRAY['K4-2-u4-X05','K4-2-u4-X32']::text[],false,'{"seq":8,"concept":"K4-2-u4-C32","difficulty":2,"kind":"mc","stem":"설명하는 글을 읽을 때 떠올리기 좋은 질문은 무엇인가요?","options":[{"t":"새로 알게 된 것은 무엇인가?","correct":true},{"t":"글쓴이의 의견을 받치는 이유가 알맞은가?","mis":"K4-2-u4-X05"},{"t":"가장 오래 마음에 남는 장면은 어디인가?","mis":"K4-2-u4-X05"},{"t":"글쓴이는 몇 살일까?","mis":"K4-2-u4-X32"}],"explanation":["설명하는 글은 알려 주는 글이에요.","의견 글 질문은 빼요.","새로 안 것을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_basic#9','kor',4,2,'u4','L07','g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C33',2,'mc','auto','읽기 전·중·후에 할 수 있는 일을 모두 배웠어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X07','K4-2-u4-X06','K4-2-u4-X04']::text[],false,'{"seq":9,"concept":"K4-2-u4-C33","difficulty":2,"kind":"mc","stem":"읽기 전·중·후에 할 수 있는 일을 모두 배웠어요. 알맞은 생각은 무엇인가요?","options":[{"t":"글과 상황에 맞게 알맞은 것을 스스로 골라 쓴다","correct":true},{"t":"글을 읽을 때마다 전부 다 해야 한다","mis":"K4-2-u4-X07"},{"t":"질문을 많이 만들수록 잘 읽은 것이다","mis":"K4-2-u4-X06"},{"t":"짧은 글을 읽을 때는 아무것도 묻지 않아도 된다","mis":"K4-2-u4-X04"}],"explanation":["다 배웠다고 다 하는 건 아니에요.","그때그때 달라요.","골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_basic#10','kor',4,2,'u4','L07','g4_2_kor_u4_L07_basic','lesson_basic','K4-2-u4-C29',3,'error','auto','세 친구가 「다 읽은 뒤에 할 수 있는 일」을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X30','K4-2-u4-X31']::text[],false,'{"seq":10,"concept":"K4-2-u4-C29","difficulty":3,"kind":"error","stem":"세 친구가 「다 읽은 뒤에 할 수 있는 일」을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「제목을 보고 무슨 내용일지 짐작해.」","correct":true,"mis_target":"K4-2-u4-X30"},{"t":"친구 가 — 「읽은 내용을 짧게 간추려.」","mis":"K4-2-u4-X31"},{"t":"친구 나 — 「더 알고 싶어진 것을 떠올려.」","mis":"K4-2-u4-X31"}],"explanation":["다 읽은 뒤의 일을 찾아요.","짐작하기는 읽기 전이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_challenge#1','kor',4,2,'u4','L07','g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C26',2,'sa','auto','글을 읽는 과정은 읽기 전, 읽기 중, 읽기 (  )(으)로 나누어 볼 수 있어요. 빈칸에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u4-C26","difficulty":2,"kind":"sa","stem":"글을 읽는 과정은 읽기 전, 읽기 중, 읽기 (  )(으)로 나누어 볼 수 있어요. 빈칸에 알맞은 한 글자를 쓰세요.","answer":["후"],"explanation":["전, 중 다음이에요.","다 읽은 뒤예요.","‘후’예요."],"mis":"K4-2-u4-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_challenge#2','kor',4,2,'u4','L07','g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C28',2,'blank','auto','읽는 동안에는 각 부분에서 가장 (  ) 문장을 찾아요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u4-X37','K4-2-u4-X39']::text[],false,'{"seq":2,"concept":"K4-2-u4-C28","difficulty":2,"kind":"blank","stem":"읽는 동안에는 각 부분에서 가장 (  ) 문장을 찾아요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"중요한","correct":true},{"t":"긴","mis":"K4-2-u4-X37"},{"t":"재미있는","mis":"K4-2-u4-X39"},{"t":"첫","mis":"K4-2-u4-X37"}],"explanation":["길이로 찾지 않아요.","재미로도 찾지 않아요.","‘중요한’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_challenge#3','kor',4,2,'u4','L07','g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C30',3,'mc','auto','다음 질문 가운데 글을 다 읽은 뒤에야 답할 수 있는 것은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":3,"concept":"K4-2-u4-C30","difficulty":3,"kind":"mc","stem":"다음 질문 가운데 글을 다 읽은 뒤에야 답할 수 있는 것은 무엇인가요?","options":[{"t":"이 글을 읽고 더 알고 싶어진 것은 무엇인가?","correct":true},{"t":"제목을 보니 무슨 내용일 것 같은가?","mis":"K4-2-u4-X31"},{"t":"이 주제에 대해 내가 아는 것은 무엇인가?","mis":"K4-2-u4-X31"},{"t":"이 책 표지는 무슨 색인가?","mis":"K4-2-u4-X32"}],"explanation":["제목만으로 답할 수 있는 건 빼요.","읽기와 상관없는 것도 빼요.","다 읽어야 궁금한 게 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_challenge#4','kor',4,2,'u4','L07','g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C33',3,'mc','auto','짧은 학교 안내문을 읽을 때와 두꺼운 과학책을 조사하려고 읽을 때를 두고 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X07','K4-2-u4-X06','K4-2-u4-X02']::text[],false,'{"seq":4,"concept":"K4-2-u4-C33","difficulty":3,"kind":"mc","stem":"짧은 학교 안내문을 읽을 때와 두꺼운 과학책을 조사하려고 읽을 때를 두고 알맞게 말한 것은 무엇인가요?","options":[{"t":"읽는 글과 목적이 다르니 필요한 질문도 달라진다","correct":true},{"t":"어떤 글이든 일곱 가지 활동을 똑같이 다 한다","mis":"K4-2-u4-X07"},{"t":"안내문은 짧으니 질문을 더 많이 만들어야 한다","mis":"K4-2-u4-X06"},{"t":"두꺼운 책은 질문 없이 빨리 읽어야 한다","mis":"K4-2-u4-X02"}],"explanation":["글이 달라요.","목적도 달라요.","필요한 질문도 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_challenge#5','kor',4,2,'u4','L07','g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C31',3,'mc','auto','바람이 잘 부는 길가에 민들레가 줄지어 피어 있는 까닭을 글에서 찾아 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X33']::text[],false,'{"seq":5,"concept":"K4-2-u4-C31","difficulty":3,"kind":"mc","stem":"바람이 잘 부는 길가에 민들레가 줄지어 피어 있는 까닭을 글에서 찾아 바르게 말한 것은 무엇인가요?","options":[{"t":"털 달린 씨앗이 바람을 타고 날아가 퍼지기 때문이다","correct":true},{"t":"길가의 흙에만 양분이 있기 때문이다","mis":"K4-2-u4-X33"},{"t":"사람들이 길가에 씨앗을 심기 때문이다","mis":"K4-2-u4-X33"},{"t":"민들레가 길을 따라 걸어 다니기 때문이다","mis":"K4-2-u4-X33"}],"explanation":["6번 문장의 「여기」를 찾아요.","앞 문장들을 이어요.","바람을 타고 퍼져요."],"asset":{"type":"passage","lines":["1 봄에 핀 노란 민들레꽃이 지고 나면 그 자리에 하얗고 동그란 공이 생깁니다.","2 이 공은 꽃이 시든 것이 아니라 씨앗이 잔뜩 모여 있는 것입니다.","3 씨앗 하나하나에는 가는 털이 부챗살처럼 붙어 있습니다.","4 이 털이 낙하산처럼 공기를 받아 씨앗을 공중에 띄웁니다.","5 그래서 민들레는 스스로 걸어 다니지 못해도 멀리까지 퍼질 수 있습니다.","6 바람이 잘 부는 길가에 민들레가 줄지어 피어 있는 까닭이 여기에 있습니다."],"title":"설명하는 글 「민들레 씨앗의 여행」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_challenge#6','kor',4,2,'u4','L07','g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C26',3,'ox','auto','「짐작한 것과 맞는지 확인하며 읽기」는 읽기 전에 하는 활동이에요.',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":6,"concept":"K4-2-u4-C26","difficulty":3,"kind":"ox","stem":"「짐작한 것과 맞는지 확인하며 읽기」는 읽기 전에 하는 활동이에요.","answer":"X","reason_options":[{"t":"글을 읽는 동안에야 짐작과 견주어 확인할 수 있기 때문에","correct":true},{"t":"읽기 전에 미리 확인해 두어야 하기 때문에","mis":"K4-2-u4-X30"}],"mis":"K4-2-u4-X30","explanation":["확인하려면 읽어야 해요.","읽는 동안의 일이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_challenge#7','kor',4,2,'u4','L07','g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C32',3,'mc','auto','「민들레 씨앗의 여행」을 읽을 때 떠올리기에 어울리지 「않는」 질문은 무엇인가요?',ARRAY['K4-2-u4-X05']::text[],false,'{"seq":7,"concept":"K4-2-u4-C32","difficulty":3,"kind":"mc","stem":"「민들레 씨앗의 여행」을 읽을 때 떠올리기에 어울리지 「않는」 질문은 무엇인가요?","options":[{"t":"글쓴이의 의견을 받치는 이유가 알맞은가?","correct":true},{"t":"이 글은 무엇에 대해 알려 주고 있나?","mis":"K4-2-u4-X05"},{"t":"새로 알게 된 것은 무엇인가?","mis":"K4-2-u4-X05"},{"t":"각 부분에서 가장 중요한 문장은 무엇인가?","mis":"K4-2-u4-X05"}],"explanation":["이 글은 설명하는 글이에요.","의견을 내세운 글이 아니에요.","이유 질문은 어울리지 않아요."],"asset":{"type":"passage","lines":["1 봄에 핀 노란 민들레꽃이 지고 나면 그 자리에 하얗고 동그란 공이 생깁니다.","2 이 공은 꽃이 시든 것이 아니라 씨앗이 잔뜩 모여 있는 것입니다.","3 씨앗 하나하나에는 가는 털이 부챗살처럼 붙어 있습니다.","4 이 털이 낙하산처럼 공기를 받아 씨앗을 공중에 띄웁니다.","5 그래서 민들레는 스스로 걸어 다니지 못해도 멀리까지 퍼질 수 있습니다.","6 바람이 잘 부는 길가에 민들레가 줄지어 피어 있는 까닭이 여기에 있습니다."],"title":"설명하는 글 「민들레 씨앗의 여행」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_challenge#8','kor',4,2,'u4','L07','g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C28',4,'mc','auto','민들레 글을 다시 읽으며 「각 부분에서 가장 중요한 문장은 무엇인가?」에 답한 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X37','K4-2-u4-X32']::text[],false,'{"seq":8,"concept":"K4-2-u4-C28","difficulty":4,"kind":"mc","stem":"민들레 글을 다시 읽으며 「각 부분에서 가장 중요한 문장은 무엇인가?」에 답한 것으로 알맞은 것은 무엇인가요?","options":[{"t":"3번과 4번 — 털이 낙하산처럼 공기를 받아 씨앗을 띄운다","correct":true},{"t":"1번 — 봄에 노란 민들레꽃이 핀다","mis":"K4-2-u4-X37"},{"t":"6번 — 길가에 민들레가 줄지어 피어 있다","mis":"K4-2-u4-X37"},{"t":"글이 모두 여섯 줄이다","mis":"K4-2-u4-X32"}],"explanation":["글이 알려 주려는 것이 뭘까요?","멀리 퍼지는 방법이에요.","털과 공기 문장이에요."],"asset":{"type":"passage","lines":["1 봄에 핀 노란 민들레꽃이 지고 나면 그 자리에 하얗고 동그란 공이 생깁니다.","2 이 공은 꽃이 시든 것이 아니라 씨앗이 잔뜩 모여 있는 것입니다.","3 씨앗 하나하나에는 가는 털이 부챗살처럼 붙어 있습니다.","4 이 털이 낙하산처럼 공기를 받아 씨앗을 공중에 띄웁니다.","5 그래서 민들레는 스스로 걸어 다니지 못해도 멀리까지 퍼질 수 있습니다.","6 바람이 잘 부는 길가에 민들레가 줄지어 피어 있는 까닭이 여기에 있습니다."],"title":"설명하는 글 「민들레 씨앗의 여행」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_challenge#9','kor',4,2,'u4','L07','g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C33',4,'mc','auto','읽기 과정을 되돌아보는 것을 두고 친구들이 말했어요. 가장 알맞게 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X06','K4-2-u4-X07','K4-2-u4-X04']::text[],false,'{"seq":9,"concept":"K4-2-u4-C33","difficulty":4,"kind":"mc","stem":"읽기 과정을 되돌아보는 것을 두고 친구들이 말했어요. 가장 알맞게 말한 친구는 누구인가요?","options":[{"t":"「나는 오늘 짧은 글이라 짐작하기와 간추리기만 했어. 그 글엔 그게 필요했거든.」","correct":true},{"t":"「나는 질문을 열 개 만들었으니 가장 잘 읽었어.」","mis":"K4-2-u4-X06"},{"t":"「일곱 가지를 하나라도 빠뜨리면 처음부터 다시 읽어야 해.」","mis":"K4-2-u4-X07"},{"t":"「질문은 시험 볼 때만 하는 거야.」","mis":"K4-2-u4-X04"}],"explanation":["개수가 아니에요.","빠짐없이도 아니에요.","그 글에 필요한 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L07_challenge#10','kor',4,2,'u4','L07','g4_2_kor_u4_L07_challenge','lesson_challenge','K4-2-u4-C30',4,'essay','teacher','「민들레 씨앗의 여행」을 읽기 전·중·후에 스스로 던질 질문을 하나씩 쓰고, 왜 그 단계에 알맞은지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C30","difficulty":4,"kind":"essay","stem":"「민들레 씨앗의 여행」을 읽기 전·중·후에 스스로 던질 질문을 하나씩 쓰고, 왜 그 단계에 알맞은지 쓰세요.","answer_guide":{"answer":"예: 읽기 전 — 「제목을 보니 씨앗이 어디로 가는 이야기일까?」(아직 읽지 않아도 제목만 보고 답할 수 있다). 읽기 중 — 「씨앗이 멀리 가는 방법이 내가 짐작한 것과 같은가?」(읽는 동안 짐작과 견줄 수 있다). 읽기 후 — 「읽고 더 알고 싶어진 것은 무엇인가?」(다 읽어야 궁금한 것이 생긴다).","scoring_points":["읽기 전·중·후 질문을 하나씩 썼는가","각 질문이 그 단계에서 답할 수 있는 질문인가","왜 그 단계에 알맞은지 썼는가"]},"explanation":["전 — 제목으로","중 — 짐작과 견주기","후 — 간추리기·궁금한 것"],"asset":{"type":"passage","lines":["1 봄에 핀 노란 민들레꽃이 지고 나면 그 자리에 하얗고 동그란 공이 생깁니다.","2 이 공은 꽃이 시든 것이 아니라 씨앗이 잔뜩 모여 있는 것입니다.","3 씨앗 하나하나에는 가는 털이 부챗살처럼 붙어 있습니다.","4 이 털이 낙하산처럼 공기를 받아 씨앗을 공중에 띄웁니다.","5 그래서 민들레는 스스로 걸어 다니지 못해도 멀리까지 퍼질 수 있습니다.","6 바람이 잘 부는 길가에 민들레가 줄지어 피어 있는 까닭이 여기에 있습니다."],"title":"설명하는 글 「민들레 씨앗의 여행」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_basic#1','kor',4,2,'u4','L09','g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C34',1,'mc','auto','설명하는 글을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X34']::text[],false,'{"seq":1,"concept":"K4-2-u4-C34","difficulty":1,"kind":"mc","stem":"설명하는 글을 바르게 말한 것은 무엇인가요?","options":[{"t":"어떤 것을 알기 쉽게 알려 주는 글","correct":true},{"t":"글쓴이의 느낌만 짧게 적은 글","mis":"K4-2-u4-X34"},{"t":"있었던 일을 날짜 차례로 적은 일기","mis":"K4-2-u4-X34"},{"t":"읽는 사람에게 무조건 하라고 시키는 글","mis":"K4-2-u4-X34"}],"explanation":["조립 설명서를 떠올려요.","무엇을 알려 줘요.","알기 쉽게 알려 주는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_basic#2','kor',4,2,'u4','L09','g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C35',1,'mc','auto','지렁이가 지나간 자리에 남는 것은 무엇인가요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":2,"concept":"K4-2-u4-C35","difficulty":1,"kind":"mc","stem":"지렁이가 지나간 자리에 남는 것은 무엇인가요?","options":[{"t":"가늘고 긴 굴","correct":true},{"t":"물웅덩이","mis":"K4-2-u4-X35"},{"t":"나뭇잎 더미","mis":"K4-2-u4-X35"},{"t":"작은 돌무더기","mis":"K4-2-u4-X35"}],"explanation":["5번 문장을 봐요.","지나간 자리예요.","굴이 남아요."],"asset":{"type":"passage","lines":["1 비가 온 뒤 길바닥에서 지렁이를 본 적이 있을 것입니다.","2 지렁이는 대부분의 시간을 땅속에서 지냅니다.","3 지렁이는 땅속을 지나가면서 흙을 먹습니다.","4 흙 속에 섞인 나뭇잎 조각이나 썩은 뿌리에서 양분을 얻기 때문입니다.","5 지렁이가 지나간 자리에는 가늘고 긴 굴이 남습니다.","6 이 굴을 따라 공기와 물이 땅속 깊은 곳까지 스며듭니다."],"title":"설명하는 글 「지렁이가 하는 일」 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_basic#3','kor',4,2,'u4','L09','g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C36',1,'match','auto','글에 나온 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u4-C36","difficulty":1,"kind":"match","stem":"글에 나온 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"양분","r":"살아가고 자라는 데 필요한 성분"},{"l":"스며들다","r":"속으로 배어 들어가다"},{"l":"뒤섞이다","r":"여럿이 한데 마구 섞이다"}],"mis":"K4-2-u4-X36","explanation":["낱말이 나온 줄을 찾아요.","앞뒤 문장을 읽어요.","뜻을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_basic#4','kor',4,2,'u4','L09','g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C38',1,'ox','auto','글을 간추릴 때는 글에 나온 문장을 모두 옮겨 적어요.',ARRAY['K4-2-u4-X38']::text[],false,'{"seq":4,"concept":"K4-2-u4-C38","difficulty":1,"kind":"ox","stem":"글을 간추릴 때는 글에 나온 문장을 모두 옮겨 적어요.","answer":"X","reason_options":[{"t":"각 부분의 중심 문장을 모아 짧게 정리하는 것이 간추리기이기 때문에","correct":true},{"t":"하나라도 빠뜨리면 간추린 것이 아니기 때문에","mis":"K4-2-u4-X38"}],"mis":"K4-2-u4-X38","explanation":["간추리기는 짧게예요.","중심 문장을 모아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_basic#5','kor',4,2,'u4','L09','g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C35',2,'mc','auto','지렁이가 많이 사는 땅이 식물이 자라기 좋은 땅이 되는 까닭은 무엇인가요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":5,"concept":"K4-2-u4-C35","difficulty":2,"kind":"mc","stem":"지렁이가 많이 사는 땅이 식물이 자라기 좋은 땅이 되는 까닭은 무엇인가요?","options":[{"t":"굴로 공기와 물이 들어가고, 똥이 흙에 양분을 섞어 주기 때문에","correct":true},{"t":"땅이 늘 따뜻해지기 때문에","mis":"K4-2-u4-X35"},{"t":"다른 벌레가 모두 사라지기 때문에","mis":"K4-2-u4-X35"},{"t":"지렁이가 식물 뿌리를 먹어 없애기 때문에","mis":"K4-2-u4-X35"}],"explanation":["굴로 무엇이 들어가나요?","똥에는 무엇이 섞였나요?","두 가지를 이어요."],"asset":{"type":"passage","lines":["7 식물의 뿌리도 숨을 쉽니다.","8 그래서 공기가 잘 드나드는 흙에서 뿌리가 더 잘 자랍니다.","9 지렁이는 먹은 흙을 몸 밖으로 내놓습니다.","10 이때 나온 똥은 잘게 부서지고 양분과 뒤섞여 있습니다.","11 그래서 지렁이가 많이 사는 땅은 식물이 자라기에 좋은 땅이 됩니다.","12 땅속에서 조용히 지나다니는 작은 동물이 흙을 돌보고 있었던 것입니다."],"title":"설명하는 글 「지렁이가 하는 일」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_basic#6','kor',4,2,'u4','L09','g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C37',2,'mc','auto','1~4번 문장에서 가장 중요한 문장은 무엇인가요?',ARRAY['K4-2-u4-X37']::text[],false,'{"seq":6,"concept":"K4-2-u4-C37","difficulty":2,"kind":"mc","stem":"1~4번 문장에서 가장 중요한 문장은 무엇인가요?","options":[{"t":"지렁이는 땅속을 지나가면서 흙을 먹습니다.","correct":true},{"t":"비가 온 뒤 길바닥에서 지렁이를 본 적이 있을 것입니다.","mis":"K4-2-u4-X37"},{"t":"흙 속에 섞인 나뭇잎 조각이나 썩은 뿌리에서 양분을 얻기 때문입니다.","mis":"K4-2-u4-X37"},{"t":"지렁이는 대부분의 시간을 땅속에서 지냅니다.","mis":"K4-2-u4-X37"}],"explanation":["없으면 뜻이 통하지 않는 문장이에요.","4번은 3번을 풀어 줘요.","3번이 중심이에요."],"asset":{"type":"passage","lines":["1 비가 온 뒤 길바닥에서 지렁이를 본 적이 있을 것입니다.","2 지렁이는 대부분의 시간을 땅속에서 지냅니다.","3 지렁이는 땅속을 지나가면서 흙을 먹습니다.","4 흙 속에 섞인 나뭇잎 조각이나 썩은 뿌리에서 양분을 얻기 때문입니다.","5 지렁이가 지나간 자리에는 가늘고 긴 굴이 남습니다.","6 이 굴을 따라 공기와 물이 땅속 깊은 곳까지 스며듭니다."],"title":"설명하는 글 「지렁이가 하는 일」 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_basic#7','kor',4,2,'u4','L09','g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C38',2,'mc','auto','글을 간추리는 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u4-X38','K4-2-u4-X39','K4-2-u4-X37']::text[],false,'{"seq":7,"concept":"K4-2-u4-C38","difficulty":2,"kind":"mc","stem":"글을 간추리는 알맞은 방법은 무엇인가요?","options":[{"t":"각 부분의 중심 문장을 모아 짧게 정리한다","correct":true},{"t":"글에 나온 문장을 모두 옮겨 적는다","mis":"K4-2-u4-X38"},{"t":"가장 재미있었던 부분만 적는다","mis":"K4-2-u4-X39"},{"t":"맨 첫 문장만 옮겨 적는다","mis":"K4-2-u4-X37"}],"explanation":["모두 옮기기는 아니에요.","재미있는 것만도 아니에요.","중심 문장을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_basic#8','kor',4,2,'u4','L09','g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C39',2,'mc','auto','「오늘 내가 어떻게 읽었는지」 표시할 때 알맞은 태도는 무엇인가요?',ARRAY['K4-2-u4-X40','K4-2-u4-X41','K4-2-u4-X04']::text[],false,'{"seq":8,"concept":"K4-2-u4-C39","difficulty":2,"kind":"mc","stem":"「오늘 내가 어떻게 읽었는지」 표시할 때 알맞은 태도는 무엇인가요?","options":[{"t":"솔직하게 표시하고, 표시하지 못한 줄을 다음에 해 볼 일로 삼는다","correct":true},{"t":"점수가 잘 나오게 모든 줄에 표시한다","mis":"K4-2-u4-X40"},{"t":"빨리 끝내려고 읽지 않고 표시한다","mis":"K4-2-u4-X41"},{"t":"표시는 쓸모없으니 하지 않는다","mis":"K4-2-u4-X04"}],"explanation":["여기에는 점수가 없어요.","솔직하게 해요.","남은 줄이 다음 할 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_basic#9','kor',4,2,'u4','L09','g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C40',2,'mc','auto','「지렁이가 하는 일」을 읽고 말한 것 가운데 「더 알고 싶어진 것」은 무엇인가요?',ARRAY['K4-2-u4-X58']::text[],false,'{"seq":9,"concept":"K4-2-u4-C40","difficulty":2,"kind":"mc","stem":"「지렁이가 하는 일」을 읽고 말한 것 가운데 「더 알고 싶어진 것」은 무엇인가요?","options":[{"t":"지렁이가 하루에 얼마나 움직이는지","correct":true},{"t":"지렁이 똥이 흙을 좋게 만든다는 것","mis":"K4-2-u4-X58"},{"t":"식물 뿌리도 숨을 쉰다는 것","mis":"K4-2-u4-X58"},{"t":"지렁이는 땅속을 지나가며 흙을 먹는다는 것","mis":"K4-2-u4-X58"}],"explanation":["글에 나온 것은 새로 안 것이에요.","글에 없는 궁금한 것을 찾아요.","얼마나 움직이는지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_basic#10','kor',4,2,'u4','L09','g4_2_kor_u4_L09_basic','lesson_basic','K4-2-u4-C34',3,'error','auto','설명하는 글의 예를 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X34','K4-2-u4-X05']::text[],false,'{"seq":10,"concept":"K4-2-u4-C34","difficulty":3,"kind":"error","stem":"설명하는 글의 예를 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「친구에게 쓴 생일 축하 편지도 설명하는 글이야.」","correct":true,"mis_target":"K4-2-u4-X34"},{"t":"친구 가 — 「장난감 조립 설명서는 설명하는 글이야.」","mis":"K4-2-u4-X05"},{"t":"친구 나 — 「떡볶이 만드는 조리법도 설명하는 글이야.」","mis":"K4-2-u4-X05"}],"explanation":["알기 쉽게 알려 주나요?","축하 편지는 마음을 전해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_challenge#1','kor',4,2,'u4','L09','g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C36',2,'sa','auto','「살아가고 자라는 데 필요한 성분」을 뜻하는 두 글자 낱말을 글에서 찾아 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u4-C36","difficulty":2,"kind":"sa","stem":"「살아가고 자라는 데 필요한 성분」을 뜻하는 두 글자 낱말을 글에서 찾아 쓰세요.","answer":["양분"],"explanation":["4번 문장을 봐요.","썩은 뿌리에서 얻어요.","‘양분’이에요."],"asset":{"type":"passage","lines":["1 비가 온 뒤 길바닥에서 지렁이를 본 적이 있을 것입니다.","2 지렁이는 대부분의 시간을 땅속에서 지냅니다.","3 지렁이는 땅속을 지나가면서 흙을 먹습니다.","4 흙 속에 섞인 나뭇잎 조각이나 썩은 뿌리에서 양분을 얻기 때문입니다.","5 지렁이가 지나간 자리에는 가늘고 긴 굴이 남습니다.","6 이 굴을 따라 공기와 물이 땅속 깊은 곳까지 스며듭니다."],"title":"설명하는 글 「지렁이가 하는 일」 앞부분"},"mis":"K4-2-u4-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_challenge#2','kor',4,2,'u4','L09','g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C37',2,'blank','auto','그 문장이 없으면 그 부분의 뜻이 통하지 않는 문장을 (  ) 문장이라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u4-X37','K4-2-u4-X39']::text[],false,'{"seq":2,"concept":"K4-2-u4-C37","difficulty":2,"kind":"blank","stem":"그 문장이 없으면 그 부분의 뜻이 통하지 않는 문장을 (  ) 문장이라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"중심","correct":true},{"t":"첫","mis":"K4-2-u4-X37"},{"t":"마지막","mis":"K4-2-u4-X37"},{"t":"재미있는","mis":"K4-2-u4-X39"}],"explanation":["자리로 정하지 않아요.","재미로도 아니에요.","‘중심’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_challenge#3','kor',4,2,'u4','L09','g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C35',3,'mc','auto','「뿌리가 공기가 잘 드나드는 흙에서 더 잘 자란다」는 것과 지렁이 굴을 이어 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":3,"concept":"K4-2-u4-C35","difficulty":3,"kind":"mc","stem":"「뿌리가 공기가 잘 드나드는 흙에서 더 잘 자란다」는 것과 지렁이 굴을 이어 알맞게 말한 것은 무엇인가요?","options":[{"t":"지렁이 굴로 공기가 땅속에 들어가니 뿌리가 숨 쉬기 좋아진다","correct":true},{"t":"지렁이 굴에 물이 고여 뿌리가 썩는다","mis":"K4-2-u4-X35"},{"t":"지렁이가 뿌리를 먹어 흙이 비워진다","mis":"K4-2-u4-X35"},{"t":"굴과 뿌리는 서로 아무 상관이 없다","mis":"K4-2-u4-X35"}],"explanation":["6번 — 굴로 공기와 물이 들어가요.","7·8번 — 뿌리도 숨을 쉬어요.","둘을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_challenge#4','kor',4,2,'u4','L09','g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C38',3,'mc','auto','「지렁이가 하는 일」을 가장 알맞게 간추린 것은 무엇인가요?',ARRAY['K4-2-u4-X39','K4-2-u4-X37','K4-2-u4-X35']::text[],false,'{"seq":4,"concept":"K4-2-u4-C38","difficulty":3,"kind":"mc","stem":"「지렁이가 하는 일」을 가장 알맞게 간추린 것은 무엇인가요?","options":[{"t":"지렁이는 흙을 먹으며 땅속을 지나다니고, 그 굴로 공기와 물이 들어가며, 똥이 흙에 양분을 섞어 준다","correct":true},{"t":"비가 온 뒤 길바닥에서 지렁이를 볼 수 있다","mis":"K4-2-u4-X39"},{"t":"지렁이 똥은 잘게 부서져 있다","mis":"K4-2-u4-X37"},{"t":"지렁이는 눈이 없어도 밝고 어두운 것을 안다","mis":"K4-2-u4-X35"}],"explanation":["곁가지 한 줄이 아니에요.","글에 없는 것도 아니에요.","중심 문장을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_challenge#5','kor',4,2,'u4','L09','g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C40',3,'mc','auto','「지렁이가 하는 일」을 읽고 글과 연결하기를 바르게 한 말은 무엇인가요?',ARRAY['K4-2-u4-X58','K4-2-u4-X32']::text[],false,'{"seq":5,"concept":"K4-2-u4-C40","difficulty":3,"kind":"mc","stem":"「지렁이가 하는 일」을 읽고 글과 연결하기를 바르게 한 말은 무엇인가요?","options":[{"t":"「식물 뿌리도 숨을 쉰다는 것이 새로웠어. 지렁이가 겨울에는 어디서 지내는지 더 알고 싶어.」","correct":true},{"t":"「지렁이는 징그러우니 다시는 안 읽을래.」","mis":"K4-2-u4-X58"},{"t":"「글이 모두 몇 줄인지 세어 봤어.」","mis":"K4-2-u4-X32"},{"t":"「다 아는 내용이라 새로 안 것도 궁금한 것도 없어.」","mis":"K4-2-u4-X58"}],"explanation":["새로 안 것을 말해요.","더 알고 싶은 것도 말해요.","둘 다 글과 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_challenge#6','kor',4,2,'u4','L09','g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C39',3,'ox','auto','읽기 과정 점검에서 표시하지 못한 줄이 있으면 실패한 것이니 감추는 것이 좋아요.',ARRAY['K4-2-u4-X40']::text[],false,'{"seq":6,"concept":"K4-2-u4-C39","difficulty":3,"kind":"ox","stem":"읽기 과정 점검에서 표시하지 못한 줄이 있으면 실패한 것이니 감추는 것이 좋아요.","answer":"X","reason_options":[{"t":"표시하지 못한 줄이 다음에 해 볼 일을 알려 주기 때문에","correct":true},{"t":"모든 줄에 표시해야 잘 읽은 것이기 때문에","mis":"K4-2-u4-X40"}],"mis":"K4-2-u4-X40","explanation":["점수가 없는 점검이에요.","남은 줄이 길잡이예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_challenge#7','kor',4,2,'u4','L09','g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C34',3,'mc','auto','「개미가 줄지어 가는 까닭」은 어떤 글인가요?',ARRAY['K4-2-u4-X05','K4-2-u4-X34']::text[],false,'{"seq":7,"concept":"K4-2-u4-C34","difficulty":3,"kind":"mc","stem":"「개미가 줄지어 가는 까닭」은 어떤 글인가요?","options":[{"t":"개미가 줄지어 가는 까닭을 알기 쉽게 알려 주는 설명하는 글","correct":true},{"t":"개미를 보며 든 느낌을 노래한 시","mis":"K4-2-u4-X05"},{"t":"개미를 보호하자는 글쓴이의 의견을 내세운 글","mis":"K4-2-u4-X05"},{"t":"개미를 본 날의 일을 날짜 차례로 적은 일기","mis":"K4-2-u4-X34"}],"explanation":["무엇을 알려 주나요?","느낌이나 의견이 아니에요.","설명하는 글이에요."],"asset":{"type":"passage","lines":["1 개미가 한 줄로 길게 지나가는 모습을 본 적이 있을 것입니다.","2 먹이를 찾은 개미는 집으로 돌아가면서 땅에 냄새를 남깁니다.","3 다른 개미들은 더듬이로 이 냄새를 맡고 같은 길을 따라갑니다.","4 그래서 개미들은 말을 하지 않아도 먹이가 있는 곳을 찾아갑니다.","5 먹이가 다 떨어지면 냄새가 점점 옅어지고, 줄도 흩어집니다."],"title":"설명하는 글 「개미가 줄지어 가는 까닭」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_challenge#8','kor',4,2,'u4','L09','g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C38',4,'mc','auto','「개미가 줄지어 가는 까닭」을 가장 알맞게 간추린 것은 무엇인가요?',ARRAY['K4-2-u4-X39','K4-2-u4-X37','K4-2-u4-X35']::text[],false,'{"seq":8,"concept":"K4-2-u4-C38","difficulty":4,"kind":"mc","stem":"「개미가 줄지어 가는 까닭」을 가장 알맞게 간추린 것은 무엇인가요?","options":[{"t":"먹이를 찾은 개미가 남긴 냄새를 다른 개미들이 따라가서 줄을 짓는다","correct":true},{"t":"개미가 한 줄로 지나가는 모습을 본 적이 있다","mis":"K4-2-u4-X39"},{"t":"개미에게는 더듬이가 있다","mis":"K4-2-u4-X37"},{"t":"먹이가 떨어지면 개미는 모두 집에서 쉰다","mis":"K4-2-u4-X35"}],"explanation":["2·3번이 중심이에요.","냄새를 남기고, 따라가요.","한 문장으로 모아요."],"asset":{"type":"passage","lines":["1 개미가 한 줄로 길게 지나가는 모습을 본 적이 있을 것입니다.","2 먹이를 찾은 개미는 집으로 돌아가면서 땅에 냄새를 남깁니다.","3 다른 개미들은 더듬이로 이 냄새를 맡고 같은 길을 따라갑니다.","4 그래서 개미들은 말을 하지 않아도 먹이가 있는 곳을 찾아갑니다.","5 먹이가 다 떨어지면 냄새가 점점 옅어지고, 줄도 흩어집니다."],"title":"설명하는 글 「개미가 줄지어 가는 까닭」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_challenge#9','kor',4,2,'u4','L09','g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C40',4,'mc','auto','「개미가 줄지어 가는 까닭」을 읽고 더 알고 싶어진 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X58','K4-2-u4-X32']::text[],false,'{"seq":9,"concept":"K4-2-u4-C40","difficulty":4,"kind":"mc","stem":"「개미가 줄지어 가는 까닭」을 읽고 더 알고 싶어진 것으로 알맞은 것은 무엇인가요?","options":[{"t":"비가 와서 냄새가 씻겨 나가면 개미는 어떻게 길을 찾을까?","correct":true},{"t":"먹이를 찾은 개미는 땅에 냄새를 남긴다","mis":"K4-2-u4-X58"},{"t":"개미들은 냄새를 따라 같은 길을 간다","mis":"K4-2-u4-X58"},{"t":"이 글을 쓴 사람의 이름은 무엇일까?","mis":"K4-2-u4-X32"}],"explanation":["글에 나온 것은 새로 안 것이에요.","글을 읽고 생긴 궁금한 것이에요.","비 오는 날을 궁금해했어요."],"asset":{"type":"passage","lines":["1 개미가 한 줄로 길게 지나가는 모습을 본 적이 있을 것입니다.","2 먹이를 찾은 개미는 집으로 돌아가면서 땅에 냄새를 남깁니다.","3 다른 개미들은 더듬이로 이 냄새를 맡고 같은 길을 따라갑니다.","4 그래서 개미들은 말을 하지 않아도 먹이가 있는 곳을 찾아갑니다.","5 먹이가 다 떨어지면 냄새가 점점 옅어지고, 줄도 흩어집니다."],"title":"설명하는 글 「개미가 줄지어 가는 까닭」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L09_challenge#10','kor',4,2,'u4','L09','g4_2_kor_u4_L09_challenge','lesson_challenge','K4-2-u4-C37',4,'essay','teacher','「지렁이가 하는 일」 뒷부분(7~12)에서 중심 문장을 찾아 쓰고, 그 문장을 고른 까닭과 「문장을 모두 옮겨 적기」가 간추리기가 아닌 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C37","difficulty":4,"kind":"essay","stem":"「지렁이가 하는 일」 뒷부분(7~12)에서 중심 문장을 찾아 쓰고, 그 문장을 고른 까닭과 「문장을 모두 옮겨 적기」가 간추리기가 아닌 까닭을 쓰세요.","answer_guide":{"answer":"예: 중심 문장은 「그래서 지렁이가 많이 사는 땅은 식물이 자라기에 좋은 땅이 됩니다.」이다. 뿌리가 숨을 쉰다는 것과 똥에 양분이 섞여 있다는 것이 모두 이 문장을 풀어 주고 있어서, 이 문장이 없으면 뒷부분의 뜻이 통하지 않기 때문이다. 문장을 모두 옮겨 적으면 글이 짧아지지 않고 무엇이 중요한지 드러나지 않으므로 간추리기가 아니다.","scoring_points":["중심 문장을 바르게 찾았는가","다른 문장이 중심 문장을 풀어 준다는 까닭을 썼는가","모두 옮겨 적기가 간추리기가 아닌 까닭을 썼는가"]},"explanation":["「그래서」를 살펴요.","나머지가 풀어 줘요.","간추리기는 짧게예요."],"asset":{"type":"passage","lines":["7 식물의 뿌리도 숨을 쉽니다.","8 그래서 공기가 잘 드나드는 흙에서 뿌리가 더 잘 자랍니다.","9 지렁이는 먹은 흙을 몸 밖으로 내놓습니다.","10 이때 나온 똥은 잘게 부서지고 양분과 뒤섞여 있습니다.","11 그래서 지렁이가 많이 사는 땅은 식물이 자라기에 좋은 땅이 됩니다.","12 땅속에서 조용히 지나다니는 작은 동물이 흙을 돌보고 있었던 것입니다."],"title":"설명하는 글 「지렁이가 하는 일」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_basic#1','kor',4,2,'u4','L11','g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C41',1,'mc','auto','의견을 제시하는 글을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X42','K4-2-u4-X05']::text[],false,'{"seq":1,"concept":"K4-2-u4-C41","difficulty":1,"kind":"mc","stem":"의견을 제시하는 글을 바르게 말한 것은 무엇인가요?","options":[{"t":"어떤 문제에 대한 글쓴이의 생각을 밝혀 쓴 글","correct":true},{"t":"읽는 사람이 반드시 그대로 따라야 하는 글","mis":"K4-2-u4-X42"},{"t":"어떤 것을 알기 쉽게 알려 주기만 하는 글","mis":"K4-2-u4-X05"},{"t":"글쓴이가 겪은 일을 날짜 차례로 적은 글","mis":"K4-2-u4-X42"}],"explanation":["글쓴이의 생각이 들어 있어요.","따를지는 읽는 사람이 정해요.","생각을 밝혀 쓴 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_basic#2','kor',4,2,'u4','L11','g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C43',1,'mc','auto','병훈이의 의견은 무엇인가요?',ARRAY['K4-2-u4-X44']::text[],false,'{"seq":2,"concept":"K4-2-u4-C43","difficulty":1,"kind":"mc","stem":"병훈이의 의견은 무엇인가요?","options":[{"t":"우리가 쓰는 물건에 이름을 써 두자","correct":true},{"t":"교실 뒤 상자를 없애자","mis":"K4-2-u4-X44"},{"t":"물건을 학교에 가져오지 말자","mis":"K4-2-u4-X44"},{"t":"주운 물건은 모두 선생님께 드리자","mis":"K4-2-u4-X44"}],"explanation":["「~라고 생각합니다」를 찾아요.","3번 문장이에요.","이름을 써 두자는 의견이에요."],"asset":{"type":"passage","lines":["1 4학년 친구들, 안녕하세요? 저는 병훈입니다.","2 교실 뒤 상자에는 주인을 찾지 못한 물건이 쌓여 있습니다.","   지난주에도 줄넘기와 물병이 그대로 남았습니다.","3 저는 우리가 쓰는 물건에 이름을 써 두면 좋겠다고 생각합니다.","4 첫째, 이름이 적혀 있으면 물건을 주운 친구가 바로 돌려줄 수 있습니다.","5 둘째, 이름을 쓰는 동안 이것이 내 물건이라는 것을 한 번 더 생각하게 됩니다.","6 작은 일이지만 물건을 찾느라 쓰는 시간을 모두가 아낄 수 있습니다.","7 오늘 집에 가서 필통과 물병부터 살펴보면 어떨까요?"],"title":"병훈이의 글 「함께 쓰는 물건에 이름을 써 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_basic#3','kor',4,2,'u4','L11','g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C42',1,'ox','auto','제목 「함께 쓰는 물건에 이름을 써 주세요」만 보고도 글쓴이가 무엇을 하자고 할지 짐작할 수 있어요.',ARRAY['K4-2-u4-X43']::text[],false,'{"seq":3,"concept":"K4-2-u4-C42","difficulty":1,"kind":"ox","stem":"제목 「함께 쓰는 물건에 이름을 써 주세요」만 보고도 글쓴이가 무엇을 하자고 할지 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"제목에 글쓴이의 의견이 그대로 드러나 있기 때문에","correct":true},{"t":"제목을 보면 글쓴이가 든 이유가 몇 개인지까지 알 수 있기 때문에","mis":"K4-2-u4-X43"}],"mis":"K4-2-u4-X43","explanation":["제목을 읽어요.","이름을 써 달래요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_basic#4','kor',4,2,'u4','L11','g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C49',1,'mc','auto','읽기 과정 점검표를 채울 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X40','K4-2-u4-X41']::text[],false,'{"seq":4,"concept":"K4-2-u4-C49","difficulty":1,"kind":"mc","stem":"읽기 과정 점검표를 채울 때 알맞은 것은 무엇인가요?","options":[{"t":"「아니요」가 나온 곳으로 돌아가 다시 읽어 본다","correct":true},{"t":"모두 「예」가 되게 답한다","mis":"K4-2-u4-X40"},{"t":"빨리 채우는 것이 가장 중요하다","mis":"K4-2-u4-X41"},{"t":"선생님께 보여 드리려고 깔끔하게 채운다","mis":"K4-2-u4-X40"}],"explanation":["점검표는 나를 위한 거예요.","「아니요」가 길잡이예요.","그곳을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_basic#5','kor',4,2,'u4','L11','g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C44',2,'mc','auto','병훈이가 의견을 받치려고 든 이유는 무엇인가요?',ARRAY['K4-2-u4-X45']::text[],false,'{"seq":5,"concept":"K4-2-u4-C44","difficulty":2,"kind":"mc","stem":"병훈이가 의견을 받치려고 든 이유는 무엇인가요?","options":[{"t":"이름이 적혀 있으면 물건을 주운 친구가 바로 돌려줄 수 있다","correct":true},{"t":"교실 뒤 상자에 주인 없는 물건이 쌓여 있다","mis":"K4-2-u4-X45"},{"t":"오늘 집에 가서 필통과 물병부터 살펴보자","mis":"K4-2-u4-X45"},{"t":"지난주에 줄넘기와 물병이 그대로 남았다","mis":"K4-2-u4-X45"}],"explanation":["「첫째」로 시작하는 줄을 봐요.","상자 이야기는 문제 상황이에요.","돌려줄 수 있다는 것이 이유예요."],"asset":{"type":"passage","lines":["1 4학년 친구들, 안녕하세요? 저는 병훈입니다.","2 교실 뒤 상자에는 주인을 찾지 못한 물건이 쌓여 있습니다.","   지난주에도 줄넘기와 물병이 그대로 남았습니다.","3 저는 우리가 쓰는 물건에 이름을 써 두면 좋겠다고 생각합니다.","4 첫째, 이름이 적혀 있으면 물건을 주운 친구가 바로 돌려줄 수 있습니다.","5 둘째, 이름을 쓰는 동안 이것이 내 물건이라는 것을 한 번 더 생각하게 됩니다.","6 작은 일이지만 물건을 찾느라 쓰는 시간을 모두가 아낄 수 있습니다.","7 오늘 집에 가서 필통과 물병부터 살펴보면 어떨까요?"],"title":"병훈이의 글 「함께 쓰는 물건에 이름을 써 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_basic#6','kor',4,2,'u4','L11','g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C45',2,'mc','auto','이름을 쓰자는 의견을 받치기에 알맞지 「않은」 이유는 무엇인가요?',ARRAY['K4-2-u4-X46','K4-2-u4-X47']::text[],false,'{"seq":6,"concept":"K4-2-u4-C45","difficulty":2,"kind":"mc","stem":"이름을 쓰자는 의견을 받치기에 알맞지 「않은」 이유는 무엇인가요?","options":[{"t":"이름을 쓰면 글씨 연습이 된다","correct":true},{"t":"잃어버려도 주인에게 돌아올 수 있다","mis":"K4-2-u4-X46"},{"t":"물건을 찾느라 쓰는 시간을 줄일 수 있다","mis":"K4-2-u4-X46"},{"t":"내 물건이라는 것을 한 번 더 생각하게 된다","mis":"K4-2-u4-X47"}],"explanation":["이름을 쓰면 좋은 점인가요?","글씨 연습은 다른 이야기예요.","의견과 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_basic#7','kor',4,2,'u4','L11','g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C46',2,'mc','auto','의견을 제시하는 글을 읽는 태도로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X48','K4-2-u4-X49']::text[],false,'{"seq":7,"concept":"K4-2-u4-C46","difficulty":2,"kind":"mc","stem":"의견을 제시하는 글을 읽는 태도로 알맞은 것은 무엇인가요?","options":[{"t":"이유가 의견과 이어지는지 따져 보며 읽는다","correct":true},{"t":"글에 실렸으니 옳은 말이라고 믿는다","mis":"K4-2-u4-X48"},{"t":"의견 글은 일단 틀렸다고 보고 읽는다","mis":"K4-2-u4-X49"},{"t":"깔끔하게 쓰인 글이면 그대로 따른다","mis":"K4-2-u4-X48"}],"explanation":["무조건 믿지 않아요.","무조건 의심하지도 않아요.","이유를 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_basic#8','kor',4,2,'u4','L11','g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C47',2,'mc','auto','글쓴이와 내 의견을 견줄 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X48','K4-2-u4-X49']::text[],false,'{"seq":8,"concept":"K4-2-u4-C47","difficulty":2,"kind":"mc","stem":"글쓴이와 내 의견을 견줄 때 알맞은 것은 무엇인가요?","options":[{"t":"같은 곳과 다른 곳을 찾고, 다르면 내 이유를 마련한다","correct":true},{"t":"글로 쓰여 있으니 그대로 따른다","mis":"K4-2-u4-X48"},{"t":"글쓴이와 다르면 내 생각을 바로 버린다","mis":"K4-2-u4-X48"},{"t":"의견 글은 무조건 반대하며 읽는다","mis":"K4-2-u4-X49"}],"explanation":["같은 곳을 찾아요.","다른 곳도 찾아요.","내 이유를 마련해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_basic#9','kor',4,2,'u4','L11','g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C48',2,'match','auto','의견을 제시하는 글을 읽는 과정과 그때 떠올릴 질문을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K4-2-u4-C48","difficulty":2,"kind":"match","stem":"의견을 제시하는 글을 읽는 과정과 그때 떠올릴 질문을 알맞게 이으세요.","pairs":[{"l":"읽기 전","r":"제목을 보니 무엇을 하자는 글일까?"},{"l":"읽기 중","r":"이유가 의견과 이어지는가?"},{"l":"읽기 후","r":"내 생각과 어디가 같고 어디가 다른가?"}],"mis":"K4-2-u4-X30","explanation":["전 — 제목으로 짐작","중 — 의견과 이유","후 — 내 생각과 견주기"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_basic#10','kor',4,2,'u4','L11','g4_2_kor_u4_L11_basic','lesson_basic','K4-2-u4-C46',3,'error','auto','의견 글을 읽는 태도를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X48','K4-2-u4-X49']::text[],false,'{"seq":10,"concept":"K4-2-u4-C46","difficulty":3,"kind":"error","stem":"의견 글을 읽는 태도를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「글로 깔끔하게 실렸으면 언제나 옳은 말이야.」","correct":true,"mis_target":"K4-2-u4-X48"},{"t":"친구 가 — 「이유가 의견과 이어지는지 따져 봐야 해.」","mis":"K4-2-u4-X49"},{"t":"친구 다 — 「무조건 의심하며 읽는 것도 아니야.」","mis":"K4-2-u4-X49"}],"explanation":["깔끔함과 옳음은 달라요.","이유를 따져요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_challenge#1','kor',4,2,'u4','L11','g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C43',2,'sa','auto','병훈이의 글에서 「저는 ~라고 생각합니다」로 끝나는 의견 문장은 몇 번 문장인지 숫자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u4-C43","difficulty":2,"kind":"sa","stem":"병훈이의 글에서 「저는 ~라고 생각합니다」로 끝나는 의견 문장은 몇 번 문장인지 숫자로 쓰세요.","answer":["3"],"explanation":["「생각합니다」를 찾아요.","물건에 이름을 써 두자는 문장이에요.","3번이에요."],"asset":{"type":"passage","lines":["1 4학년 친구들, 안녕하세요? 저는 병훈입니다.","2 교실 뒤 상자에는 주인을 찾지 못한 물건이 쌓여 있습니다.","   지난주에도 줄넘기와 물병이 그대로 남았습니다.","3 저는 우리가 쓰는 물건에 이름을 써 두면 좋겠다고 생각합니다.","4 첫째, 이름이 적혀 있으면 물건을 주운 친구가 바로 돌려줄 수 있습니다.","5 둘째, 이름을 쓰는 동안 이것이 내 물건이라는 것을 한 번 더 생각하게 됩니다.","6 작은 일이지만 물건을 찾느라 쓰는 시간을 모두가 아낄 수 있습니다.","7 오늘 집에 가서 필통과 물병부터 살펴보면 어떨까요?"],"title":"병훈이의 글 「함께 쓰는 물건에 이름을 써 주세요」"},"mis":"K4-2-u4-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_challenge#2','kor',4,2,'u4','L11','g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C42',2,'blank','auto','제목만 보고는 글쓴이가 무엇을 하자고 할지 짐작할 수 있지만, (  )은/는 글을 읽어 봐야 알 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u4-X43']::text[],false,'{"seq":2,"concept":"K4-2-u4-C42","difficulty":2,"kind":"blank","stem":"제목만 보고는 글쓴이가 무엇을 하자고 할지 짐작할 수 있지만, (  )은/는 글을 읽어 봐야 알 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"글쓴이가 든 이유","correct":true},{"t":"글쓴이가 하자는 것","mis":"K4-2-u4-X43"},{"t":"글의 제목","mis":"K4-2-u4-X43"},{"t":"글이 다루는 문제","mis":"K4-2-u4-X43"}],"explanation":["제목에는 의견이 보여요.","이유는 제목에 없어요.","읽어야 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_challenge#3','kor',4,2,'u4','L11','g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C45',3,'mc','auto','이유가 알맞은지 따질 때 바른 생각은 무엇인가요?',ARRAY['K4-2-u4-X47','K4-2-u4-X46']::text[],false,'{"seq":3,"concept":"K4-2-u4-C45","difficulty":3,"kind":"mc","stem":"이유가 알맞은지 따질 때 바른 생각은 무엇인가요?","options":[{"t":"내가 찬성하든 반대하든, 그 이유가 의견과 이어지는지로 따진다","correct":true},{"t":"내가 찬성하는 의견이면 이유도 모두 알맞다","mis":"K4-2-u4-X47"},{"t":"이유가 길게 쓰여 있으면 알맞다","mis":"K4-2-u4-X46"},{"t":"이유가 많을수록 알맞다","mis":"K4-2-u4-X46"}],"explanation":["찬반으로 정하지 않아요.","길이나 개수도 아니에요.","의견과 이어지나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_challenge#4','kor',4,2,'u4','L11','g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C44',3,'mc','auto','은재가 의견을 받치려고 든 이유를 바르게 고른 것은 무엇인가요?',ARRAY['K4-2-u4-X45','K4-2-u4-X44']::text[],false,'{"seq":4,"concept":"K4-2-u4-C44","difficulty":3,"kind":"mc","stem":"은재가 의견을 받치려고 든 이유를 바르게 고른 것은 무엇인가요?","options":[{"t":"연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 된다","correct":true},{"t":"우리 반 쓰레기통에 한 면만 쓴 종이가 자주 버려져 있다","mis":"K4-2-u4-X45"},{"t":"내일부터 종이를 버리기 전에 뒷면을 살펴보자","mis":"K4-2-u4-X45"},{"t":"저는 4학년 은재입니다","mis":"K4-2-u4-X44"}],"explanation":["「첫째」로 시작해요.","쓰레기통 이야기는 문제 상황이에요.","마지막 줄은 권하는 말이에요."],"asset":{"type":"passage","lines":["1 안녕하세요? 저는 4학년 은재입니다.","2 우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.","3 저는 한 면만 쓴 종이를 교실 뒤 이면지 상자에 모으면 좋겠다고 생각합니다.","4 첫째, 연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 됩니다.","5 둘째, 버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다.","6 내일부터 종이를 버리기 전에 뒷면을 한 번 살펴보면 어떨까요?"],"title":"은재의 글 「다 쓴 종이는 이면지 상자에 모아요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_challenge#5','kor',4,2,'u4','L11','g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C45',3,'mc','auto','은재의 의견을 받치기에 알맞지 「않은」 이유는 무엇인가요?',ARRAY['K4-2-u4-X46','K4-2-u4-X47']::text[],false,'{"seq":5,"concept":"K4-2-u4-C45","difficulty":3,"kind":"mc","stem":"은재의 의견을 받치기에 알맞지 「않은」 이유는 무엇인가요?","options":[{"t":"이면지 상자를 예쁘게 꾸밀 수 있다","correct":true},{"t":"버리는 종이가 줄어든다","mis":"K4-2-u4-X46"},{"t":"연습할 종이를 쉽게 구할 수 있다","mis":"K4-2-u4-X46"},{"t":"종이를 한 번 더 쓰게 된다","mis":"K4-2-u4-X47"}],"explanation":["종이를 모으면 좋은 점인가요?","상자 꾸미기는 다른 이야기예요.","의견과 이어지지 않아요."],"asset":{"type":"passage","lines":["1 안녕하세요? 저는 4학년 은재입니다.","2 우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.","3 저는 한 면만 쓴 종이를 교실 뒤 이면지 상자에 모으면 좋겠다고 생각합니다.","4 첫째, 연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 됩니다.","5 둘째, 버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다.","6 내일부터 종이를 버리기 전에 뒷면을 한 번 살펴보면 어떨까요?"],"title":"은재의 글 「다 쓴 종이는 이면지 상자에 모아요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_challenge#6','kor',4,2,'u4','L11','g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C46',3,'ox','auto','의견 글을 바르게 읽으려면 글쓴이의 의견을 일단 틀렸다고 보고 읽어야 해요.',ARRAY['K4-2-u4-X49']::text[],false,'{"seq":6,"concept":"K4-2-u4-C46","difficulty":3,"kind":"ox","stem":"의견 글을 바르게 읽으려면 글쓴이의 의견을 일단 틀렸다고 보고 읽어야 해요.","answer":"X","reason_options":[{"t":"무조건 믿는 것도 무조건 의심하는 것도 아니라 이유를 따져 보는 것이기 때문에","correct":true},{"t":"글쓴이는 늘 자기에게 좋은 쪽으로만 쓰기 때문에","mis":"K4-2-u4-X49"}],"mis":"K4-2-u4-X49","explanation":["무조건 의심은 아니에요.","이유를 따져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_challenge#7','kor',4,2,'u4','L11','g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C48',3,'mc','auto','설명하는 글과 견주어, 의견을 제시하는 글을 읽을 때 특히 달라지는 질문은 무엇인가요?',ARRAY['K4-2-u4-X05','K4-2-u4-X32']::text[],false,'{"seq":7,"concept":"K4-2-u4-C48","difficulty":3,"kind":"mc","stem":"설명하는 글과 견주어, 의견을 제시하는 글을 읽을 때 특히 달라지는 질문은 무엇인가요?","options":[{"t":"글쓴이의 의견은 무엇이고, 이유가 의견과 이어지는가?","correct":true},{"t":"무엇을 어떻게 알려 주고 있나?","mis":"K4-2-u4-X05"},{"t":"가장 오래 마음에 남는 장면은 어디인가?","mis":"K4-2-u4-X05"},{"t":"글이 모두 몇 줄인가?","mis":"K4-2-u4-X32"}],"explanation":["의견 글에는 의견이 있어요.","이유도 있어요.","둘이 이어지는지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_challenge#8','kor',4,2,'u4','L11','g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C47',4,'mc','auto','은재의 의견에 대해 내 생각을 가장 알맞게 견주어 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X48','K4-2-u4-X49','K4-2-u4-X47']::text[],false,'{"seq":8,"concept":"K4-2-u4-C47","difficulty":4,"kind":"mc","stem":"은재의 의견에 대해 내 생각을 가장 알맞게 견주어 말한 것은 무엇인가요?","options":[{"t":"「종이를 다시 쓰자는 생각은 같아. 그런데 나는 모둠마다 집게로 묶어 두는 게 낫다고 생각해. 왜냐하면 종이가 흩어지지 않기 때문이야.」","correct":true},{"t":"「글로 썼으니 은재 말이 다 맞아.」","mis":"K4-2-u4-X48"},{"t":"「은재 글은 분명 틀린 데가 있을 거야.」","mis":"K4-2-u4-X49"},{"t":"「나는 은재랑 안 친하니까 반대야.」","mis":"K4-2-u4-X47"}],"explanation":["같은 곳을 말해요.","다른 곳도 말해요.","내 이유를 붙여요."],"asset":{"type":"passage","lines":["1 안녕하세요? 저는 4학년 은재입니다.","2 우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.","3 저는 한 면만 쓴 종이를 교실 뒤 이면지 상자에 모으면 좋겠다고 생각합니다.","4 첫째, 연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 됩니다.","5 둘째, 버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다.","6 내일부터 종이를 버리기 전에 뒷면을 한 번 살펴보면 어떨까요?"],"title":"은재의 글 「다 쓴 종이는 이면지 상자에 모아요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_challenge#9','kor',4,2,'u4','L11','g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C49',4,'mc','auto','점검표의 「이유가 의견과 이어지는지 따져 보았다」에 「아니요」가 나왔어요. 가장 알맞은 다음 행동은 무엇인가요?',ARRAY['K4-2-u4-X40','K4-2-u4-X41']::text[],false,'{"seq":9,"concept":"K4-2-u4-C49","difficulty":4,"kind":"mc","stem":"점검표의 「이유가 의견과 이어지는지 따져 보았다」에 「아니요」가 나왔어요. 가장 알맞은 다음 행동은 무엇인가요?","options":[{"t":"글로 돌아가 이유가 나온 줄을 다시 읽으며 따져 본다","correct":true},{"t":"「예」로 고쳐 적어 점검표를 깔끔하게 만든다","mis":"K4-2-u4-X40"},{"t":"다음 칸으로 빨리 넘어가 점검표를 끝낸다","mis":"K4-2-u4-X41"},{"t":"점검표를 지우고 새 점검표에 「예」만 적는다","mis":"K4-2-u4-X40"}],"explanation":["「아니요」는 길잡이예요.","그 자리로 돌아가요.","다시 읽고 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L11_challenge#10','kor',4,2,'u4','L11','g4_2_kor_u4_L11_challenge','lesson_challenge','K4-2-u4-C45',4,'essay','teacher','병훈이의 글을 읽고 「이름을 쓰면 글씨 연습이 된다」가 왜 알맞은 이유가 아닌지 쓰고, 의견을 받치는 알맞은 이유를 하나 더 지어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C45","difficulty":4,"kind":"essay","stem":"병훈이의 글을 읽고 「이름을 쓰면 글씨 연습이 된다」가 왜 알맞은 이유가 아닌지 쓰고, 의견을 받치는 알맞은 이유를 하나 더 지어 쓰세요.","answer_guide":{"answer":"예: 글씨 연습은 물건에 이름을 써 두자는 의견대로 했을 때 좋아지는 점이 아니라서, 의견과 이어지지 않으므로 알맞은 이유가 아니다. 알맞은 이유 — 「비슷한 물병이 여럿이어도 이름을 보면 서로 바뀌지 않는다.」","scoring_points":["글씨 연습이 의견과 이어지지 않는다고 썼는가","의견대로 하면 좋아지는 점을 이유로 지어 썼는가","찬반이 아니라 이어지는지로 따졌는가"]},"explanation":["이름을 쓰면 좋은 점인가요?","의견과 이어져야 해요.","좋아지는 점을 이유로 써요."],"asset":{"type":"passage","lines":["1 4학년 친구들, 안녕하세요? 저는 병훈입니다.","2 교실 뒤 상자에는 주인을 찾지 못한 물건이 쌓여 있습니다.","   지난주에도 줄넘기와 물병이 그대로 남았습니다.","3 저는 우리가 쓰는 물건에 이름을 써 두면 좋겠다고 생각합니다.","4 첫째, 이름이 적혀 있으면 물건을 주운 친구가 바로 돌려줄 수 있습니다.","5 둘째, 이름을 쓰는 동안 이것이 내 물건이라는 것을 한 번 더 생각하게 됩니다.","6 작은 일이지만 물건을 찾느라 쓰는 시간을 모두가 아낄 수 있습니다.","7 오늘 집에 가서 필통과 물병부터 살펴보면 어떨까요?"],"title":"병훈이의 글 「함께 쓰는 물건에 이름을 써 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_basic#1','kor',4,2,'u4','L13','g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C54',1,'mc','auto','시 「받아쓰기」에서 집에 돌아와 다시 써 보면 어떻게 되나요?',ARRAY['K4-2-u4-X57']::text[],false,'{"seq":1,"concept":"K4-2-u4-C54","difficulty":1,"kind":"mc","stem":"시 「받아쓰기」에서 집에 돌아와 다시 써 보면 어떻게 되나요?","options":[{"t":"또박또박 잘 써진다","correct":true},{"t":"글자가 자꾸 미끄러진다","mis":"K4-2-u4-X57"},{"t":"아는 글자도 낯설어진다","mis":"K4-2-u4-X57"},{"t":"연필이 부러진다","mis":"K4-2-u4-X57"}],"explanation":["「집에 돌아와」를 찾아요.","아무 일도 없었다는 듯","잘 써져요."],"asset":{"type":"passage","lines":["시험지를 받으면","아는 글자도 갑자기 낯설어진다","집에서는 술술 썼는데","연필 끝에서만 글자가 자꾸 미끄러진다","집에 돌아와 다시 써 보면","아무 일도 없었다는 듯","또박또박 잘 써진다"],"title":"시 「받아쓰기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_basic#2','kor',4,2,'u4','L13','g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C55',1,'mc','auto','사물에 높임말을 쓰지 않고 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X53','K4-2-u4-X59']::text[],false,'{"seq":2,"concept":"K4-2-u4-C55","difficulty":1,"kind":"mc","stem":"사물에 높임말을 쓰지 않고 바르게 말한 것은 무엇인가요?","options":[{"t":"「그 연필은 오백 원이에요.」","correct":true},{"t":"「그 연필은 오백 원이세요.」","mis":"K4-2-u4-X53"},{"t":"「그 연필께서는 오백 원이에요.」","mis":"K4-2-u4-X59"},{"t":"「그 연필은 오백 원이시옵니다.」","mis":"K4-2-u4-X53"}],"explanation":["연필과 값은 사물이에요.","「-시-」를 붙이지 않아요.","「이에요」로 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_basic#3','kor',4,2,'u4','L13','g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C57',1,'match','auto','외국어와 바꿔 쓸 우리말을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u4-C57","difficulty":1,"kind":"match","stem":"외국어와 바꿔 쓸 우리말을 알맞게 이으세요.","pairs":[{"l":"메모","r":"쪽지"},{"l":"스케줄","r":"일정"},{"l":"체크하다","r":"표시하다"}],"mis":"K4-2-u4-X55","explanation":["우리말로 풀어 봐요.","적어 두는 종이 · 할 일의 차례","뜻이 같은 말을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_basic#4','kor',4,2,'u4','L13','g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C58',1,'mc','auto','받침이 ㄻ인 낱말은 무엇인가요?',ARRAY['K4-2-u4-X56']::text[],false,'{"seq":4,"concept":"K4-2-u4-C58","difficulty":1,"kind":"mc","stem":"받침이 ㄻ인 낱말은 무엇인가요?","options":[{"t":"옮기다","correct":true},{"t":"맑다","mis":"K4-2-u4-X56"},{"t":"넓다","mis":"K4-2-u4-X56"},{"t":"앉다","mis":"K4-2-u4-X56"}],"explanation":["ㄹ과 ㅁ이 나란히 있어요.","맑다는 ㄺ, 넓다는 ㄼ","‘옮기다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_basic#5','kor',4,2,'u4','L13','g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C50',2,'mc','auto','시에 대한 생각이나 느낌을 나타내는 방법으로 알맞지 「않은」 것은 무엇인가요?',ARRAY['K4-2-u4-X50']::text[],false,'{"seq":5,"concept":"K4-2-u4-C50","difficulty":2,"kind":"mc","stem":"시에 대한 생각이나 느낌을 나타내는 방법으로 알맞지 「않은」 것은 무엇인가요?","options":[{"t":"친구가 고른 방법을 그대로 따라 하기","correct":true},{"t":"짧은 즉흥극으로 꾸며 보기","mis":"K4-2-u4-X50"},{"t":"시 속 아이에게 편지 쓰기","mis":"K4-2-u4-X50"},{"t":"가락을 붙여 노래로 부르기","mis":"K4-2-u4-X50"}],"explanation":["내 느낌을 나타내요.","방법은 여러 가지예요.","그대로 따라 하기는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_basic#6','kor',4,2,'u4','L13','g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C51',2,'mc','auto','친구가 나와 다른 방법으로 느낌을 나타냈어요. 알맞은 말은 무엇인가요?',ARRAY['K4-2-u4-X50','K4-2-u4-X12']::text[],false,'{"seq":6,"concept":"K4-2-u4-C51","difficulty":2,"kind":"mc","stem":"친구가 나와 다른 방법으로 느낌을 나타냈어요. 알맞은 말은 무엇인가요?","options":[{"t":"「왜 그 방법으로 나타냈는지 궁금해.」","correct":true},{"t":"「그 방법은 우리가 배운 것이 아니야.」","mis":"K4-2-u4-X50"},{"t":"「누구 방법이 제일 잘한 건지 정하자.」","mis":"K4-2-u4-X50"},{"t":"「네 방법은 틀렸어.」","mis":"K4-2-u4-X12"}],"explanation":["방법에는 등수가 없어요.","틀린 것이 아니에요.","까닭을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_basic#7','kor',4,2,'u4','L13','g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C52',2,'mc','auto','질문 사다리 타기 놀이의 질문 카드에 적기 알맞은 질문은 무엇인가요?',ARRAY['K4-2-u4-X32','K4-2-u4-X28']::text[],false,'{"seq":7,"concept":"K4-2-u4-C52","difficulty":2,"kind":"mc","stem":"질문 사다리 타기 놀이의 질문 카드에 적기 알맞은 질문은 무엇인가요?","options":[{"t":"짐작한 내용과 글의 내용이 같았나요?","correct":true},{"t":"이 글은 몇 줄인가요?","mis":"K4-2-u4-X32"},{"t":"글쓴이는 몇 살일까요?","mis":"K4-2-u4-X28"},{"t":"글씨체가 예쁜가요?","mis":"K4-2-u4-X32"}],"explanation":["답하면 내 읽기가 드러나야 해요.","줄 수나 나이는 아니에요.","짐작과 견주는 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_basic#8','kor',4,2,'u4','L13','g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C53',2,'mc','auto','사다리 놀이에서 질문에 답할 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X51','K4-2-u4-X52','K4-2-u4-X06']::text[],false,'{"seq":8,"concept":"K4-2-u4-C53","difficulty":2,"kind":"mc","stem":"사다리 놀이에서 질문에 답할 때 알맞은 것은 무엇인가요?","options":[{"t":"내가 그렇게 읽었다고 말할 수 있으면 된다","correct":true},{"t":"질문을 많이 받은 사람이 이긴다","mis":"K4-2-u4-X51"},{"t":"빨리 답할수록 잘한 것이다","mis":"K4-2-u4-X52"},{"t":"질문 카드를 많이 만든 사람이 가장 잘 읽은 것이다","mis":"K4-2-u4-X06"}],"explanation":["이기는 놀이가 아니에요.","빠르기도 아니에요.","내 읽기를 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_basic#9','kor',4,2,'u4','L13','g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C56',2,'mc','auto','「저희 나라의 가을 하늘은 참 맑습니다.」에서 고쳐야 할 말은 무엇인가요?',ARRAY['K4-2-u4-X59','K4-2-u4-X53','K4-2-u4-X54']::text[],false,'{"seq":9,"concept":"K4-2-u4-C56","difficulty":2,"kind":"mc","stem":"「저희 나라의 가을 하늘은 참 맑습니다.」에서 고쳐야 할 말은 무엇인가요?","options":[{"t":"저희 나라 → 우리나라","correct":true},{"t":"가을 하늘 → 가을 하늘께서","mis":"K4-2-u4-X59"},{"t":"맑습니다 → 맑으십니다","mis":"K4-2-u4-X53"},{"t":"참 → 매우","mis":"K4-2-u4-X54"}],"explanation":["「저희」는 낮추는 말이에요.","나라는 낮추지 않아요.","‘우리나라’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_basic#10','kor',4,2,'u4','L13','g4_2_kor_u4_L13_basic','lesson_basic','K4-2-u4-C55',3,'error','auto','높임 표현을 두고 세 친구가 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X53','K4-2-u4-X59']::text[],false,'{"seq":10,"concept":"K4-2-u4-C55","difficulty":3,"kind":"error","stem":"높임 표현을 두고 세 친구가 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「할머니, 국이 식으셨어요.」","correct":true,"mis_target":"K4-2-u4-X53"},{"t":"친구 가 — 「선생님께서 교실에 오셨어요.」","mis":"K4-2-u4-X59"},{"t":"친구 나 — 「손님, 찾으시는 책은 저쪽에 있어요.」","mis":"K4-2-u4-X53"}],"explanation":["높일 것은 사람이에요.","국은 사물이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_challenge#1','kor',4,2,'u4','L13','g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C58',2,'sa','auto','낱말 「젊은이」에서 겹받침 ㄻ이 들어 있는 글자 하나를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u4-C58","difficulty":2,"kind":"sa","stem":"낱말 「젊은이」에서 겹받침 ㄻ이 들어 있는 글자 하나를 쓰세요.","answer":["젊"],"explanation":["받침을 살펴요.","ㄹ과 ㅁ이 나란히 있어요.","‘젊’이에요."],"mis":"K4-2-u4-X56"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_challenge#2','kor',4,2,'u4','L13','g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C57',2,'blank','auto','「내일 일정을 확인해요.」에서 「일정」은 외국어 (  )을/를 바꿔 쓴 우리말이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u4-X55']::text[],false,'{"seq":2,"concept":"K4-2-u4-C57","difficulty":2,"kind":"blank","stem":"「내일 일정을 확인해요.」에서 「일정」은 외국어 (  )을/를 바꿔 쓴 우리말이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"스케줄","correct":true},{"t":"메모","mis":"K4-2-u4-X55"},{"t":"체크","mis":"K4-2-u4-X55"},{"t":"리더","mis":"K4-2-u4-X55"}],"explanation":["할 일의 차례예요.","메모는 쪽지예요.","‘스케줄’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_challenge#3','kor',4,2,'u4','L13','g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C55',3,'mc','auto','「손님, 그 색연필은 다 팔리셨어요.」를 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u4-X59','K4-2-u4-X53']::text[],false,'{"seq":3,"concept":"K4-2-u4-C55","difficulty":3,"kind":"mc","stem":"「손님, 그 색연필은 다 팔리셨어요.」를 바르게 고친 것은 무엇인가요?","options":[{"t":"「손님, 그 색연필은 다 팔렸어요.」","correct":true},{"t":"「손님, 그 색연필께서는 다 팔리셨어요.」","mis":"K4-2-u4-X59"},{"t":"「손님, 그 색연필은 다 팔리시었어요.」","mis":"K4-2-u4-X53"},{"t":"「손님, 저희 색연필은 다 팔리셨어요.」","mis":"K4-2-u4-X53"}],"explanation":["높일 사람은 손님이에요.","색연필은 높이지 않아요.","「팔렸어요」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_challenge#4','kor',4,2,'u4','L13','g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C56',3,'mc','auto','외국에서 온 친구에게 우리나라를 소개할 때 알맞은 말은 무엇인가요?',ARRAY['K4-2-u4-X54','K4-2-u4-X59']::text[],false,'{"seq":4,"concept":"K4-2-u4-C56","difficulty":3,"kind":"mc","stem":"외국에서 온 친구에게 우리나라를 소개할 때 알맞은 말은 무엇인가요?","options":[{"t":"「우리나라는 산이 많아.」","correct":true},{"t":"「저희 나라는 산이 많아.」","mis":"K4-2-u4-X54"},{"t":"「저희 나라께서는 산이 많아.」","mis":"K4-2-u4-X59"},{"t":"「저의 나라는 산이 많아.」","mis":"K4-2-u4-X54"}],"explanation":["나라는 낮추지 않아요.","「께서」도 엉뚱해요.","‘우리나라’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_challenge#5','kor',4,2,'u4','L13','g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C50',3,'mc','auto','「받아쓰기」에 대한 느낌을 나타내는 방법을 두고 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X50','K4-2-u4-X11']::text[],false,'{"seq":5,"concept":"K4-2-u4-C50","difficulty":3,"kind":"mc","stem":"「받아쓰기」에 대한 느낌을 나타내는 방법을 두고 알맞게 말한 것은 무엇인가요?","options":[{"t":"그림·편지·노래·즉흥극 가운데 나에게 맞는 것을 고르고, 내가 생각한 다른 방법도 된다","correct":true},{"t":"그림으로 그린 것이 가장 잘한 방법이다","mis":"K4-2-u4-X50"},{"t":"배운 네 가지 말고 다른 방법은 쓰면 안 된다","mis":"K4-2-u4-X50"},{"t":"친구가 고른 방법을 그대로 따라 하는 것이 가장 좋다","mis":"K4-2-u4-X11"}],"explanation":["방법에 등수는 없어요.","목록은 닫혀 있지 않아요.","나에게 맞는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_challenge#6','kor',4,2,'u4','L13','g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C53',3,'ox','auto','질문 사다리 놀이에서 질문에 답을 못 하면 진 것이니 놀이를 그만두어요.',ARRAY['K4-2-u4-X52']::text[],false,'{"seq":6,"concept":"K4-2-u4-C53","difficulty":3,"kind":"ox","stem":"질문 사다리 놀이에서 질문에 답을 못 하면 진 것이니 놀이를 그만두어요.","answer":"X","reason_options":[{"t":"답을 못 하는 자리가 바로 다시 읽을 자리이고, 글을 펴서 찾아보고 답해도 되기 때문에","correct":true},{"t":"이 놀이는 질문에 빨리 답해서 이기는 놀이이기 때문에","mis":"K4-2-u4-X52"}],"mis":"K4-2-u4-X52","explanation":["이기고 지는 놀이가 아니에요.","답 못 한 곳은 다시 읽을 곳이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_challenge#7','kor',4,2,'u4','L13','g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C52',3,'mc','auto','어린이 신문 기사를 읽기 전에 먼저 하면 좋은 일은 무엇인가요?',ARRAY['K4-2-u4-X32','K4-2-u4-X06','K4-2-u4-X05']::text[],false,'{"seq":7,"concept":"K4-2-u4-C52","difficulty":3,"kind":"mc","stem":"어린이 신문 기사를 읽기 전에 먼저 하면 좋은 일은 무엇인가요?","options":[{"t":"설명하는 글인지 의견 글인지 가려내고 알맞은 질문을 고른다","correct":true},{"t":"기사가 모두 몇 줄인지 센다","mis":"K4-2-u4-X32"},{"t":"질문을 되도록 많이 만들어 둔다","mis":"K4-2-u4-X06"},{"t":"글의 종류와 상관없이 같은 질문 하나만 쓴다","mis":"K4-2-u4-X05"}],"explanation":["글의 종류를 먼저 봐요.","종류에 따라 질문이 달라요.","알맞은 질문을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_challenge#8','kor',4,2,'u4','L13','g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C57',4,'mc','auto','외국어 대신 우리말을 쓰는 까닭과 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X55','K4-2-u4-X53']::text[],false,'{"seq":8,"concept":"K4-2-u4-C57","difficulty":4,"kind":"mc","stem":"외국어 대신 우리말을 쓰는 까닭과 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"바꿔 쓸 우리말이 있으면 우리말로 써서 모르는 사람도 알아듣게 한다","correct":true},{"t":"외국어가 더 멋지게 들리니 되도록 외국어를 쓴다","mis":"K4-2-u4-X55"},{"t":"들어온 말은 하나도 빠짐없이 다 바꾸어야 한다","mis":"K4-2-u4-X55"},{"t":"외국어를 쓰면 높임말이 된다","mis":"K4-2-u4-X53"}],"explanation":["모르는 사람도 있어요.","바꿀 말이 있으면 바꿔요.","「빠짐없이 다」는 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_challenge#9','kor',4,2,'u4','L13','g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C58',4,'mc','auto','받침이 ㄻ인 낱말끼리 바르게 묶은 것은 무엇인가요?',ARRAY['K4-2-u4-X56']::text[],false,'{"seq":9,"concept":"K4-2-u4-C58","difficulty":4,"kind":"mc","stem":"받침이 ㄻ인 낱말끼리 바르게 묶은 것은 무엇인가요?","options":[{"t":"앎 · 삶다 · 젊은이","correct":true},{"t":"맑다 · 옮기다 · 앎","mis":"K4-2-u4-X56"},{"t":"넓다 · 삶다 · 젊은이","mis":"K4-2-u4-X56"},{"t":"앉다 · 젊은이 · 밟다","mis":"K4-2-u4-X56"}],"explanation":["하나씩 받침을 살펴요.","맑다 ㄺ · 넓다 ㄼ · 앉다 ㄵ","셋 다 ㄻ인 묶음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_L13_challenge#10','kor',4,2,'u4','L13','g4_2_kor_u4_L13_challenge','lesson_challenge','K4-2-u4-C55',4,'essay','teacher','「할머니, 국이 식으셨어요.」와 「저희 나라 노래를 들려줄게요.」를 바르게 고쳐 쓰고, 각각 왜 그렇게 고쳐야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C55","difficulty":4,"kind":"essay","stem":"「할머니, 국이 식으셨어요.」와 「저희 나라 노래를 들려줄게요.」를 바르게 고쳐 쓰고, 각각 왜 그렇게 고쳐야 하는지 쓰세요.","answer_guide":{"answer":"예: 「할머니, 국이 식었어요.」로 고친다. 국은 사물이라 높이지 않고, 높일 분인 할머니께는 말끝을 「-요」로 하면 되기 때문이다. 「우리나라 노래를 들려줄게요.」로 고친다. 나라는 남의 나라보다 낮출 수 없어 「저희 나라」가 아니라 「우리나라」라고 하기 때문이다.","scoring_points":["첫 문장에서 사물을 높이지 않게 고쳤는가","둘째 문장을 「우리나라」로 고쳤는가","각각 고친 까닭을 썼는가"]},"explanation":["국은 사물이에요.","나라는 낮추지 않아요.","까닭을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#1','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C34',1,'mc','auto','조립 설명서, 안내문, 조리법은 모두 어떤 글인가요?',ARRAY['K4-2-u4-X34','K4-2-u4-X05']::text[],false,'{"seq":1,"concept":"K4-2-u4-C34","difficulty":1,"kind":"mc","stem":"조립 설명서, 안내문, 조리법은 모두 어떤 글인가요?","options":[{"t":"설명하는 글","correct":true},{"t":"시","mis":"K4-2-u4-X34"},{"t":"의견을 제시하는 글","mis":"K4-2-u4-X05"},{"t":"일기","mis":"K4-2-u4-X34"}],"explanation":["무엇을 알려 주나요?","만드는 법, 가는 법을 알려요.","설명하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#2','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C8',1,'mc','auto','「소리」를 길게 불러 보면 그 속에서 헤엄쳐 나오는 것은 무엇인가요?',ARRAY['K4-2-u4-X09']::text[],false,'{"seq":2,"concept":"K4-2-u4-C8","difficulty":1,"kind":"mc","stem":"「소리」를 길게 불러 보면 그 속에서 헤엄쳐 나오는 것은 무엇인가요?","options":[{"t":"오리","correct":true},{"t":"조개","mis":"K4-2-u4-X09"},{"t":"노래","mis":"K4-2-u4-X09"},{"t":"고래","mis":"K4-2-u4-X09"}],"explanation":["「소오오오오리」로 늘여요.","뒤에 남는 소리예요.","‘오리’예요."],"asset":{"type":"passage","lines":["고래를 길게 불러 보면 / 고오오오오래","바다에서 오래 사는 고래 / 이름 속에 오래가 먼저 와 있었네","소리를 길게 불러 보면 / 소오오오오리","물 위에 동동 오리 한 마리 / 소리 속에서 헤엄쳐 나오네","길게 불러 보면 / 낱말 속에 숨어 있던 것들이 / 하나씩 고개를 드네"],"title":"시 「길게 불러 보면」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#3','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C29',1,'mc','auto','읽기 「후」에 하는 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":3,"concept":"K4-2-u4-C29","difficulty":1,"kind":"mc","stem":"읽기 「후」에 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"더 알고 싶어진 것을 떠올린다","correct":true},{"t":"제목과 차례를 보고 내용을 짐작한다","mis":"K4-2-u4-X30"},{"t":"그 주제에 대해 아는 것을 떠올린다","mis":"K4-2-u4-X30"},{"t":"짐작한 것이 맞는지 확인하며 읽는다","mis":"K4-2-u4-X30"}],"explanation":["다 읽은 뒤예요.","짐작·아는 것은 읽기 전이에요.","더 알고 싶은 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#4','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C17',1,'mc','auto','「선뜻 하지 못하고 잠깐 멈칫하다」는 뜻의 낱말은 무엇인가요?',ARRAY['K4-2-u4-X19','K4-2-u4-X36']::text[],false,'{"seq":4,"concept":"K4-2-u4-C17","difficulty":1,"kind":"mc","stem":"「선뜻 하지 못하고 잠깐 멈칫하다」는 뜻의 낱말은 무엇인가요?","options":[{"t":"머뭇거리다","correct":true},{"t":"멋쩍다","mis":"K4-2-u4-X19"},{"t":"뒤섞이다","mis":"K4-2-u4-X36"},{"t":"스며들다","mis":"K4-2-u4-X36"}],"explanation":["멈칫해요.","선뜻 못 해요.","‘머뭇거리다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#5','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C55',1,'mc','auto','사물을 높이지 않고 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X53','K4-2-u4-X59']::text[],false,'{"seq":5,"concept":"K4-2-u4-C55","difficulty":1,"kind":"mc","stem":"사물을 높이지 않고 바르게 말한 것은 무엇인가요?","options":[{"t":"「할머니, 국이 식었어요.」","correct":true},{"t":"「할머니, 국이 식으셨어요.」","mis":"K4-2-u4-X53"},{"t":"「할머니, 국께서 식었어요.」","mis":"K4-2-u4-X59"},{"t":"「할머니, 국이 식으시었어요.」","mis":"K4-2-u4-X53"}],"explanation":["국은 사물이에요.","할머니께는 「-요」로 말해요.","「식었어요」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#6','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C56',1,'mc','auto','나라를 말할 때 바르게 쓴 말은 무엇인가요?',ARRAY['K4-2-u4-X54']::text[],false,'{"seq":6,"concept":"K4-2-u4-C56","difficulty":1,"kind":"mc","stem":"나라를 말할 때 바르게 쓴 말은 무엇인가요?","options":[{"t":"우리나라","correct":true},{"t":"저희 나라","mis":"K4-2-u4-X54"},{"t":"저의 나라","mis":"K4-2-u4-X54"},{"t":"제 나라","mis":"K4-2-u4-X54"}],"explanation":["나라는 낮추지 않아요.","「저희」는 낮추는 말이에요.","‘우리나라’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#7','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C58',1,'mc','auto','겹받침 ㄻ이 들어 있는 낱말은 무엇인가요?',ARRAY['K4-2-u4-X56']::text[],false,'{"seq":7,"concept":"K4-2-u4-C58","difficulty":1,"kind":"mc","stem":"겹받침 ㄻ이 들어 있는 낱말은 무엇인가요?","options":[{"t":"삶다","correct":true},{"t":"밟다","mis":"K4-2-u4-X56"},{"t":"읽다","mis":"K4-2-u4-X56"},{"t":"얹다","mis":"K4-2-u4-X56"}],"explanation":["ㄹ과 ㅁ을 찾아요.","밟다 ㄼ · 읽다 ㄺ · 얹다 ㄵ","‘삶다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#8','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C11',1,'ox','auto','친구가 나와 다른 느낌을 말하면 「그건 틀렸어.」라고 바로잡아 줘요.',ARRAY['K4-2-u4-X08']::text[],false,'{"seq":8,"concept":"K4-2-u4-C11","difficulty":1,"kind":"ox","stem":"친구가 나와 다른 느낌을 말하면 「그건 틀렸어.」라고 바로잡아 줘요.","answer":"X","reason_options":[{"t":"느낌은 틀리는 것이 아니라 다를 수 있는 것이기 때문에","correct":true},{"t":"시마다 정해진 느낌이 하나씩 있기 때문에","mis":"K4-2-u4-X08"}],"mis":"K4-2-u4-X08","explanation":["느낌은 다를 수 있어요.","까닭을 물어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#9','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C10',2,'mc','auto','시에 대한 느낌을 친구가 알아듣게 말하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X14','K4-2-u4-X11','K4-2-u4-X10']::text[],false,'{"seq":9,"concept":"K4-2-u4-C10","difficulty":2,"kind":"mc","stem":"시에 대한 느낌을 친구가 알아듣게 말하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"시에서 마음에 든 줄을 짚어 가며 까닭을 함께 말한다","correct":true},{"t":"「좋았어.」 한마디만 말한다","mis":"K4-2-u4-X14"},{"t":"친구가 먼저 말한 느낌을 그대로 말한다","mis":"K4-2-u4-X11"},{"t":"가장 많이 나온 느낌을 내 느낌이라고 한다","mis":"K4-2-u4-X10"}],"explanation":["줄을 짚어요.","까닭을 붙여요.","그러면 알아들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#10','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C12',2,'sa','auto','「나무」를 길게 늘여 「나아아아무」라고 하면 뒤에 숨어 있는 낱말을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u4-C12","difficulty":2,"kind":"sa","stem":"「나무」를 길게 늘여 「나아아아무」라고 하면 뒤에 숨어 있는 낱말을 쓰세요.","answer":["아무"],"explanation":["앞 글자를 늘여요.","뒤에 남는 소리를 들어요.","‘아무’예요."],"mis":"K4-2-u4-X15"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#11','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C19',2,'mc','auto','수지 역할을 할 때 어울리는 말투는 무엇인가요?',ARRAY['K4-2-u4-X22','K4-2-u4-X21']::text[],false,'{"seq":11,"concept":"K4-2-u4-C19","difficulty":2,"kind":"mc","stem":"수지 역할을 할 때 어울리는 말투는 무엇인가요?","options":[{"t":"망설임 없이 또렷하고 빠르게","correct":true},{"t":"아주 작은 목소리로 우물쭈물","mis":"K4-2-u4-X22"},{"t":"친구를 놀리려는 듯 비웃으며","mis":"K4-2-u4-X21"},{"t":"울먹이며 느리게","mis":"K4-2-u4-X22"}],"explanation":["수지는 곧바로 말해요.","놀리려던 건 아니에요.","또렷하고 빠르게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#12','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C22',2,'mc','auto','역할놀이를 평가할 때 살펴볼 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X24','K4-2-u4-X25']::text[],false,'{"seq":12,"concept":"K4-2-u4-C22","difficulty":2,"kind":"mc","stem":"역할놀이를 평가할 때 살펴볼 것으로 알맞은 것은 무엇인가요?","options":[{"t":"인물의 말과 행동에 어울리는 말투로 했는가","correct":true},{"t":"누가 가장 웃겼는가","mis":"K4-2-u4-X24"},{"t":"목소리가 가장 큰 사람은 누구였는가","mis":"K4-2-u4-X25"},{"t":"누가 가장 빨리 끝냈는가","mis":"K4-2-u4-X24"}],"explanation":["웃기기가 아니에요.","크기도 아니에요.","인물에 어울렸나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#13','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C30',2,'mc','auto','「지렁이가 하는 일」을 읽기 전에 할 수 있는 질문은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X32']::text[],false,'{"seq":13,"concept":"K4-2-u4-C30","difficulty":2,"kind":"mc","stem":"「지렁이가 하는 일」을 읽기 전에 할 수 있는 질문은 무엇인가요?","options":[{"t":"지렁이에 대해 내가 이미 아는 것은 무엇인가?","correct":true},{"t":"지렁이 굴로 무엇이 들어가는가?","mis":"K4-2-u4-X31"},{"t":"글을 짧게 간추리면 무엇인가?","mis":"K4-2-u4-X31"},{"t":"이 글은 종이 몇 장에 실렸는가?","mis":"K4-2-u4-X32"}],"explanation":["아직 읽지 않았어요.","지금 답할 수 있나요?","아는 것을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#14','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C44',2,'mc','auto','병훈이의 글에서 의견을 받치는 이유가 나온 문장을 바르게 고른 것은 무엇인가요?',ARRAY['K4-2-u4-X45','K4-2-u4-X44']::text[],false,'{"seq":14,"concept":"K4-2-u4-C44","difficulty":2,"kind":"mc","stem":"병훈이의 글에서 의견을 받치는 이유가 나온 문장을 바르게 고른 것은 무엇인가요?","options":[{"t":"4번과 5번","correct":true},{"t":"2번과 7번","mis":"K4-2-u4-X45"},{"t":"1번과 3번","mis":"K4-2-u4-X44"},{"t":"3번과 7번","mis":"K4-2-u4-X45"}],"explanation":["「첫째, 둘째」를 찾아요.","2번은 문제 상황, 7번은 권하는 말","4번과 5번이에요."],"asset":{"type":"passage","lines":["1 4학년 친구들, 안녕하세요? 저는 병훈입니다.","2 교실 뒤 상자에는 주인을 찾지 못한 물건이 쌓여 있습니다.","   지난주에도 줄넘기와 물병이 그대로 남았습니다.","3 저는 우리가 쓰는 물건에 이름을 써 두면 좋겠다고 생각합니다.","4 첫째, 이름이 적혀 있으면 물건을 주운 친구가 바로 돌려줄 수 있습니다.","5 둘째, 이름을 쓰는 동안 이것이 내 물건이라는 것을 한 번 더 생각하게 됩니다.","6 작은 일이지만 물건을 찾느라 쓰는 시간을 모두가 아낄 수 있습니다.","7 오늘 집에 가서 필통과 물병부터 살펴보면 어떨까요?"],"title":"병훈이의 글 「함께 쓰는 물건에 이름을 써 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#15','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C38',2,'mc','auto','간추리기를 바르게 한 것은 무엇인가요?',ARRAY['K4-2-u4-X38','K4-2-u4-X39','K4-2-u4-X37']::text[],false,'{"seq":15,"concept":"K4-2-u4-C38","difficulty":2,"kind":"mc","stem":"간추리기를 바르게 한 것은 무엇인가요?","options":[{"t":"각 부분의 중심 문장을 모아 짧게 정리했다","correct":true},{"t":"글을 처음부터 끝까지 그대로 옮겨 적었다","mis":"K4-2-u4-X38"},{"t":"가장 재미있었던 한 줄만 적었다","mis":"K4-2-u4-X39"},{"t":"모르는 낱말만 모아 적었다","mis":"K4-2-u4-X37"}],"explanation":["모두 옮기기가 아니에요.","재미있는 것만도 아니에요.","중심 문장을 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#16','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C53',2,'mc','auto','질문 사다리 놀이를 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X51','K4-2-u4-X52','K4-2-u4-X06']::text[],false,'{"seq":16,"concept":"K4-2-u4-C53","difficulty":2,"kind":"mc","stem":"질문 사다리 놀이를 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"질문에 답하며 내가 어떻게 읽었는지 되돌아보려고","correct":true},{"t":"질문을 많이 받아 이기려고","mis":"K4-2-u4-X51"},{"t":"누가 빨리 답하는지 겨루려고","mis":"K4-2-u4-X52"},{"t":"질문 카드를 많이 모으려고","mis":"K4-2-u4-X06"}],"explanation":["이기는 놀이가 아니에요.","빠르기도 아니에요.","내 읽기를 되돌아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#17','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C33',3,'mc','auto','「읽기 전·중·후 활동」을 쓰는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X07','K4-2-u4-X06','K4-2-u4-X04']::text[],false,'{"seq":17,"concept":"K4-2-u4-C33","difficulty":3,"kind":"mc","stem":"「읽기 전·중·후 활동」을 쓰는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"그때그때 글과 목적에 맞는 것을 스스로 골라 쓴다","correct":true},{"t":"글을 읽을 때마다 빠짐없이 모두 한다","mis":"K4-2-u4-X07"},{"t":"질문을 되도록 많이 만들어 칸을 채운다","mis":"K4-2-u4-X06"},{"t":"선생님이 시킬 때만 한다","mis":"K4-2-u4-X04"}],"explanation":["빠짐없이가 아니에요.","많이도 아니에요.","스스로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#18','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C45',3,'mc','auto','병훈이의 의견을 받치기에 알맞은 이유를 하나 더 고른다면 무엇인가요?',ARRAY['K4-2-u4-X46','K4-2-u4-X47']::text[],false,'{"seq":18,"concept":"K4-2-u4-C45","difficulty":3,"kind":"mc","stem":"병훈이의 의견을 받치기에 알맞은 이유를 하나 더 고른다면 무엇인가요?","options":[{"t":"이름이 있으면 비슷한 물건끼리 바뀌어도 금방 알아볼 수 있다","correct":true},{"t":"이름표 스티커가 예쁘다","mis":"K4-2-u4-X46"},{"t":"나는 이름 쓰는 것을 좋아한다","mis":"K4-2-u4-X47"},{"t":"이름을 쓰면 글씨 연습이 된다","mis":"K4-2-u4-X46"}],"explanation":["이름을 써 두면 좋은 점이에요.","내 취향은 아니에요.","바뀌지 않게 해 줘요."],"asset":{"type":"passage","lines":["1 4학년 친구들, 안녕하세요? 저는 병훈입니다.","2 교실 뒤 상자에는 주인을 찾지 못한 물건이 쌓여 있습니다.","   지난주에도 줄넘기와 물병이 그대로 남았습니다.","3 저는 우리가 쓰는 물건에 이름을 써 두면 좋겠다고 생각합니다.","4 첫째, 이름이 적혀 있으면 물건을 주운 친구가 바로 돌려줄 수 있습니다.","5 둘째, 이름을 쓰는 동안 이것이 내 물건이라는 것을 한 번 더 생각하게 됩니다.","6 작은 일이지만 물건을 찾느라 쓰는 시간을 모두가 아낄 수 있습니다.","7 오늘 집에 가서 필통과 물병부터 살펴보면 어떨까요?"],"title":"병훈이의 글 「함께 쓰는 물건에 이름을 써 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#19','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C46',3,'mc','auto','「깔끔하게 쓰여 있으니 옳겠지.」라고 생각한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X48','K4-2-u4-X49']::text[],false,'{"seq":19,"concept":"K4-2-u4-C46","difficulty":3,"kind":"mc","stem":"「깔끔하게 쓰여 있으니 옳겠지.」라고 생각한 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"「깔끔한 것과 옳은 것은 달라. 이유가 의견과 이어지는지 따져 보자.」","correct":true},{"t":"「맞아, 글에 실렸으면 옳은 말이야.」","mis":"K4-2-u4-X48"},{"t":"「의견 글은 일단 다 틀렸다고 보면 돼.」","mis":"K4-2-u4-X49"},{"t":"「글쓴이 이름만 보면 옳은지 알 수 있어.」","mis":"K4-2-u4-X48"}],"explanation":["무조건 믿지 않아요.","무조건 의심도 아니에요.","이유를 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#20','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C49',3,'mc','auto','점검표에 「아니요」가 나왔을 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X40','K4-2-u4-X41']::text[],false,'{"seq":20,"concept":"K4-2-u4-C49","difficulty":3,"kind":"mc","stem":"점검표에 「아니요」가 나왔을 때 알맞은 생각은 무엇인가요?","options":[{"t":"「아니요」가 나온 자리가 바로 다시 읽을 자리다","correct":true},{"t":"「아니요」는 창피하니 「예」로 고친다","mis":"K4-2-u4-X40"},{"t":"「아니요」가 나오면 점검표를 빨리 덮는다","mis":"K4-2-u4-X41"},{"t":"「아니요」가 나오면 그 글은 다시 읽지 않는다","mis":"K4-2-u4-X40"}],"explanation":["고치지 않아요.","덮지도 않아요.","다시 읽을 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#21','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C25',3,'mc','auto','「말하지 못한 말」을 읽고 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X29']::text[],false,'{"seq":21,"concept":"K4-2-u4-C25","difficulty":3,"kind":"mc","stem":"「말하지 못한 말」을 읽고 알맞게 말한 것은 무엇인가요?","options":[{"t":"형준이는 하고 싶은 말을 삼켰고, 수지는 상대 마음을 살피지 않았으니 둘 다 돌아볼 점이 있다","correct":true},{"t":"수지만 나쁜 아이다","mis":"K4-2-u4-X29"},{"t":"형준이만 잘못했다","mis":"K4-2-u4-X29"},{"t":"우석이가 모두 잘못했다","mis":"K4-2-u4-X29"}],"explanation":["한 사람만의 일이 아니에요.","둘 다 한 가지씩이에요.","돌아볼 점이 있어요."],"asset":{"type":"passage","lines":["다음 연습 날, 배경 그림을 맡은 친구가 종이를 펼쳤다.","수지가 들여다보더니 말했다. 「이건 좀 이상해. 나무가 집보다 크잖아.」","그 친구는 종이를 접어 넣고 그날 내내 아무 말도 하지 않았다.","연습이 자꾸 끊겼다. 아무도 먼저 의견을 내지 않았기 때문이다.","형준이가 조용히 말했다. 「사실 나…… 해설 하고 싶었어.」","수지가 「그럼 그때 말하지.」 하려다 입을 다물었다. 자기가 한 말이 떠올랐다.","우석이가 말했다. 「우리 둘 다 한 가지씩 빠뜨린 것 같아.」","셋은 한참 동안 말없이 앉아 있었다."],"title":"이야기 「말하지 못한 말」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#22','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C51',3,'mc','auto','친구는 「받아쓰기」를 노래로, 나는 그림으로 나타냈어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X50','K4-2-u4-X11']::text[],false,'{"seq":22,"concept":"K4-2-u4-C51","difficulty":3,"kind":"mc","stem":"친구는 「받아쓰기」를 노래로, 나는 그림으로 나타냈어요. 알맞은 생각은 무엇인가요?","options":[{"t":"방법에는 등수가 없으니 왜 그 방법을 골랐는지 서로 묻는다","correct":true},{"t":"그림이 더 어려우니 내가 더 잘했다","mis":"K4-2-u4-X50"},{"t":"노래가 더 재미있으니 친구가 이겼다","mis":"K4-2-u4-X50"},{"t":"다음에는 친구 방법으로 바꿔야 한다","mis":"K4-2-u4-X11"}],"explanation":["등수가 없어요.","바꿀 것도 없어요.","까닭을 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#23','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C11',4,'essay','teacher','하은이가 「빈 그네」를 읽고 쓸쓸했다는 도윤이에게 할 말을 쓰고, 그렇게 말하면 좋은 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u4-C11","difficulty":4,"kind":"essay","stem":"하은이가 「빈 그네」를 읽고 쓸쓸했다는 도윤이에게 할 말을 쓰고, 그렇게 말하면 좋은 까닭을 쓰세요.","answer_guide":{"answer":"예: 「나는 궁금했는데, 너는 어느 줄에서 쓸쓸했는지 말해 줄래?」라고 묻는다. 느낌은 틀린 것이 아니라 다를 수 있는 것이라서, 도윤이의 까닭을 들으면 내가 못 본 면을 볼 수 있기 때문이다.","scoring_points":["도윤이의 느낌을 틀렸다고 하지 않았는가","도윤이에게 느낌의 까닭(어느 줄)을 묻는 말을 썼는가","다른 느낌을 들으면 좋은 점을 까닭으로 썼는가"]},"explanation":["틀렸다고 하지 않아요.","어느 줄인지 물어요.","넓게 볼 수 있어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"나는 쓸쓸했어. 다들 가 버린 저녁 운동장이 눈에 보이는 것 같았거든."},{"who":"하은","text":"나는 궁금했어. 「누가 방금 내렸을까」 하는 줄에서 이야기가 시작될 것 같았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#24','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C45',4,'essay','teacher','은재의 글에서 의견과 이유 두 가지를 찾아 쓰고, 「이면지 상자를 예쁘게 꾸밀 수 있다」가 왜 알맞은 이유가 아닌지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u4-C45","difficulty":4,"kind":"essay","stem":"은재의 글에서 의견과 이유 두 가지를 찾아 쓰고, 「이면지 상자를 예쁘게 꾸밀 수 있다」가 왜 알맞은 이유가 아닌지 쓰세요.","answer_guide":{"answer":"예: 의견은 「한 면만 쓴 종이를 교실 뒤 이면지 상자에 모으자」이다. 이유는 「연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 된다」와 「버리는 종이가 줄어 쓰레기통이 금방 차지 않는다」이다. 상자를 꾸미는 것은 종이를 모으자는 의견대로 했을 때 좋아지는 점이 아니라서 의견과 이어지지 않는다.","scoring_points":["의견을 바르게 찾았는가","이유 두 가지를 바르게 찾았는가","상자 꾸미기가 의견과 이어지지 않는다고 썼는가"]},"explanation":["「생각합니다」를 찾아요.","「첫째, 둘째」를 찾아요.","의견과 이어지나요?"],"asset":{"type":"passage","lines":["1 안녕하세요? 저는 4학년 은재입니다.","2 우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.","3 저는 한 면만 쓴 종이를 교실 뒤 이면지 상자에 모으면 좋겠다고 생각합니다.","4 첫째, 연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 됩니다.","5 둘째, 버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다.","6 내일부터 종이를 버리기 전에 뒷면을 한 번 살펴보면 어떨까요?"],"title":"은재의 글 「다 쓴 종이는 이면지 상자에 모아요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_a#25','kor',4,2,'u4','','g4_2_kor_u4_review_a','unit_review','K4-2-u4-C38',4,'essay','teacher','「개미가 줄지어 가는 까닭」을 두세 문장으로 간추려 쓰고, 어떤 방법으로 간추렸는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u4-C38","difficulty":4,"kind":"essay","stem":"「개미가 줄지어 가는 까닭」을 두세 문장으로 간추려 쓰고, 어떤 방법으로 간추렸는지 쓰세요.","answer_guide":{"answer":"예: 먹이를 찾은 개미는 집으로 돌아가며 땅에 냄새를 남긴다. 다른 개미들이 그 냄새를 따라가서 개미들이 줄지어 가게 된다. 나는 각 부분의 중심 문장(2번·3번)을 모으고, 처음의 경험 이야기와 덧붙인 내용은 빼서 짧게 정리했다.","scoring_points":["글의 중심 내용을 두세 문장으로 썼는가","모두 옮겨 적거나 재미있는 부분만 쓰지 않았는가","중심 문장을 모아 간추린 방법을 썼는가"]},"explanation":["중심 문장을 찾아요.","모아서 짧게요.","방법도 써요."],"asset":{"type":"passage","lines":["1 개미가 한 줄로 길게 지나가는 모습을 본 적이 있을 것입니다.","2 먹이를 찾은 개미는 집으로 돌아가면서 땅에 냄새를 남깁니다.","3 다른 개미들은 더듬이로 이 냄새를 맡고 같은 길을 따라갑니다.","4 그래서 개미들은 말을 하지 않아도 먹이가 있는 곳을 찾아갑니다.","5 먹이가 다 떨어지면 냄새가 점점 옅어지고, 줄도 흩어집니다."],"title":"설명하는 글 「개미가 줄지어 가는 까닭」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#1','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C41',1,'mc','auto','어떤 문제에 대한 글쓴이의 생각을 밝혀 쓴 글은 무엇인가요?',ARRAY['K4-2-u4-X05','K4-2-u4-X34','K4-2-u4-X42']::text[],false,'{"seq":1,"concept":"K4-2-u4-C41","difficulty":1,"kind":"mc","stem":"어떤 문제에 대한 글쓴이의 생각을 밝혀 쓴 글은 무엇인가요?","options":[{"t":"의견을 제시하는 글","correct":true},{"t":"설명하는 글","mis":"K4-2-u4-X05"},{"t":"조립 설명서","mis":"K4-2-u4-X34"},{"t":"받아쓰기 시험지","mis":"K4-2-u4-X42"}],"explanation":["글쓴이의 생각이 있어요.","「~라고 생각합니다」","의견을 제시하는 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#2','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C31',1,'mc','auto','민들레 씨앗 하나하나에 붙어 있는 것은 무엇인가요?',ARRAY['K4-2-u4-X33']::text[],false,'{"seq":2,"concept":"K4-2-u4-C31","difficulty":1,"kind":"mc","stem":"민들레 씨앗 하나하나에 붙어 있는 것은 무엇인가요?","options":[{"t":"가는 털","correct":true},{"t":"작은 날개","mis":"K4-2-u4-X33"},{"t":"노란 꽃잎","mis":"K4-2-u4-X33"},{"t":"끈적한 진","mis":"K4-2-u4-X33"}],"explanation":["3번 문장을 봐요.","부챗살처럼 붙어 있어요.","가는 털이에요."],"asset":{"type":"passage","lines":["1 봄에 핀 노란 민들레꽃이 지고 나면 그 자리에 하얗고 동그란 공이 생깁니다.","2 이 공은 꽃이 시든 것이 아니라 씨앗이 잔뜩 모여 있는 것입니다.","3 씨앗 하나하나에는 가는 털이 부챗살처럼 붙어 있습니다.","4 이 털이 낙하산처럼 공기를 받아 씨앗을 공중에 띄웁니다.","5 그래서 민들레는 스스로 걸어 다니지 못해도 멀리까지 퍼질 수 있습니다.","6 바람이 잘 부는 길가에 민들레가 줄지어 피어 있는 까닭이 여기에 있습니다."],"title":"설명하는 글 「민들레 씨앗의 여행」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#3','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C28',1,'mc','auto','읽기 「중」에 하는 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":3,"concept":"K4-2-u4-C28","difficulty":1,"kind":"mc","stem":"읽기 「중」에 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"새로 알게 된 것이 무엇인지 살핀다","correct":true},{"t":"제목을 보고 무슨 내용일지 짐작한다","mis":"K4-2-u4-X30"},{"t":"글 전체를 짧게 간추린다","mis":"K4-2-u4-X30"},{"t":"더 알고 싶어진 것을 적는다","mis":"K4-2-u4-X30"}],"explanation":["읽는 동안이에요.","짐작은 전, 간추리기는 후예요.","새로 안 것을 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#4','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C36',1,'mc','auto','「속으로 배어 들어가다」는 뜻의 낱말은 무엇인가요?',ARRAY['K4-2-u4-X36','K4-2-u4-X19']::text[],false,'{"seq":4,"concept":"K4-2-u4-C36","difficulty":1,"kind":"mc","stem":"「속으로 배어 들어가다」는 뜻의 낱말은 무엇인가요?","options":[{"t":"스며들다","correct":true},{"t":"뒤섞이다","mis":"K4-2-u4-X36"},{"t":"우물쭈물하다","mis":"K4-2-u4-X19"},{"t":"멋쩍다","mis":"K4-2-u4-X19"}],"explanation":["굴을 따라 물이 들어가요.","속으로 배어요.","‘스며들다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#5','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C55',1,'ox','auto','「손님, 찾으시는 책은 저쪽에 있으세요.」는 바른 높임 표현이에요.',ARRAY['K4-2-u4-X53']::text[],false,'{"seq":5,"concept":"K4-2-u4-C55","difficulty":1,"kind":"ox","stem":"「손님, 찾으시는 책은 저쪽에 있으세요.」는 바른 높임 표현이에요.","answer":"X","reason_options":[{"t":"책은 사물이라 높이지 않고 「있어요」로 말해야 하기 때문에","correct":true},{"t":"손님이 찾는 책이니 책도 높여야 하기 때문에","mis":"K4-2-u4-X53"}],"mis":"K4-2-u4-X53","explanation":["높일 사람은 손님이에요.","책은 사물이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#6','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C57',1,'mc','auto','「메모」를 바꿔 쓸 우리말은 무엇인가요?',ARRAY['K4-2-u4-X55']::text[],false,'{"seq":6,"concept":"K4-2-u4-C57","difficulty":1,"kind":"mc","stem":"「메모」를 바꿔 쓸 우리말은 무엇인가요?","options":[{"t":"쪽지","correct":true},{"t":"일정","mis":"K4-2-u4-X55"},{"t":"표시","mis":"K4-2-u4-X55"},{"t":"편지지","mis":"K4-2-u4-X55"}],"explanation":["잊지 않게 적어 둔 것이에요.","일정은 스케줄이에요.","‘쪽지’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#7','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C58',1,'mc','auto','「앎」의 받침을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X56']::text[],false,'{"seq":7,"concept":"K4-2-u4-C58","difficulty":1,"kind":"mc","stem":"「앎」의 받침을 바르게 말한 것은 무엇인가요?","options":[{"t":"ㄹ과 ㅁ이 나란히 있는 겹받침 ㄻ","correct":true},{"t":"ㄹ과 ㄱ이 나란히 있는 겹받침 ㄺ","mis":"K4-2-u4-X56"},{"t":"ㄹ과 ㅂ이 나란히 있는 겹받침 ㄼ","mis":"K4-2-u4-X56"},{"t":"받침 ㅁ 하나","mis":"K4-2-u4-X56"}],"explanation":["받침 칸을 봐요.","두 자음이 있어요.","ㄹ과 ㅁ이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#8','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C9',1,'mc','auto','도윤이와 하은이가 「빈 그네」를 읽고 서로 다른 느낌을 말했어요. 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u4-X10','K4-2-u4-X08','K4-2-u4-X16']::text[],false,'{"seq":8,"concept":"K4-2-u4-C9","difficulty":1,"kind":"mc","stem":"도윤이와 하은이가 「빈 그네」를 읽고 서로 다른 느낌을 말했어요. 알맞은 생각은 무엇인가요?","options":[{"t":"겪은 일과 눈길이 간 줄이 달라 느낌이 다를 수 있으니 둘 다 틀린 것이 아니다","correct":true},{"t":"도윤이가 먼저 말했으니 도윤이 느낌이 맞다","mis":"K4-2-u4-X10"},{"t":"하은이는 시를 잘못 읽었다","mis":"K4-2-u4-X08"},{"t":"둘 중 한 사람 느낌으로 맞춰야 한다","mis":"K4-2-u4-X16"}],"explanation":["둘 다 까닭이 있어요.","틀린 사람은 없어요.","다를 수 있어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"나는 쓸쓸했어. 다들 가 버린 저녁 운동장이 눈에 보이는 것 같았거든."},{"who":"하은","text":"나는 궁금했어. 「누가 방금 내렸을까」 하는 줄에서 이야기가 시작될 것 같았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#9','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C10',2,'ox','auto','반에서 가장 많이 나온 느낌을 그 시의 느낌으로 정해요.',ARRAY['K4-2-u4-X10']::text[],false,'{"seq":9,"concept":"K4-2-u4-C10","difficulty":2,"kind":"ox","stem":"반에서 가장 많이 나온 느낌을 그 시의 느낌으로 정해요.","answer":"X","reason_options":[{"t":"느낌은 사람마다 다를 수 있어 수로 정하는 것이 아니기 때문에","correct":true},{"t":"여럿이 고른 느낌이 정답이기 때문에","mis":"K4-2-u4-X10"}],"mis":"K4-2-u4-X10","explanation":["느낌은 투표가 아니에요.","사람마다 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#10','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C12',2,'mc','auto','길게 늘였을 때 뒤에 다른 낱말이 숨어 있지 「않은」 것은 무엇인가요?',ARRAY['K4-2-u4-X15']::text[],false,'{"seq":10,"concept":"K4-2-u4-C12","difficulty":2,"kind":"mc","stem":"길게 늘였을 때 뒤에 다른 낱말이 숨어 있지 「않은」 것은 무엇인가요?","options":[{"t":"사탕","correct":true},{"t":"모이","mis":"K4-2-u4-X15"},{"t":"나무","mis":"K4-2-u4-X15"},{"t":"고래","mis":"K4-2-u4-X15"}],"explanation":["하나씩 늘여 봐요.","「아탕」은 낱말이 아니에요.","‘사탕’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#11','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C18',2,'mc','auto','인물의 성격을 짐작하는 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u4-X20']::text[],false,'{"seq":11,"concept":"K4-2-u4-C18","difficulty":2,"kind":"mc","stem":"인물의 성격을 짐작하는 알맞은 방법은 무엇인가요?","options":[{"t":"인물이 한 말과 행동을 살펴본다","correct":true},{"t":"인물의 이름을 보고 정한다","mis":"K4-2-u4-X20"},{"t":"그림 속 옷 색깔을 보고 정한다","mis":"K4-2-u4-X20"},{"t":"한 장면만 보고 나쁜 사람이라고 정한다","mis":"K4-2-u4-X20"}],"explanation":["이름은 단서가 아니에요.","한 장면만도 아니에요.","말과 행동을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#12','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C22',2,'ox','auto','역할놀이에서 목소리가 가장 큰 친구가 가장 잘한 거예요.',ARRAY['K4-2-u4-X25']::text[],false,'{"seq":12,"concept":"K4-2-u4-C22","difficulty":2,"kind":"ox","stem":"역할놀이에서 목소리가 가장 큰 친구가 가장 잘한 거예요.","answer":"X","reason_options":[{"t":"인물에 대한 생각이나 느낌이 드러났는지가 중요하기 때문에","correct":true},{"t":"크게 말해야 잘 들리니 무조건 잘한 것이기 때문에","mis":"K4-2-u4-X25"}],"mis":"K4-2-u4-X25","explanation":["목소리 크기 대회가 아니에요.","인물의 마음을 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#13','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C30',2,'mc','auto','「개미가 줄지어 가는 까닭」을 읽는 동안 할 수 있는 질문은 무엇인가요?',ARRAY['K4-2-u4-X30','K4-2-u4-X32']::text[],false,'{"seq":13,"concept":"K4-2-u4-C30","difficulty":2,"kind":"mc","stem":"「개미가 줄지어 가는 까닭」을 읽는 동안 할 수 있는 질문은 무엇인가요?","options":[{"t":"내가 짐작한 까닭과 글에 나온 까닭이 같은가?","correct":true},{"t":"제목을 보니 무엇에 대한 글일까?","mis":"K4-2-u4-X30"},{"t":"다 읽고 더 알고 싶어진 것은 무엇인가?","mis":"K4-2-u4-X30"},{"t":"개미 그림은 무슨 색인가?","mis":"K4-2-u4-X32"}],"explanation":["읽는 도중이에요.","짐작과 견주어요.","같은지 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#14','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C43',2,'mc','auto','은재의 의견은 무엇인가요?',ARRAY['K4-2-u4-X44']::text[],false,'{"seq":14,"concept":"K4-2-u4-C43","difficulty":2,"kind":"mc","stem":"은재의 의견은 무엇인가요?","options":[{"t":"한 면만 쓴 종이를 이면지 상자에 모으자","correct":true},{"t":"쓰레기통을 더 큰 것으로 바꾸자","mis":"K4-2-u4-X44"},{"t":"종이를 아예 쓰지 말자","mis":"K4-2-u4-X44"},{"t":"새 종이를 더 많이 사자","mis":"K4-2-u4-X44"}],"explanation":["「~라고 생각합니다」를 찾아요.","3번 문장이에요.","이면지 상자에 모으자예요."],"asset":{"type":"passage","lines":["1 안녕하세요? 저는 4학년 은재입니다.","2 우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.","3 저는 한 면만 쓴 종이를 교실 뒤 이면지 상자에 모으면 좋겠다고 생각합니다.","4 첫째, 연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 됩니다.","5 둘째, 버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다.","6 내일부터 종이를 버리기 전에 뒷면을 한 번 살펴보면 어떨까요?"],"title":"은재의 글 「다 쓴 종이는 이면지 상자에 모아요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#15','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C37',2,'mc','auto','「지렁이가 하는 일」 뒷부분(7~12)에서 가장 중요한 문장은 무엇인가요?',ARRAY['K4-2-u4-X37']::text[],false,'{"seq":15,"concept":"K4-2-u4-C37","difficulty":2,"kind":"mc","stem":"「지렁이가 하는 일」 뒷부분(7~12)에서 가장 중요한 문장은 무엇인가요?","options":[{"t":"그래서 지렁이가 많이 사는 땅은 식물이 자라기에 좋은 땅이 됩니다.","correct":true},{"t":"식물의 뿌리도 숨을 쉽니다.","mis":"K4-2-u4-X37"},{"t":"지렁이는 먹은 흙을 몸 밖으로 내놓습니다.","mis":"K4-2-u4-X37"},{"t":"이때 나온 똥은 잘게 부서지고 양분과 뒤섞여 있습니다.","mis":"K4-2-u4-X37"}],"explanation":["없으면 뜻이 안 통하는 문장이에요.","다른 문장이 풀어 줘요.","11번이에요."],"asset":{"type":"passage","lines":["7 식물의 뿌리도 숨을 쉽니다.","8 그래서 공기가 잘 드나드는 흙에서 뿌리가 더 잘 자랍니다.","9 지렁이는 먹은 흙을 몸 밖으로 내놓습니다.","10 이때 나온 똥은 잘게 부서지고 양분과 뒤섞여 있습니다.","11 그래서 지렁이가 많이 사는 땅은 식물이 자라기에 좋은 땅이 됩니다.","12 땅속에서 조용히 지나다니는 작은 동물이 흙을 돌보고 있었던 것입니다."],"title":"설명하는 글 「지렁이가 하는 일」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#16','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C53',2,'ox','auto','사다리 놀이에서는 빨리 답할수록 잘한 거예요.',ARRAY['K4-2-u4-X52']::text[],false,'{"seq":16,"concept":"K4-2-u4-C53","difficulty":2,"kind":"ox","stem":"사다리 놀이에서는 빨리 답할수록 잘한 거예요.","answer":"X","reason_options":[{"t":"내가 그렇게 읽었다고 말할 수 있으면 되기 때문에","correct":true},{"t":"이 놀이는 빠르기를 겨루는 놀이이기 때문에","mis":"K4-2-u4-X52"}],"mis":"K4-2-u4-X52","explanation":["빠르기가 아니에요.","읽은 것을 말해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#17','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C6',3,'error','auto','읽기를 되돌아보는 것을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X06','K4-2-u4-X07']::text[],false,'{"seq":17,"concept":"K4-2-u4-C6","difficulty":3,"kind":"error","stem":"읽기를 되돌아보는 것을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「질문을 많이 만들수록 잘 읽은 거야.」","correct":true,"mis_target":"K4-2-u4-X06"},{"t":"친구 가 — 「그 글에 필요한 질문을 골라 쓰면 돼.」","mis":"K4-2-u4-X07"},{"t":"친구 다 — 「짧은 안내문이면 질문 하나로도 충분할 수 있어.」","mis":"K4-2-u4-X07"}],"explanation":["개수를 세는 친구를 찾아요.","질문은 골라 써요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#18','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C45',3,'ox','auto','이유가 알맞은지 따질 때, 내가 그 의견에 반대하면 이유도 모두 알맞지 않은 거예요.',ARRAY['K4-2-u4-X47']::text[],false,'{"seq":18,"concept":"K4-2-u4-C45","difficulty":3,"kind":"ox","stem":"이유가 알맞은지 따질 때, 내가 그 의견에 반대하면 이유도 모두 알맞지 않은 거예요.","answer":"X","reason_options":[{"t":"찬성하든 반대하든 이유가 의견과 이어지는지로 따져야 하기 때문에","correct":true},{"t":"내 생각과 다르면 이유도 틀린 것이기 때문에","mis":"K4-2-u4-X47"}],"mis":"K4-2-u4-X47","explanation":["찬반과 따지기는 달라요.","의견과 이어지나요?","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#19','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C47',3,'mc','auto','글쓴이의 의견이 내 생각과 다를 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X48','K4-2-u4-X49']::text[],false,'{"seq":19,"concept":"K4-2-u4-C47","difficulty":3,"kind":"mc","stem":"글쓴이의 의견이 내 생각과 다를 때 알맞은 것은 무엇인가요?","options":[{"t":"어디가 다른지 찾고, 내 생각을 받칠 이유를 마련한다","correct":true},{"t":"글쓴이 의견으로 내 생각을 바로 바꾼다","mis":"K4-2-u4-X48"},{"t":"글쓴이를 틀렸다고 깎아내린다","mis":"K4-2-u4-X49"},{"t":"읽기를 그만두고 덮는다","mis":"K4-2-u4-X49"}],"explanation":["바로 바꾸지 않아요.","깎아내리지도 않아요.","내 이유를 마련해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#20','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C49',3,'ox','auto','읽기 과정 점검표는 모두 「예」가 되게 답해야 좋은 거예요.',ARRAY['K4-2-u4-X40']::text[],false,'{"seq":20,"concept":"K4-2-u4-C49","difficulty":3,"kind":"ox","stem":"읽기 과정 점검표는 모두 「예」가 되게 답해야 좋은 거예요.","answer":"X","reason_options":[{"t":"점검표는 잘 보이려는 것이 아니라 나를 위해 다시 읽을 곳을 찾는 것이기 때문에","correct":true},{"t":"「예」가 많을수록 잘 읽은 것이기 때문에","mis":"K4-2-u4-X40"}],"mis":"K4-2-u4-X40","explanation":["점검표는 나를 위한 거예요.","「예」 세기가 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#21','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C24',3,'mc','auto','쪽지를 받는 사람이 상처받지 않게 쓰는 방법은 무엇인가요?',ARRAY['K4-2-u4-X27']::text[],false,'{"seq":21,"concept":"K4-2-u4-C24","difficulty":3,"kind":"mc","stem":"쪽지를 받는 사람이 상처받지 않게 쓰는 방법은 무엇인가요?","options":[{"t":"「너는 ~하잖아」 대신 「나는 ~라고 생각했어」로 쓴다","correct":true},{"t":"잘못한 점을 크게 적어 모두 보게 붙인다","mis":"K4-2-u4-X27"},{"t":"「너 때문에」로 시작해 탓한다","mis":"K4-2-u4-X27"},{"t":"이름을 크게 적고 고칠 점만 늘어놓는다","mis":"K4-2-u4-X27"}],"explanation":["받는 사람을 생각해요.","탓하지 않아요.","「나는 ~」으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#22','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C50',3,'ox','auto','느낌을 나타내는 방법은 즉흥극·그림·편지·노래 네 가지뿐이에요.',ARRAY['K4-2-u4-X50']::text[],false,'{"seq":22,"concept":"K4-2-u4-C50","difficulty":3,"kind":"ox","stem":"느낌을 나타내는 방법은 즉흥극·그림·편지·노래 네 가지뿐이에요.","answer":"X","reason_options":[{"t":"내가 생각한 다른 방법으로도 나타낼 수 있기 때문에","correct":true},{"t":"배운 방법 말고는 쓰면 안 되기 때문에","mis":"K4-2-u4-X50"}],"mis":"K4-2-u4-X50","explanation":["목록은 닫혀 있지 않아요.","다른 방법도 돼요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#23','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C13',4,'mc','auto','도윤이와 하은이가 느낌을 나눈 뒤의 모습으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X16','K4-2-u4-X12','K4-2-u4-X13']::text[],false,'{"seq":23,"concept":"K4-2-u4-C13","difficulty":4,"kind":"mc","stem":"도윤이와 하은이가 느낌을 나눈 뒤의 모습으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"도윤이는 쓸쓸함을, 하은이는 궁금함을 그대로 지니면서 서로가 눈여겨본 줄을 새로 알게 되었다","correct":true},{"t":"둘이 한 가지 느낌으로 맞추어 정했다","mis":"K4-2-u4-X16"},{"t":"하은이가 자기 느낌이 틀렸다고 인정했다","mis":"K4-2-u4-X12"},{"t":"도윤이가 하은이 느낌으로 바꾸었다","mis":"K4-2-u4-X13"}],"explanation":["맞추지 않아요.","바꾸지도 않아요.","서로의 줄을 알게 돼요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"나는 쓸쓸했어. 다들 가 버린 저녁 운동장이 눈에 보이는 것 같았거든."},{"who":"하은","text":"나는 궁금했어. 「누가 방금 내렸을까」 하는 줄에서 이야기가 시작될 것 같았어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#24','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C47',4,'essay','teacher','은재의 의견과 내 의견을 견주어 같은 점과 다른 점(또는 더하고 싶은 점)을 쓰고, 내 생각을 받치는 이유를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u4-C47","difficulty":4,"kind":"essay","stem":"은재의 의견과 내 의견을 견주어 같은 점과 다른 점(또는 더하고 싶은 점)을 쓰고, 내 생각을 받치는 이유를 쓰세요.","answer_guide":{"answer":"예: 종이를 한 번 더 쓰자는 생각은 은재와 같다. 다른 점은, 나는 상자 하나보다 모둠마다 작은 바구니를 두는 것이 낫다고 생각한다. 왜냐하면 자리에서 바로 꺼내 쓸 수 있어 더 자주 쓰게 되기 때문이다.","scoring_points":["같은 점을 썼는가","다른 점이나 더하고 싶은 점을 썼는가","내 생각을 받치는 이유를 썼는가"]},"explanation":["같은 곳을 찾아요.","다른 곳도 찾아요.","내 이유를 붙여요."],"asset":{"type":"passage","lines":["1 안녕하세요? 저는 4학년 은재입니다.","2 우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.","3 저는 한 면만 쓴 종이를 교실 뒤 이면지 상자에 모으면 좋겠다고 생각합니다.","4 첫째, 연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 됩니다.","5 둘째, 버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다.","6 내일부터 종이를 버리기 전에 뒷면을 한 번 살펴보면 어떨까요?"],"title":"은재의 글 「다 쓴 종이는 이면지 상자에 모아요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_b#25','kor',4,2,'u4','','g4_2_kor_u4_review_b','unit_review','K4-2-u4-C30',4,'essay','teacher','「개미가 줄지어 가는 까닭」을 읽기 전·중·후에 스스로 던질 질문을 하나씩 쓰고, 그 가운데 읽기 후 질문에 답해 보세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u4-C30","difficulty":4,"kind":"essay","stem":"「개미가 줄지어 가는 까닭」을 읽기 전·중·후에 스스로 던질 질문을 하나씩 쓰고, 그 가운데 읽기 후 질문에 답해 보세요.","answer_guide":{"answer":"예: 읽기 전 — 「개미가 왜 줄지어 갈까? 내가 아는 것은 무엇이지?」 · 읽기 중 — 「내가 짐작한 까닭과 글의 까닭이 같은가?」 · 읽기 후 — 「더 알고 싶어진 것은 무엇인가?」 → 비가 와서 냄새가 씻기면 개미가 어떻게 길을 찾는지 더 알고 싶다.","scoring_points":["읽기 전·중·후 질문을 하나씩 썼는가","각 질문이 그 단계에서 답할 수 있는 질문인가","읽기 후 질문에 답했는가"]},"explanation":["전 — 짐작·아는 것","중 — 짐작과 견주기","후 — 더 알고 싶은 것"],"asset":{"type":"passage","lines":["1 개미가 한 줄로 길게 지나가는 모습을 본 적이 있을 것입니다.","2 먹이를 찾은 개미는 집으로 돌아가면서 땅에 냄새를 남깁니다.","3 다른 개미들은 더듬이로 이 냄새를 맡고 같은 길을 따라갑니다.","4 그래서 개미들은 말을 하지 않아도 먹이가 있는 곳을 찾아갑니다.","5 먹이가 다 떨어지면 냄새가 점점 옅어지고, 줄도 흩어집니다."],"title":"설명하는 글 「개미가 줄지어 가는 까닭」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#1','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C41',1,'ox','auto','의견을 제시하는 글을 읽는 사람은 그 생각에 동의할지 말지 스스로 정할 수 있어요.',ARRAY['K4-2-u4-X42']::text[],false,'{"seq":1,"concept":"K4-2-u4-C41","difficulty":1,"kind":"ox","stem":"의견을 제시하는 글을 읽는 사람은 그 생각에 동의할지 말지 스스로 정할 수 있어요.","answer":"O","reason_options":[{"t":"글쓴이의 생각을 밝힌 글이라 이유를 따져 보고 내 생각을 정할 수 있기 때문에","correct":true},{"t":"글에 쓰인 의견은 반드시 따라야 하기 때문에","mis":"K4-2-u4-X42"}],"mis":"K4-2-u4-X42","explanation":["글쓴이의 생각이에요.","내 생각은 내가 정해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#2','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C35',1,'mc','auto','지렁이가 흙 속에서 양분을 얻는 것은 무엇인가요?',ARRAY['K4-2-u4-X35']::text[],false,'{"seq":2,"concept":"K4-2-u4-C35","difficulty":1,"kind":"mc","stem":"지렁이가 흙 속에서 양분을 얻는 것은 무엇인가요?","options":[{"t":"나뭇잎 조각이나 썩은 뿌리","correct":true},{"t":"작은 돌멩이","mis":"K4-2-u4-X35"},{"t":"빗물","mis":"K4-2-u4-X35"},{"t":"다른 지렁이","mis":"K4-2-u4-X35"}],"explanation":["4번 문장을 봐요.","흙 속에 섞인 것이에요.","나뭇잎 조각, 썩은 뿌리예요."],"asset":{"type":"passage","lines":["1 비가 온 뒤 길바닥에서 지렁이를 본 적이 있을 것입니다.","2 지렁이는 대부분의 시간을 땅속에서 지냅니다.","3 지렁이는 땅속을 지나가면서 흙을 먹습니다.","4 흙 속에 섞인 나뭇잎 조각이나 썩은 뿌리에서 양분을 얻기 때문입니다.","5 지렁이가 지나간 자리에는 가늘고 긴 굴이 남습니다.","6 이 굴을 따라 공기와 물이 땅속 깊은 곳까지 스며듭니다."],"title":"설명하는 글 「지렁이가 하는 일」 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#3','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C27',1,'ox','auto','「제목을 보고 무슨 내용일지 짐작하기」는 읽기 전에 하는 일이에요.',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":3,"concept":"K4-2-u4-C27","difficulty":1,"kind":"ox","stem":"「제목을 보고 무슨 내용일지 짐작하기」는 읽기 전에 하는 일이에요.","answer":"O","reason_options":[{"t":"아직 글을 읽지 않아도 제목만 보고 할 수 있기 때문에","correct":true},{"t":"글을 다 읽어야 짐작할 수 있기 때문에","mis":"K4-2-u4-X30"}],"mis":"K4-2-u4-X30","explanation":["제목은 먼저 보여요.","읽지 않아도 짐작해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#4','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C17',1,'mc','auto','「어색하고 쑥스럽다」는 뜻의 낱말은 무엇인가요?',ARRAY['K4-2-u4-X19','K4-2-u4-X36']::text[],false,'{"seq":4,"concept":"K4-2-u4-C17","difficulty":1,"kind":"mc","stem":"「어색하고 쑥스럽다」는 뜻의 낱말은 무엇인가요?","options":[{"t":"멋쩍다","correct":true},{"t":"머뭇거리다","mis":"K4-2-u4-X19"},{"t":"양분","mis":"K4-2-u4-X36"},{"t":"뒤섞이다","mis":"K4-2-u4-X36"}],"explanation":["형준이가 웃은 모습이에요.","어색하고 쑥스러워요.","‘멋쩍다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#5','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C55',1,'mc','auto','높임말 「-시-」를 붙이지 않아야 하는 것은 무엇인가요?',ARRAY['K4-2-u4-X53']::text[],false,'{"seq":5,"concept":"K4-2-u4-C55","difficulty":1,"kind":"mc","stem":"높임말 「-시-」를 붙이지 않아야 하는 것은 무엇인가요?","options":[{"t":"물건이나 값","correct":true},{"t":"선생님","mis":"K4-2-u4-X53"},{"t":"할머니","mis":"K4-2-u4-X53"},{"t":"손님","mis":"K4-2-u4-X53"}],"explanation":["「-시-」는 사람을 높여요.","물건은 높이지 않아요.","물건이나 값이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#6','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C56',1,'ox','auto','다른 나라 사람 앞에서는 나를 낮추려고 「저희 나라」라고 해야 해요.',ARRAY['K4-2-u4-X54']::text[],false,'{"seq":6,"concept":"K4-2-u4-C56","difficulty":1,"kind":"ox","stem":"다른 나라 사람 앞에서는 나를 낮추려고 「저희 나라」라고 해야 해요.","answer":"X","reason_options":[{"t":"나라는 남의 나라보다 낮출 수 없어 「우리나라」라고 하기 때문에","correct":true},{"t":"「저희」를 쓰면 언제나 더 예의 바른 말이 되기 때문에","mis":"K4-2-u4-X54"}],"mis":"K4-2-u4-X54","explanation":["나는 낮출 수 있어요.","나라는 낮추지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#7','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C58',1,'ox','auto','「넓다」의 받침은 ㄻ이에요.',ARRAY['K4-2-u4-X56']::text[],false,'{"seq":7,"concept":"K4-2-u4-C58","difficulty":1,"kind":"ox","stem":"「넓다」의 받침은 ㄻ이에요.","answer":"X","reason_options":[{"t":"「넓다」의 받침은 ㄹ과 ㅂ이 나란히 있는 ㄼ이기 때문에","correct":true},{"t":"받침이 두 자음이면 모두 ㄻ이기 때문에","mis":"K4-2-u4-X56"}],"mis":"K4-2-u4-X56","explanation":["ㄹ 옆에 무엇이 있나요?","ㅂ이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#8','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C11',1,'mc','auto','짝이 「빈 그네」를 읽고 나와 다른 느낌을 말했을 때 알맞은 대답은 무엇인가요?',ARRAY['K4-2-u4-X12','K4-2-u4-X13','K4-2-u4-X16']::text[],false,'{"seq":8,"concept":"K4-2-u4-C11","difficulty":1,"kind":"mc","stem":"짝이 「빈 그네」를 읽고 나와 다른 느낌을 말했을 때 알맞은 대답은 무엇인가요?","options":[{"t":"「그 느낌은 어느 줄에서 들었는지 말해 줄래?」","correct":true},{"t":"「그렇게 느끼면 안 돼.」","mis":"K4-2-u4-X12"},{"t":"「그럼 나도 너처럼 느낄게.」","mis":"K4-2-u4-X13"},{"t":"「느낌은 하나로 정해야 해.」","mis":"K4-2-u4-X16"}],"explanation":["막지 않아요.","바꾸지도 않아요.","까닭을 물어요."],"asset":{"type":"passage","lines":["아이들이 다 돌아간 저녁 운동장","그네 하나가 아직 흔들린다","누가 방금 내렸을까","바람이 대신 타고 있을까","나는 가방을 멘 채로 한참 서서","그네가 멈출 때까지 기다렸다"],"title":"시 「빈 그네」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#9','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C10',2,'mc','auto','「나는 이 시를 읽고 노란색이 떠올랐어.」 다음에 이어 말하면 좋은 것은 무엇인가요?',ARRAY['K4-2-u4-X16','K4-2-u4-X14','K4-2-u4-X13']::text[],false,'{"seq":9,"concept":"K4-2-u4-C10","difficulty":2,"kind":"mc","stem":"「나는 이 시를 읽고 노란색이 떠올랐어.」 다음에 이어 말하면 좋은 것은 무엇인가요?","options":[{"t":"「왜냐하면 오래 사는 고래가 따뜻하게 느껴졌기 때문이야.」","correct":true},{"t":"「너도 노란색으로 해.」","mis":"K4-2-u4-X16"},{"t":"「끝.」","mis":"K4-2-u4-X14"},{"t":"「다들 파란색이라고 하니 나도 바꿀게.」","mis":"K4-2-u4-X13"}],"explanation":["느낌 다음에는?","까닭이에요.","「왜냐하면」으로 이어요."],"asset":{"type":"passage","lines":["고래를 길게 불러 보면 / 고오오오오래","바다에서 오래 사는 고래 / 이름 속에 오래가 먼저 와 있었네","소리를 길게 불러 보면 / 소오오오오리","물 위에 동동 오리 한 마리 / 소리 속에서 헤엄쳐 나오네","길게 불러 보면 / 낱말 속에 숨어 있던 것들이 / 하나씩 고개를 드네"],"title":"시 「길게 불러 보면」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#10','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C12',2,'mc','auto','「모이」를 길게 늘이면 숨어 있는 낱말은 무엇인가요?',ARRAY['K4-2-u4-X15']::text[],false,'{"seq":10,"concept":"K4-2-u4-C12","difficulty":2,"kind":"mc","stem":"「모이」를 길게 늘이면 숨어 있는 낱말은 무엇인가요?","options":[{"t":"오이","correct":true},{"t":"모모","mis":"K4-2-u4-X15"},{"t":"이모","mis":"K4-2-u4-X15"},{"t":"오모","mis":"K4-2-u4-X15"}],"explanation":["「모오오오이」로 늘여요.","뒤에 남는 소리예요.","‘오이’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#11','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C18',2,'mc','auto','다빈이가 「같이 가자. 나는 어깨 좀 젖어도 괜찮아.」라고 한 말로 짐작할 수 있는 것은 무엇인가요?',ARRAY['K4-2-u4-X20','K4-2-u4-X17']::text[],false,'{"seq":11,"concept":"K4-2-u4-C18","difficulty":2,"kind":"mc","stem":"다빈이가 「같이 가자. 나는 어깨 좀 젖어도 괜찮아.」라고 한 말로 짐작할 수 있는 것은 무엇인가요?","options":[{"t":"자기가 조금 젖더라도 친구를 먼저 생각한다","correct":true},{"t":"지호를 귀찮게 여긴다","mis":"K4-2-u4-X20"},{"t":"비 맞는 것을 좋아한다","mis":"K4-2-u4-X17"},{"t":"우산을 빨리 돌려받고 싶다","mis":"K4-2-u4-X20"}],"explanation":["다빈이가 한 말을 봐요.","어깨가 젖어도 괜찮대요.","친구를 먼저 생각했어요."],"asset":{"type":"passage","lines":["비가 오는 하굣길, 지호는 우산이 없어 현관에 서 있었다.","같은 반 다빈이가 우산을 펴다가 지호를 보았다.","다빈이는 잠깐 머뭇거리더니 우산을 지호 쪽으로 기울였다.","「같이 가자. 나는 어깨 좀 젖어도 괜찮아.」","지호는 「고마워.」 하고 작게 말했다.","다음 날, 지호는 집에 있던 우산 하나를 더 들고 와 다빈이 책상 옆에 걸어 두었다."],"title":"이야기 「우산 하나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#12','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C22',2,'mc','auto','역할놀이를 하고 나서 하면 좋은 일은 무엇인가요?',ARRAY['K4-2-u4-X24','K4-2-u4-X25','K4-2-u4-X27']::text[],false,'{"seq":12,"concept":"K4-2-u4-C22","difficulty":2,"kind":"mc","stem":"역할놀이를 하고 나서 하면 좋은 일은 무엇인가요?","options":[{"t":"역할놀이를 하고 나서 새로 든 생각을 말한다","correct":true},{"t":"가장 웃긴 친구에게 상을 준다","mis":"K4-2-u4-X24"},{"t":"목소리 크기로 순위를 정한다","mis":"K4-2-u4-X25"},{"t":"다른 모둠의 실수를 찾아 크게 말한다","mis":"K4-2-u4-X27"}],"explanation":["순위를 매기지 않아요.","실수 찾기도 아니에요.","새로 든 생각을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#13','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C30',2,'ox','auto','「이 글을 읽고 더 알고 싶어진 것은 무엇인가?」는 읽기 전에 하는 질문이에요.',ARRAY['K4-2-u4-X31']::text[],false,'{"seq":13,"concept":"K4-2-u4-C30","difficulty":2,"kind":"ox","stem":"「이 글을 읽고 더 알고 싶어진 것은 무엇인가?」는 읽기 전에 하는 질문이에요.","answer":"X","reason_options":[{"t":"글을 다 읽어야 더 알고 싶은 것이 생기기 때문에","correct":true},{"t":"읽기 전에 궁금한 것을 다 정해 두어야 하기 때문에","mis":"K4-2-u4-X31"}],"mis":"K4-2-u4-X31","explanation":["「읽고」가 들어 있어요.","다 읽은 뒤예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#14','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C43',2,'mc','auto','글쓴이의 의견이 담긴 문장을 찾을 때 살펴보면 좋은 표현은 무엇인가요?',ARRAY['K4-2-u4-X44','K4-2-u4-X45']::text[],false,'{"seq":14,"concept":"K4-2-u4-C43","difficulty":2,"kind":"mc","stem":"글쓴이의 의견이 담긴 문장을 찾을 때 살펴보면 좋은 표현은 무엇인가요?","options":[{"t":"「저는 ~라고 생각합니다」","correct":true},{"t":"「안녕하세요?」","mis":"K4-2-u4-X44"},{"t":"「지난주에도 ~했습니다」","mis":"K4-2-u4-X44"},{"t":"「첫째, ~」","mis":"K4-2-u4-X45"}],"explanation":["인사가 아니에요.","이유도 아니에요.","생각을 밝힌 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#15','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C38',2,'ox','auto','가장 재미있었던 부분만 적는 것이 간추리기예요.',ARRAY['K4-2-u4-X39']::text[],false,'{"seq":15,"concept":"K4-2-u4-C38","difficulty":2,"kind":"ox","stem":"가장 재미있었던 부분만 적는 것이 간추리기예요.","answer":"X","reason_options":[{"t":"각 부분의 중심 문장을 모아 글 전체를 짧게 정리하는 것이 간추리기이기 때문에","correct":true},{"t":"재미있는 부분이 가장 중요한 부분이기 때문에","mis":"K4-2-u4-X39"}],"mis":"K4-2-u4-X39","explanation":["재미와 중요함은 달라요.","중심 문장을 모아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#16','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C52',2,'mc','auto','질문 카드에 적기 알맞지 「않은」 질문은 무엇인가요?',ARRAY['K4-2-u4-X32','K4-2-u4-X28']::text[],false,'{"seq":16,"concept":"K4-2-u4-C52","difficulty":2,"kind":"mc","stem":"질문 카드에 적기 알맞지 「않은」 질문은 무엇인가요?","options":[{"t":"이 글은 몇 줄인가요?","correct":true},{"t":"제목을 보고 무슨 내용이라고 짐작했나요?","mis":"K4-2-u4-X32"},{"t":"읽고 새로 알게 된 것은 무엇인가요?","mis":"K4-2-u4-X32"},{"t":"짐작한 내용과 글의 내용이 같았나요?","mis":"K4-2-u4-X28"}],"explanation":["답하면 내 읽기가 드러나나요?","줄 수는 세기만 하면 돼요.","몇 줄인지 묻는 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#17','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C33',3,'ox','auto','짧은 안내문을 읽을 때도 읽기 전·중·후 활동을 빠짐없이 다 해야 잘 읽은 거예요.',ARRAY['K4-2-u4-X07']::text[],false,'{"seq":17,"concept":"K4-2-u4-C33","difficulty":3,"kind":"ox","stem":"짧은 안내문을 읽을 때도 읽기 전·중·후 활동을 빠짐없이 다 해야 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"글의 특성과 읽는 목적에 따라 필요한 활동이 달라지기 때문에","correct":true},{"t":"하나라도 빠뜨리면 잘못 읽은 것이기 때문에","mis":"K4-2-u4-X07"}],"mis":"K4-2-u4-X07","explanation":["짧은 안내문이에요.","필요한 것만 골라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#18','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C45',3,'mc','auto','은재의 이유 「버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다」가 알맞은 이유인 까닭은 무엇인가요?',ARRAY['K4-2-u4-X46','K4-2-u4-X47']::text[],false,'{"seq":18,"concept":"K4-2-u4-C45","difficulty":3,"kind":"mc","stem":"은재의 이유 「버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다」가 알맞은 이유인 까닭은 무엇인가요?","options":[{"t":"한 면만 쓴 종이를 모으자는 의견과 이어지기 때문에","correct":true},{"t":"문장이 길기 때문에","mis":"K4-2-u4-X46"},{"t":"「둘째」로 시작하기 때문에","mis":"K4-2-u4-X46"},{"t":"내가 은재와 같은 생각이기 때문에","mis":"K4-2-u4-X47"}],"explanation":["길이가 아니에요.","찬성이어서도 아니에요.","의견과 이어져요."],"asset":{"type":"passage","lines":["1 안녕하세요? 저는 4학년 은재입니다.","2 우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.","3 저는 한 면만 쓴 종이를 교실 뒤 이면지 상자에 모으면 좋겠다고 생각합니다.","4 첫째, 연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 됩니다.","5 둘째, 버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다.","6 내일부터 종이를 버리기 전에 뒷면을 한 번 살펴보면 어떨까요?"],"title":"은재의 글 「다 쓴 종이는 이면지 상자에 모아요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#19','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C46',3,'ox','auto','글에 실린 의견은 무조건 옳다고 믿으면 돼요.',ARRAY['K4-2-u4-X48']::text[],false,'{"seq":19,"concept":"K4-2-u4-C46","difficulty":3,"kind":"ox","stem":"글에 실린 의견은 무조건 옳다고 믿으면 돼요.","answer":"X","reason_options":[{"t":"글쓴이의 생각이니 이유를 따져 보고 내 생각과 견주어야 하기 때문에","correct":true},{"t":"책이나 게시판에 실린 글은 틀릴 리가 없기 때문에","mis":"K4-2-u4-X48"}],"mis":"K4-2-u4-X48","explanation":["실렸다고 옳은 건 아니에요.","이유를 따져요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#20','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C39',3,'mc','auto','「다 읽고 짧게 간추려 보았다」에 표시하지 못했어요. 알맞은 다음 행동은 무엇인가요?',ARRAY['K4-2-u4-X40','K4-2-u4-X41','K4-2-u4-X04']::text[],false,'{"seq":20,"concept":"K4-2-u4-C39","difficulty":3,"kind":"mc","stem":"「다 읽고 짧게 간추려 보았다」에 표시하지 못했어요. 알맞은 다음 행동은 무엇인가요?","options":[{"t":"다음에 읽을 때 간추려 보는 것을 해 볼 일로 삼는다","correct":true},{"t":"표시를 해서 다 한 것처럼 만든다","mis":"K4-2-u4-X40"},{"t":"점검표를 빨리 넘긴다","mis":"K4-2-u4-X41"},{"t":"간추리기는 필요 없다고 생각한다","mis":"K4-2-u4-X04"}],"explanation":["솔직하게 표시했어요.","남은 줄이 있어요.","다음에 해 볼 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#21','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C25',3,'ox','auto','수지는 형준이를 일부러 괴롭히려고 그런 말을 한 거예요.',ARRAY['K4-2-u4-X21']::text[],false,'{"seq":21,"concept":"K4-2-u4-C25","difficulty":3,"kind":"ox","stem":"수지는 형준이를 일부러 괴롭히려고 그런 말을 한 거예요.","answer":"X","reason_options":[{"t":"수지는 본 대로 바로 말하는 인물로, 상대 마음을 살피지 못했을 뿐이기 때문에","correct":true},{"t":"형준이가 속상했으니 수지는 나쁜 마음이었던 것이 분명하기 때문에","mis":"K4-2-u4-X21"}],"mis":"K4-2-u4-X21","explanation":["수지는 곧바로 말했어요.","괴롭히려던 건 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#22','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C50',3,'mc','auto','「받아쓰기」에 대한 느낌을 「시 속 아이에게 편지 쓰기」로 나타낸 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X28','K4-2-u4-X50','K4-2-u4-X12']::text[],false,'{"seq":22,"concept":"K4-2-u4-C50","difficulty":3,"kind":"mc","stem":"「받아쓰기」에 대한 느낌을 「시 속 아이에게 편지 쓰기」로 나타낸 것으로 알맞은 것은 무엇인가요?","options":[{"t":"「집에서는 잘 썼으니 너는 글자를 아는 거야. 다음엔 천천히 써 봐.」","correct":true},{"t":"「받아쓰기 시험은 몇 점이었니?」","mis":"K4-2-u4-X28"},{"t":"「노래 가사로 바꿔 불러 줄게.」","mis":"K4-2-u4-X50"},{"t":"「네 글씨는 틀렸어.」","mis":"K4-2-u4-X12"}],"explanation":["시 속 아이에게 써요.","아이의 마음을 생각해요.","내 느낌을 담아요."],"asset":{"type":"passage","lines":["시험지를 받으면","아는 글자도 갑자기 낯설어진다","집에서는 술술 썼는데","연필 끝에서만 글자가 자꾸 미끄러진다","집에 돌아와 다시 써 보면","아무 일도 없었다는 듯","또박또박 잘 써진다"],"title":"시 「받아쓰기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#23','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C10',4,'essay','teacher','「빈 그네」를 읽고 떠오른 장면을 하나 쓰고, 그 장면이 떠오른 까닭을 시의 줄과 내 경험을 이어 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K4-2-u4-C10","difficulty":4,"kind":"essay","stem":"「빈 그네」를 읽고 떠오른 장면을 하나 쓰고, 그 장면이 떠오른 까닭을 시의 줄과 내 경험을 이어 쓰세요.","answer_guide":{"answer":"예: 해 질 녘 혼자 학교에 남아 있던 내 모습이 떠올랐다. 「나는 가방을 멘 채로 한참 서서」라는 줄을 읽으니, 지난번 친구들이 먼저 가 버린 뒤 운동장에 혼자 서 있던 일이 생각났기 때문이다.","scoring_points":["떠오른 장면을 썼는가","그 장면과 이어지는 시의 줄을 짚었는가","내 경험과 이어 까닭을 썼는가"]},"explanation":["장면을 떠올려요.","시의 줄을 짚어요.","내 경험과 이어요."],"asset":{"type":"passage","lines":["아이들이 다 돌아간 저녁 운동장","그네 하나가 아직 흔들린다","누가 방금 내렸을까","바람이 대신 타고 있을까","나는 가방을 멘 채로 한참 서서","그네가 멈출 때까지 기다렸다"],"title":"시 「빈 그네」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#24','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C45',4,'mc','auto','병훈이의 글에 「둘째, 이름을 쓰면 글씨 연습이 됩니다.」가 들어갔다면 어떻게 따지는 것이 알맞은가요?',ARRAY['K4-2-u4-X46','K4-2-u4-X47','K4-2-u4-X48']::text[],false,'{"seq":24,"concept":"K4-2-u4-C45","difficulty":4,"kind":"mc","stem":"병훈이의 글에 「둘째, 이름을 쓰면 글씨 연습이 됩니다.」가 들어갔다면 어떻게 따지는 것이 알맞은가요?","options":[{"t":"이름을 써 두자는 의견과 이어지지 않는 이유라서 빼는 것이 좋다","correct":true},{"t":"이유가 셋이 되었으니 글이 더 좋아졌다","mis":"K4-2-u4-X46"},{"t":"나는 이름 쓰기에 찬성하니 이 이유도 알맞다","mis":"K4-2-u4-X47"},{"t":"글에 실렸으니 그대로 믿는다","mis":"K4-2-u4-X48"}],"explanation":["개수가 아니에요.","찬성이어서도 아니에요.","의견과 이어지나요?"],"asset":{"type":"passage","lines":["1 4학년 친구들, 안녕하세요? 저는 병훈입니다.","2 교실 뒤 상자에는 주인을 찾지 못한 물건이 쌓여 있습니다.","   지난주에도 줄넘기와 물병이 그대로 남았습니다.","3 저는 우리가 쓰는 물건에 이름을 써 두면 좋겠다고 생각합니다.","4 첫째, 이름이 적혀 있으면 물건을 주운 친구가 바로 돌려줄 수 있습니다.","5 둘째, 이름을 쓰는 동안 이것이 내 물건이라는 것을 한 번 더 생각하게 됩니다.","6 작은 일이지만 물건을 찾느라 쓰는 시간을 모두가 아낄 수 있습니다.","7 오늘 집에 가서 필통과 물병부터 살펴보면 어떨까요?"],"title":"병훈이의 글 「함께 쓰는 물건에 이름을 써 주세요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_c#25','kor',4,2,'u4','','g4_2_kor_u4_review_c','unit_review','K4-2-u4-C6',4,'essay','teacher','이 단원에서 세 번 만난 물음 「질문을 많이 만들수록 잘 읽은 것일까?」에 대한 내 생각을 쓰고, 그렇게 생각한 까닭을 예를 들어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u4-C6","difficulty":4,"kind":"essay","stem":"이 단원에서 세 번 만난 물음 「질문을 많이 만들수록 잘 읽은 것일까?」에 대한 내 생각을 쓰고, 그렇게 생각한 까닭을 예를 들어 쓰세요.","answer_guide":{"answer":"예: 그렇지 않다. 질문은 개수를 채우는 것이 아니라 그 글과 그때의 나에게 필요한 것을 골라 쓰는 것이기 때문이다. 예를 들어 짧은 안내문을 읽을 때는 「무엇을 알려 주는가?」 하나로 충분하지만, 조사하려고 두꺼운 책을 읽을 때는 중요한 문장 찾기와 간추리기가 더 필요하다.","scoring_points":["「그렇지 않다」는 생각을 밝혔는가","질문은 골라 쓰는 것이라는 까닭을 썼는가","글이나 목적에 따라 질문이 달라지는 예를 들었는가"]},"explanation":["개수가 아니에요.","골라 써요.","예를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#1','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C5',1,'mc','auto','㉯를 읽을 때 떠올리기 알맞은 질문은 무엇인가요?',ARRAY['K4-2-u4-X05']::text[],false,'{"seq":1,"concept":"K4-2-u4-C5","difficulty":1,"kind":"mc","stem":"㉯를 읽을 때 떠올리기 알맞은 질문은 무엇인가요?","options":[{"t":"무엇을 어떻게 알려 주고 있나?","correct":true},{"t":"가장 오래 마음에 남는 장면은 어디인가?","mis":"K4-2-u4-X05"},{"t":"글쓴이의 의견을 받치는 이유가 알맞은가?","mis":"K4-2-u4-X05"},{"t":"그네는 누가 탔을까?","mis":"K4-2-u4-X05"}],"explanation":["㉯는 개미 이야기예요.","까닭을 알려 주는 글이에요.","무엇을 알려 주나 물어요."],"asset":{"type":"passage","lines":["㉮ 「빈 그네」 — 아이들이 다 돌아간 저녁, 그네 하나가 아직 흔들린다","㉯ 「개미가 줄지어 가는 까닭」 — 먹이를 찾은 개미는 땅에 냄새를 남긴다","㉰ 「다 쓴 종이는 이면지 상자에 모아요」 — 저는 종이를 모으자고 생각합니다"],"title":"세 글의 첫 토막"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#2','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C54',1,'mc','auto','시 「받아쓰기」에서 시험지를 받으면 어떻게 된다고 했나요?',ARRAY['K4-2-u4-X57']::text[],false,'{"seq":2,"concept":"K4-2-u4-C54","difficulty":1,"kind":"mc","stem":"시 「받아쓰기」에서 시험지를 받으면 어떻게 된다고 했나요?","options":[{"t":"아는 글자도 갑자기 낯설어진다","correct":true},{"t":"모르는 글자가 갑자기 생각난다","mis":"K4-2-u4-X57"},{"t":"글자가 또박또박 잘 써진다","mis":"K4-2-u4-X57"},{"t":"연필이 저절로 움직인다","mis":"K4-2-u4-X57"}],"explanation":["첫 두 줄을 봐요.","아는 글자인데도요.","낯설어져요."],"asset":{"type":"passage","lines":["시험지를 받으면","아는 글자도 갑자기 낯설어진다","집에서는 술술 썼는데","연필 끝에서만 글자가 자꾸 미끄러진다","집에 돌아와 다시 써 보면","아무 일도 없었다는 듯","또박또박 잘 써진다"],"title":"시 「받아쓰기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#3','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C26',1,'mc','auto','읽기 과정을 나눈 것으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X30']::text[],false,'{"seq":3,"concept":"K4-2-u4-C26","difficulty":1,"kind":"mc","stem":"읽기 과정을 나눈 것으로 알맞은 것은 무엇인가요?","options":[{"t":"읽기 전 · 읽기 중 · 읽기 후","correct":true},{"t":"제목 · 글쓴이 · 쪽수","mis":"K4-2-u4-X30"},{"t":"처음 · 끝 · 다시 처음","mis":"K4-2-u4-X30"},{"t":"눈 · 입 · 손","mis":"K4-2-u4-X30"}],"explanation":["읽는 때를 나눠요.","펴기 전, 읽는 동안, 다 읽고","전 · 중 · 후예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#4','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C36',1,'mc','auto','「여럿이 한데 마구 섞이다」는 뜻의 낱말은 무엇인가요?',ARRAY['K4-2-u4-X36','K4-2-u4-X19']::text[],false,'{"seq":4,"concept":"K4-2-u4-C36","difficulty":1,"kind":"mc","stem":"「여럿이 한데 마구 섞이다」는 뜻의 낱말은 무엇인가요?","options":[{"t":"뒤섞이다","correct":true},{"t":"스며들다","mis":"K4-2-u4-X36"},{"t":"머뭇거리다","mis":"K4-2-u4-X19"},{"t":"우물쭈물하다","mis":"K4-2-u4-X19"}],"explanation":["똥에 양분이 어떻게 있었나요?","한데 마구 섞였어요.","‘뒤섞이다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#5','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C55',1,'mc','auto','「이 우산은 만 원이세요.」를 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u4-X59','K4-2-u4-X53']::text[],false,'{"seq":5,"concept":"K4-2-u4-C55","difficulty":1,"kind":"mc","stem":"「이 우산은 만 원이세요.」를 바르게 고친 것은 무엇인가요?","options":[{"t":"「이 우산은 만 원이에요.」","correct":true},{"t":"「이 우산께서는 만 원이세요.」","mis":"K4-2-u4-X59"},{"t":"「이 우산은 만 원이시옵니다.」","mis":"K4-2-u4-X53"},{"t":"「이 우산은 만 원이셔요.」","mis":"K4-2-u4-X53"}],"explanation":["우산과 값은 사물이에요.","「-시-」를 빼요.","「이에요」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#6','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C57',1,'mc','auto','「체크하다」를 바꿔 쓸 우리말은 무엇인가요?',ARRAY['K4-2-u4-X55']::text[],false,'{"seq":6,"concept":"K4-2-u4-C57","difficulty":1,"kind":"mc","stem":"「체크하다」를 바꿔 쓸 우리말은 무엇인가요?","options":[{"t":"표시하다","correct":true},{"t":"쪽지하다","mis":"K4-2-u4-X55"},{"t":"일정하다","mis":"K4-2-u4-X55"},{"t":"외우다","mis":"K4-2-u4-X55"}],"explanation":["맞는 곳에 ✓ 해요.","표시를 해요.","‘표시하다’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#7','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C58',1,'mc','auto','겹받침 ㄻ을 쓸 때 알맞은 모양은 무엇인가요?',ARRAY['K4-2-u4-X56']::text[],false,'{"seq":7,"concept":"K4-2-u4-C58","difficulty":1,"kind":"mc","stem":"겹받침 ㄻ을 쓸 때 알맞은 모양은 무엇인가요?","options":[{"t":"ㄹ과 ㅁ을 같은 크기로 나란히 쓴다","correct":true},{"t":"ㅁ을 ㄹ 아래에 겹쳐 쓴다","mis":"K4-2-u4-X56"},{"t":"ㄹ만 크게 쓰고 ㅁ은 점처럼 작게 쓴다","mis":"K4-2-u4-X56"},{"t":"ㅁ 하나만 쓴다","mis":"K4-2-u4-X56"}],"explanation":["두 자음이 나란히 앉아요.","크기도 같게요.","나란히 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#8','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C7',1,'mc','auto','같은 시를 읽어도 떠오르는 장면이 사람마다 다른 까닭은 무엇인가요?',ARRAY['K4-2-u4-X08','K4-2-u4-X14']::text[],false,'{"seq":8,"concept":"K4-2-u4-C7","difficulty":1,"kind":"mc","stem":"같은 시를 읽어도 떠오르는 장면이 사람마다 다른 까닭은 무엇인가요?","options":[{"t":"시는 짧아서 읽는 사람이 채워 넣을 자리가 많기 때문에","correct":true},{"t":"시를 쓴 사람이 정답 장면을 숨겨 두었기 때문에","mis":"K4-2-u4-X08"},{"t":"누군가 잘못 읽었기 때문에","mis":"K4-2-u4-X08"},{"t":"시에는 아무 뜻이 없기 때문에","mis":"K4-2-u4-X14"}],"explanation":["시는 짧아요.","읽는 사람이 채워요.","그래서 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#9','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C13',2,'mc','auto','서로 다른 느낌을 나누면 좋은 점은 무엇인가요?',ARRAY['K4-2-u4-X16','K4-2-u4-X12','K4-2-u4-X14']::text[],false,'{"seq":9,"concept":"K4-2-u4-C13","difficulty":2,"kind":"mc","stem":"서로 다른 느낌을 나누면 좋은 점은 무엇인가요?","options":[{"t":"내가 못 본 면을 볼 수 있어 작품을 넓게 볼 수 있다","correct":true},{"t":"모두 같은 느낌으로 맞출 수 있다","mis":"K4-2-u4-X16"},{"t":"누가 맞았는지 가릴 수 있다","mis":"K4-2-u4-X12"},{"t":"나누면 느낌을 말하지 않아도 된다","mis":"K4-2-u4-X14"}],"explanation":["맞추는 게 아니에요.","가리는 것도 아니에요.","넓게 볼 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#10','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C12',2,'ox','auto','「가방」을 길게 늘여 「가아아아방」이라고 하면 뒤에 다른 낱말이 숨어 있어요.',ARRAY['K4-2-u4-X15']::text[],false,'{"seq":10,"concept":"K4-2-u4-C12","difficulty":2,"kind":"ox","stem":"「가방」을 길게 늘여 「가아아아방」이라고 하면 뒤에 다른 낱말이 숨어 있어요.","answer":"X","reason_options":[{"t":"뒤에 남는 소리 「아방」은 낱말이 아니기 때문에","correct":true},{"t":"어떤 낱말이든 늘이면 숨은 낱말이 나타나기 때문에","mis":"K4-2-u4-X15"}],"mis":"K4-2-u4-X15","explanation":["「아방」을 들어 봐요.","낱말이 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#11','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C19',2,'ox','auto','형준이 역할은 빠르고 큰 목소리로 해야 인물에 어울려요.',ARRAY['K4-2-u4-X25']::text[],false,'{"seq":11,"concept":"K4-2-u4-C19","difficulty":2,"kind":"ox","stem":"형준이 역할은 빠르고 큰 목소리로 해야 인물에 어울려요.","answer":"X","reason_options":[{"t":"형준이는 하고 싶은 말을 삼키는 인물이라 말끝이 흐려지고 느려지기 때문에","correct":true},{"t":"역할놀이는 목소리가 커야 잘한 것이기 때문에","mis":"K4-2-u4-X25"}],"mis":"K4-2-u4-X25","explanation":["형준이는 손을 내렸어요.","말을 삼켰어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#12','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C20',2,'mc','auto','역할놀이 장면을 고른 까닭을 알맞게 말한 것은 무엇인가요?',ARRAY['K4-2-u4-X23','K4-2-u4-X24']::text[],false,'{"seq":12,"concept":"K4-2-u4-C20","difficulty":2,"kind":"mc","stem":"역할놀이 장면을 고른 까닭을 알맞게 말한 것은 무엇인가요?","options":[{"t":"「형준이가 처음 말하는 장면을 골랐어. 용기를 낸 마음을 나타내고 싶었거든.」","correct":true},{"t":"「이 장면이 정답이라서 골랐어.」","mis":"K4-2-u4-X23"},{"t":"「가장 웃길 것 같아서 골랐어.」","mis":"K4-2-u4-X24"},{"t":"「아무 장면이나 골랐어. 까닭은 없어.」","mis":"K4-2-u4-X23"}],"explanation":["정답 장면은 없어요.","그래도 까닭은 말해요.","나타내고 싶은 마음을 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#13','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C30',2,'mc','auto','읽기 전에 하는 질문을 고르는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X31','K4-2-u4-X06','K4-2-u4-X32']::text[],false,'{"seq":13,"concept":"K4-2-u4-C30","difficulty":2,"kind":"mc","stem":"읽기 전에 하는 질문을 고르는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"글을 읽지 않은 상태에서도 답할 수 있는 질문인가","correct":true},{"t":"글을 끝까지 읽어야 답할 수 있는 질문인가","mis":"K4-2-u4-X31"},{"t":"질문이 길고 어려운가","mis":"K4-2-u4-X06"},{"t":"글의 줄 수를 묻는 질문인가","mis":"K4-2-u4-X32"}],"explanation":["아직 읽지 않았어요.","그래도 답할 수 있어야 해요.","지금 답할 수 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#14','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C44',2,'mc','auto','은재의 글에서 「우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.」는 무엇인가요?',ARRAY['K4-2-u4-X44','K4-2-u4-X45']::text[],false,'{"seq":14,"concept":"K4-2-u4-C44","difficulty":2,"kind":"mc","stem":"은재의 글에서 「우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.」는 무엇인가요?","options":[{"t":"문제 상황","correct":true},{"t":"글쓴이의 의견","mis":"K4-2-u4-X44"},{"t":"의견을 받치는 이유","mis":"K4-2-u4-X45"},{"t":"실천을 권하는 말","mis":"K4-2-u4-X44"}],"explanation":["지금 어떤 일이 있나요?","불편한 일을 알려요.","문제 상황이에요."],"asset":{"type":"passage","lines":["1 안녕하세요? 저는 4학년 은재입니다.","2 우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.","3 저는 한 면만 쓴 종이를 교실 뒤 이면지 상자에 모으면 좋겠다고 생각합니다.","4 첫째, 연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 됩니다.","5 둘째, 버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다.","6 내일부터 종이를 버리기 전에 뒷면을 한 번 살펴보면 어떨까요?"],"title":"은재의 글 「다 쓴 종이는 이면지 상자에 모아요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#15','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C37',2,'mc','auto','중심 문장을 찾는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X37','K4-2-u4-X39']::text[],false,'{"seq":15,"concept":"K4-2-u4-C37","difficulty":2,"kind":"mc","stem":"중심 문장을 찾는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"그 문장이 없으면 그 부분의 뜻이 통하지 않는지 살핀다","correct":true},{"t":"가장 긴 문장을 고른다","mis":"K4-2-u4-X37"},{"t":"가장 재미있는 문장을 고른다","mis":"K4-2-u4-X39"},{"t":"언제나 첫 문장을 고른다","mis":"K4-2-u4-X37"}],"explanation":["길이가 아니에요.","자리도 아니에요.","없으면 안 되는 문장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#16','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C53',2,'mc','auto','사다리를 타고 닿은 질문에 답을 못 하겠을 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X51','K4-2-u4-X52']::text[],false,'{"seq":16,"concept":"K4-2-u4-C53","difficulty":2,"kind":"mc","stem":"사다리를 타고 닿은 질문에 답을 못 하겠을 때 알맞은 것은 무엇인가요?","options":[{"t":"그 자리를 다시 읽을 자리로 삼고 글을 펴서 찾아본다","correct":true},{"t":"진 것이니 놀이에서 빠진다","mis":"K4-2-u4-X51"},{"t":"아무 말이나 빨리 답한다","mis":"K4-2-u4-X52"},{"t":"그 질문 카드를 몰래 버린다","mis":"K4-2-u4-X51"}],"explanation":["지는 게 아니에요.","아무 말이나도 아니에요.","다시 읽을 자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#17','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C6',3,'mc','auto','이 단원에서 세 번 만난 물음 「읽기 과정을 되돌아본다는 것」에 대한 알맞은 답은 무엇인가요?',ARRAY['K4-2-u4-X06','K4-2-u4-X07','K4-2-u4-X04']::text[],false,'{"seq":17,"concept":"K4-2-u4-C6","difficulty":3,"kind":"mc","stem":"이 단원에서 세 번 만난 물음 「읽기 과정을 되돌아본다는 것」에 대한 알맞은 답은 무엇인가요?","options":[{"t":"글과 상황에 맞게 알맞은 질문을 골라 쓴다","correct":true},{"t":"질문을 많이 만들수록 잘 읽은 것이다","mis":"K4-2-u4-X06"},{"t":"읽기 전·중·후 활동을 빠짐없이 다 해야 한다","mis":"K4-2-u4-X07"},{"t":"잘 읽는 사람은 질문이 필요 없다","mis":"K4-2-u4-X04"}],"explanation":["「많을수록」 ✗","「빠짐없이 다」 ✗","골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#18','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C45',3,'mc','auto','「학급 문고는 쉬는 시간에만 빌리자」는 의견을 받치기에 알맞지 「않은」 이유는 무엇인가요?',ARRAY['K4-2-u4-X46','K4-2-u4-X47']::text[],false,'{"seq":18,"concept":"K4-2-u4-C45","difficulty":3,"kind":"mc","stem":"「학급 문고는 쉬는 시간에만 빌리자」는 의견을 받치기에 알맞지 「않은」 이유는 무엇인가요?","options":[{"t":"책 표지가 알록달록해서 보기 좋다","correct":true},{"t":"수업 시간에 책을 찾느라 소란해지지 않는다","mis":"K4-2-u4-X46"},{"t":"쉬는 시간에 차례를 지켜 천천히 고를 수 있다","mis":"K4-2-u4-X46"},{"t":"빌린 책을 적는 때가 정해져 빠뜨리지 않는다","mis":"K4-2-u4-X47"}],"explanation":["그 의견대로 하면 좋은 점인가요?","표지 이야기는 달라요.","의견과 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#19','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C47',3,'error','auto','의견 글을 읽고 견주는 방법을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u4-X48','K4-2-u4-X49']::text[],false,'{"seq":19,"concept":"K4-2-u4-C47","difficulty":3,"kind":"error","stem":"의견 글을 읽고 견주는 방법을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「글쓴이와 생각이 다르면 내 생각을 버려야 해.」","correct":true,"mis_target":"K4-2-u4-X48"},{"t":"친구 나 — 「같은 곳과 다른 곳을 함께 찾아야 해.」","mis":"K4-2-u4-X49"},{"t":"친구 다 — 「다르면 내 이유를 마련하면 돼.」","mis":"K4-2-u4-X49"}],"explanation":["견주기는 버리기가 아니에요.","같은 곳·다른 곳을 찾아요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#20','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C49',3,'mc','auto','점검표를 채우는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X40','K4-2-u4-X41']::text[],false,'{"seq":20,"concept":"K4-2-u4-C49","difficulty":3,"kind":"mc","stem":"점검표를 채우는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"내가 어디를 다시 읽어야 할지 스스로 알기 위해","correct":true},{"t":"선생님께 칭찬받으려고","mis":"K4-2-u4-X40"},{"t":"빨리 끝내고 쉬려고","mis":"K4-2-u4-X41"},{"t":"친구보다 「예」를 더 많이 받으려고","mis":"K4-2-u4-X40"}],"explanation":["누구를 위한 표인가요?","나를 위한 표예요.","다시 읽을 곳을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#21','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C23',3,'mc','auto','「말하지 못한 말」을 읽고 자신과 관련짓는 질문으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X28','K4-2-u4-X32']::text[],false,'{"seq":21,"concept":"K4-2-u4-C23","difficulty":3,"kind":"mc","stem":"「말하지 못한 말」을 읽고 자신과 관련짓는 질문으로 알맞은 것은 무엇인가요?","options":[{"t":"내가 수지라면 그때 어떻게 말했을까요?","correct":true},{"t":"수지는 무슨 색 옷을 입었을까요?","mis":"K4-2-u4-X28"},{"t":"학예회는 어느 학교에서 했을까요?","mis":"K4-2-u4-X28"},{"t":"이 이야기는 모두 몇 줄일까요?","mis":"K4-2-u4-X32"}],"explanation":["작품과 이어져요.","나와 관련지어요.","내가 수지라면?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#22','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C51',3,'mc','auto','친구들의 발표를 듣고 마무리할 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u4-X50','K4-2-u4-X12']::text[],false,'{"seq":22,"concept":"K4-2-u4-C51","difficulty":3,"kind":"mc","stem":"친구들의 발표를 듣고 마무리할 때 알맞은 것은 무엇인가요?","options":[{"t":"잘한 부분을 서로 칭찬하고 격려한다","correct":true},{"t":"가장 잘한 사람 한 명만 뽑는다","mis":"K4-2-u4-X50"},{"t":"배운 방법을 쓰지 않은 친구를 고친다","mis":"K4-2-u4-X50"},{"t":"나와 다른 방법은 틀렸다고 말한다","mis":"K4-2-u4-X12"}],"explanation":["뽑지 않아요.","고치지도 않아요.","칭찬하고 격려해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#23','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C9',4,'mc','auto','같은 시를 읽고 장면이 다르게 떠오른 친구들에게 선생님이 「다른 것은 틀린 것이 아니에요.」라고 하셨어요. 이 말에 가장 알맞게 이어지는 생각은 무엇인가요?',ARRAY['K4-2-u4-X14','K4-2-u4-X16','K4-2-u4-X10']::text[],false,'{"seq":23,"concept":"K4-2-u4-C9","difficulty":4,"kind":"mc","stem":"같은 시를 읽고 장면이 다르게 떠오른 친구들에게 선생님이 「다른 것은 틀린 것이 아니에요.」라고 하셨어요. 이 말에 가장 알맞게 이어지는 생각은 무엇인가요?","options":[{"t":"그래도 느낌을 말할 때는 시의 어느 줄에서 왔는지 까닭을 들어야 한다","correct":true},{"t":"그러니 아무렇게나 말해도 된다","mis":"K4-2-u4-X14"},{"t":"그러니 느낌을 나눌 필요가 없다","mis":"K4-2-u4-X16"},{"t":"그러니 가장 많은 쪽 느낌을 따르면 된다","mis":"K4-2-u4-X10"}],"explanation":["다를 수 있어요.","하지만 아무렇게나는 아니에요.","까닭을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#24','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C48',4,'mc','auto','은재의 글을 읽기 전·중·후에 떠올릴 질문을 바르게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u4-X30','K4-2-u4-X05']::text[],false,'{"seq":24,"concept":"K4-2-u4-C48","difficulty":4,"kind":"mc","stem":"은재의 글을 읽기 전·중·후에 떠올릴 질문을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"전 — 무엇을 하자는 글일까? / 중 — 이유가 의견과 이어지는가? / 후 — 내 생각과 어디가 같고 다른가?","correct":true},{"t":"전 — 이유가 의견과 이어지는가? / 중 — 무엇을 하자는 글일까? / 후 — 글이 몇 줄인가?","mis":"K4-2-u4-X30"},{"t":"전 — 마음에 남는 장면은? / 중 — 인물의 말투는? / 후 — 누가 이겼나?","mis":"K4-2-u4-X05"},{"t":"전 — 내 생각과 어디가 다른가? / 중 — 제목은 무엇인가? / 후 — 무엇을 하자는 글일까?","mis":"K4-2-u4-X30"}],"explanation":["전 — 제목으로 짐작","중 — 의견과 이유","후 — 내 생각과 견주기"],"asset":{"type":"passage","lines":["1 안녕하세요? 저는 4학년 은재입니다.","2 우리 반 쓰레기통에는 한 면만 쓴 종이가 자주 버려져 있습니다.","3 저는 한 면만 쓴 종이를 교실 뒤 이면지 상자에 모으면 좋겠다고 생각합니다.","4 첫째, 연습할 종이가 필요할 때 새 종이를 꺼내지 않아도 됩니다.","5 둘째, 버리는 종이가 줄어 쓰레기통이 금방 차지 않습니다.","6 내일부터 종이를 버리기 전에 뒷면을 한 번 살펴보면 어떨까요?"],"title":"은재의 글 「다 쓴 종이는 이면지 상자에 모아요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u4_review_d#25','kor',4,2,'u4','','g4_2_kor_u4_review_d','unit_review','K4-2-u4-C55',4,'essay','teacher','「손님, 이 가방은 이만 원이세요.」와 「저희 나라에는 산이 많아요.」를 바르게 고쳐 쓰고, 고친 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u4-C55","difficulty":4,"kind":"essay","stem":"「손님, 이 가방은 이만 원이세요.」와 「저희 나라에는 산이 많아요.」를 바르게 고쳐 쓰고, 고친 까닭을 쓰세요.","answer_guide":{"answer":"예: 「손님, 이 가방은 이만 원이에요.」로 고친다. 가방과 값은 사물이라 「-시-」를 붙여 높이지 않기 때문이다. 「우리나라에는 산이 많아요.」로 고친다. 나라는 남의 나라보다 낮출 수 없어 「우리나라」라고 하기 때문이다.","scoring_points":["첫 문장에서 사물(값)을 높이지 않게 고쳤는가","둘째 문장을 「우리나라」로 고쳤는가","각각 고친 까닭을 썼는가"]},"explanation":["높일 사람은 손님이에요.","값은 높이지 않아요.","나라는 낮추지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
